contenu:
//Indicator that policy is still active
if (incidence_mult_sa(t) > SMALL_DOUBLE)
return 1.0;
return 0.0;
//NB 24/11/24 - CR483 - Column added to measure number of policies being calculated

/* Age at the start of the next period - used as a table lookup */
if (t < commence_period_w + 1 || t> maturity_period_last_w)
return 0.0;
return age_exact_b(t+1);
/* DC 31/08/17 - CR166 - built column to serve as a lookup for gimla_antiselfac_BEbasis
SK 05/08/21 - CR356 - Adding time guard for gen2 engine
*/

//used for calculation in gimla_feff_res_e
double years_to_ret = (1.0 + maturity_period_last_w - t) / pv_period_im;
return xint(age_exact_b(t) + years_to_ret);
/*
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
*/

/* Age at last premium increase date */
int xx = age_exact_issue_scal;
int x1 = xint(age_exact_b_prem(t));
return xx+prem_ren_yrs * int((x1-xx)/prem_ren_yrs);
/*
OS 06/11/17 - CR159 - Renamed the column from briut_vectors_g, as will now be using it for
other products
SK 16/02/22 - CR354 - Changing 'age_exact_issue' to 'age_exact_issue_scal' and 'age_exact_b'
to 'age_exact_b_prem'
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Returns the percentage annuitising but with anti selection for cash0 */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!gimla_prod_ind || prod_code == ANPY)
return NO_AVG;
if (gimla_retagedistr_use == 0) // not using retirement age distribution
return annuity_perc_frozen(t-1) * gimla_tur1(maturity_period_last_w+1)
+ (1.0 - annuity_perc_frozen(t-1)) * cash0_percofnonfrozen
* gimla_antiselfac_bebasis *
gimla_tur0(maturity_period_last_w+1) ;
return annuity_perc_frozen(t-1) * gimla_tur1(t+1)
+ (1.0 - annuity_perc_frozen(t-1)) * cash0_percofnonfrozen
* gimla_antiselfac_bebasis * gimla_tur0(t+1) ;
/*
OS 13/03/17 - Created column.
DC 27/08/17 - CR166 - anti-selection factor is now taken on the best-estimate basis
GR 21/01/19 - CR261 Changed gimla prod classification
SK 05/08/21 - CR356 - Adding time guard for gen2 engine
*/

/* Returns the best estimate cashflow (active + gimla)*/
if (t < commence_period_w+1)
return NO_AVG;
return be_cf_pre_neto(t) + be_cf_gimla(t);
/*
NB 12/02/24 - CR420 - Added column
*/

/* BE cashflow in period from post-retirement cashflows */
if (t < maturity_period_first_w || !gimla_prod_ind || contract_boundary_indicator)
return NO_AVG;
return sm_maslul->be_cf_gimla(t);
/*
DC 03/10/17 - Created column
NB 27/11/24 - CR490 - Add condition for contract boundaries
*/

/* BE cashflow in period from post-retirement cashflows */
if (t < maturity_period_first_w || !gimla_prod_ind )
return NO_AVG;
return sm_maslul->be_cf_gimla(t);
/*
NB 27/11/24 - CR490 - Added column
*/

/* Returns the pre-retirement best estimate cashflow, without reinsurance */
if (t < commence_period_w+1 || t > maturity_period_last_w )
return NO_AVG;
return - tot_prem_paid(t)
//claims pre maturity
+ claims_paid(t) + suppliers_claims_expense(t)
+ pup_clm_paid(t) + suppliers_pup_claims_expense(t)
- gtee_cost_equ(t)
+ tot_surrs(t) + tot_mats(t)
//expenses and commissions pre maturity
+ expenses_perc_prem (t) + expenses_per_pol (t) + as_exp(t) + pup_expenses_per_pol(t)
+ expenses_res(t) + expenses_claims(t)
+ pup_expenses_claims(t)
+ tot_comm_paid(t) - lookthrough_adj(t);
/*
NB 26/11/24 - CR490 - Added column to compare to be_cf_pre_neto
*/

/*Weighted BE value for hetz calculation*/
if (t < commence_period_w+1 )
return NO_AVG;
if (run_type != "SII")
return (be_neto(t) * (1. - inv_pct_hetz_full)
+ be_neto_taarif(t) * inv_pct_hetz_full)
* inv_pct_hetz;
return (be_neto_maazan(t) * (1. - inv_pct_hetz_full)
+ be_neto_taarif(t) * inv_pct_hetz_full)
* inv_pct_hetz;
/*
NB 12/02/24 - CR420 - Added column
*/

/* Returns the final BE (discounted by hetz rate) including both pre and post retirement periods
and reinsurance */
if (t < commence_period_w+1 || t >= model_end_period)
return NO_AVG;
return (be_cf(t) + be_neto_taarif(t+1))
*v_factor_taarif(t);
/*
NB 12/02/24 - CR420 - Added column
*/

/* Calendar month at the end of the period */
int month = (valn_month + t * (12/pv_period_im)) % 12;
if (month == 0)
return 12;
return month;
/*
DC 01/01/19 - CR250 - created column
*/

if (!rfr_curve_end_period)
return valn_month;
if(t <= int_period_adjust)
return valn_month;
return cal_month(int_period_adjust);
/*
NB 10/06/24 - CR466 - Added column for look up
*/

/* Calendar year in the period */
if (t==0)
return valn_year;
if (t<0) {
if (cal_month(t) == 12)
return cal_year(t+1) - 1;
return cal_year(t+1);
}
// t>0
if (cal_month(t-1) == 12)
return cal_year(t-1) + 1;
return cal_year(t-1);
/*
DC 01/01/19 - renamed from valn_yr_minus1_plus_proj_yr.  Rewrote code in terms of cal_year.
*/

if (!rfr_curve_end_period)
return valn_year;
if(t <= int_period_adjust)
return valn_year;
return cal_year(int_period_adjust);
/*
NB 10/06/24 - CR466 - Added column for look up
*/

/* Outstanding loan capital amount on risk mashcanta policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if ((prod_code_sub != RMASH_C) && (prod_code_sub != RMASH_F))
return 0.0;
if (t <= 1)
return sum_assured_basic_b(1);
// t > 1
if (prod_code_sub == RMASH_C ) {
double period = pv_period_im * (maturity_age - age_exact_b(1)) + 1;
return capt_outstanding(t-1) - payment_rskm * v_fac_rm(period) / v_fac_rm(t-1);
}
if (prod_code_sub == RMASH_F)
return capt_outstanding(t-1) - payment_rskm;
return 0.0;
/* DC 22/12/14 - Tidied formula
OS 01/08/16 - Changed PROD_FUND_NAME to be enumerated value.
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
DC 30/01/17 - Reordered conditions of formula for efficiency
OS 06/11/17 - CR159 - Changed condition to match the new hierarchy in Risk products
GA 28/09/23 - CR354 - Adding extra quarter to the period calculation of 'RMASH_C'
*/

/* Returns the total weighted Coverage units for the period - multiplied by conversion factors
If we choose to release the CSM by UNdiscounted CUs, this is the column of the CU "cashflow"
that we need to provide to the accounting system.
*/
if (t < commence_period_w+1)
return NO_AVG;
return cu_savings(t) * cu_conversion_savings
+ cu_risk(t)
* cu_conversion_risk
+ cu_annuity(t) * cu_conversion_annuity;
/* TA 16/08/21 - CR327 Created column
SK 19/05/22 - CR388 - Adjusting the column to be a weighted cu: sum of the coverage unit types
multiplied by the relevant conversion factors
*/

/* Returns the Coverage unit for the annuity period
This column will be used to determine the annuity conversion factor
*/
if (t < commence_period_w)
return NO_AVG;
if (!gimla_prod_ind)
return NO_AVG;
if (t <= maturity_period_first_w)
return NO_AVG;
return sm_maslul->cu_annuity(t);
/* SK 19/05/22 - CR388 - Created column
*/

/* Returns the total coverage units in the period, when expressed in terms of their present value
i.e. a cashflow multiplied by the relevant cumulative v factor in each period.
If we choose to release the CSM by discounted CUs, this is the column of the CU "cashflow" that
we need to provide to the accounting system.
*/
if (t < commence_period_w+1)
return NO_AVG;
return (cu_savings(t) * cu_conversion_savings  + cu_risk(t) * cu_conversion_risk) * v_accm(t)
+ sm_maslul -> cu_discounted_gimla(t);
/* SK 19/05/22 - CR388 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Returns the total reinsurance coverage units in the period, when expressed in terms of their
present value
i.e. a cashflow multiplied by the relevant cumulative v factor in each period.
If we choose to release the CSM by discounted CUs, this is the column of the CU "cashflow" that
we need to provide to the accounting system.
*/
if (t < commence_period_w+1)
return NO_AVG;
return  cu_reins(t) * v_accm(t);
/* SK 11/09/22 - CR377 - Created column
*/

/* PV at time t of future coverage units, weighted by conversion factors */
if (t < commence_period_w+1)
return NO_AVG;
return cu_pv_risk(t)    * cu_conversion_risk
+ cu_pv_savings(t) * cu_conversion_savings
+ cu_pv_annuity(t) * cu_conversion_annuity;
/*
TA 16/08/21 - CR327 Created column
SK 19/05/22 - CR388 - Changing the column to be weighted cu PV
*/

/* PV at time t of future annuity coverage units */
if (t < commence_period_w+1 || !gimla_prod_ind)
return NO_AVG;
if (t > maturity_period_first_w)
return sm_maslul -> cu_pv_annuity(t);
// Before maturity_period_first_w we discount back
return cu_pv_annuity(t+1) * v_factor_locked(t);
/*
SK 19/05/22 - CR388 - Created column
NB 11/06/23 - CR431 - Switched to locked-in discounting
*/

/* PV at time t of future reinsurance coverage units */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
return (cu_reins(t) + cu_pv_reins(t+1))
* v_factor_locked(t);
/*
SK 11/09/22 - CR377 - Created column
NB 11/06/23 - CR431 - Switched to locked-in discounting
*/

/* PV at time t of future risk coverage units */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
return (cu_risk(t) + cu_pv_risk(t+1))
* v_factor_locked(t);
/*
SK 19/05/22 - CR388 - Created column
NB 11/06/23 - CR431 - Switched to locked-in discounting
*/

/* PV at time t of future savings coverage units */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
return (cu_savings(t) + cu_pv_savings(t+1))
* v_factor_locked(t);
/* SK 19/05/22 - CR388 - Created column
NB 11/06/23 - CR431 - Switched to locked-in discounting
*/

/* Returns the reinsurance coverage units for the risk component in the policies
*/
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (run_type != "IFRS") //This column is relevant to IRFS runs only
return NO_AVG;
//Theres different components for LTC and other products. Hence, using local variables is nedded
double reins_pct = 0.0;
double cu_risk_final = 0.0;
if (prod_code == LTC) {
reins_pct = ltc_reins_claims_pct;
if (ltc_reins_pup_ind) //from 2017 treaty, paid up policies are also in the reinsurance
calculations
cu_risk_final =  cu_risk(t);
else
cu_risk_final = cu_risk(t) - ((sum_assured_basic_b(t) * pow(1.0 + claim_infl_rt,
duration_b(t) + 1.0 / pv_period_im - elapsed_years)
* pups_avg_value(t) /
max(sum_assured_init_model, 1.0)) * pups_if_b(t));
}
else { //For other products
reins_pct = reins_risk_pct;
cu_risk_final =  cu_risk(t);
}
/*
The code above, created especially for LTC products. The local variable 'cu_risk_final' will
be used only in the 'IF' statment below.
An assumption has been made - That there's no new business sold for LTC product nor new
treaties signed with reinsurance in the future.
In case we will have new reinsurance treaties with annual renewal, this calculation should
be changed.
*/
if (!nb_ind || treaty_period != 12)
return cu_risk_final * reins_pct * cu_conversion_risk;
/*
When the valuation date is the end of the first quarter, we assume that sales in the 2nd quarter
will be the same as in the first, and so we multiply by 2.
(Hard-coding to avoid incorrect calculation due to zero claims at t=0.)
Once a full valuation year has been completed (and t=0 is no longer referenced), the calculation
progresses recursively.
*/
if (valn_month == 3){
if (t == 1)
return cu_risk(t) * 2.0 * reins_pct * cu_conversion_risk;
if (t == 2)
return (cu_risk(t) + cu_risk(t - 1) * 2.0) * reins_pct * cu_conversion_risk;
if (t == 3)
return (cu_risk(t) + cu_risk(t - 1) + cu_risk(t - 2) * 2.0) * reins_pct *
cu_conversion_risk;
return (cu_risk(t) + cu_risk(t - 1) + cu_risk(t - 2) + cu_risk(t - 3)) * reins_pct *
cu_conversion_risk;
}
// When the valuation date is the end of the 2nd quarter, the value at time 1 is equal to 2
quarters' worth of sales - hence we divide by 2
if (valn_month == 6){
if (t == 1)
return (cu_risk(t) + cu_risk(t) * 1.0/2.0) * reins_pct * cu_conversion_risk;
if (t == 2)
return (cu_risk(t) + cu_risk(t - 1) * 1.0/2.0 + cu_risk(t - 1) * 1.0/2.0) * reins_pct
* cu_conversion_risk;
return (cu_risk(t) + cu_risk(t - 1) * 1.0/2.0 + cu_risk(t - 2) * 1.0/2.0) * reins_pct *
cu_conversion_risk;
}
// When the valuation date is the end of the 3rd quarter, the value at time 1 is equal to 3
quarters' worth of sales - hence we divide by 3
if (valn_month == 9){
if (t == 1)
return (cu_risk(t) + cu_risk(t) * 1.0/3.0) * reins_pct * cu_conversion_risk;
return (cu_risk(t) + cu_risk(t - 1) * 1.0/3.0) * reins_pct * cu_conversion_risk;
}
// When the valuation date is the end of the 4th quarter, the reinsurance contract is due for
renewal and so there is no need to assume future sales
return cu_risk(t) * reins_pct * cu_conversion_risk;
/*
SK 11/09/22 - CR377 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
SK 26/06/24 - CR423 - Correcting the CU for reinsurance in LTC covers - Distinguish between
active and pup
*/

/* Returns the Coverage unit for the risk component in the policies
This column will be used to determine the risk conversion factor
*/
if (t < commence_period_w+1)
return NO_AVG;
if (t == 0)
return cu_risk(t+1);
if (t > maturity_period_last_w)
return NO_AVG;
if (klassi_prod_ind && t > maturity_period_w)
return NO_AVG;
if (prod_code == RISK || prod_code == RMASH || prod_code == DD ||
prod_code == PERS_ACC || prod_code == ADIS)
return sum_assd_if_b(t);
// For health, the weighting comes through via the conversion table.  Here we take just the
survivorship element.
if (prod_code == HO)
return poli_if_b(t);
// For savings we are looking only at the pre retirement period
if (savings_prod_ind || klassi_prod_ind)
return sar(t);
// For PHI it's monthly payment * number of payments * survivorship
if (prod_code == PHI)
return sum_assured_basic_b(t) * (phi_vectors_clm_durs + phi_franchiza_mths) * poli_if_b(t);
// For LTC we need to take both active part and pup part
if (prod_code == LTC) {
if(!(sum_assured_init_model < SMALL_DOUBLE))
//Active part - sum assured including bonus * survivorship
return max((sum_assured_basic_b(t) + min((bonus_b(t-1) + bonus_b(t)) / 2.0 +
ltc_migdal_part * sum_assured_basic_b(t),0.0)),0.0) * poli_if_b(t)
//Paid-up part - sum assured * paid-up survivorship
+ (sum_assured_basic_b(t) * pow(1.0 + claim_infl_rt, duration_b(t) + 1.0 /
pv_period_im - elapsed_years)
* pups_avg_value(t) / sum_assured_init_model) * pups_if_b(t);
}
//Other products
return NO_AVG;
/*
SK 19/05/22 - CR388 - Created column
SK 18/02/24 - CR470 - Returning for t=0 the value of t=1
NB 31/12/23 - CR349 - Zeroed out after maturity for Klassi, prod_code condition replaced
with klassi_prod_ind
SK 26/06/24 - CR423 - Adding the "ltc_migdal_part" in case of malus, like we do in claims
*/

/* Returns the Coverage unit for the savings portion
This column will be used to determine the savings conversion factor
*/
if (t < commence_period_w+1)
return NO_AVG;
if (t == 0)
return cu_savings(t+1);
if (t > maturity_period_last_w)
return NO_AVG;
// First step - we are looking only at the pre retirement period for saving
if (savings_prod_ind || klassi_prod_ind)
return as_res_b(t) + res_bal_b(t) + pup_res_bal_b(t);
//Other products
return NO_AVG;
/*
SK 19/05/22 - CR388 - Created column
SK 18/02/24 - CR470 - Returning for t=0 the value of t=1
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
*/

/* Sum of future coverage units, for use if we are releasing the CSM by UNdiscounted CUs */
if (t < commence_period_w+1)
return NO_AVG;
if (t > model_end_period)
return 0.0;
return cu_sum(t+1) + cu(t);
/* TA 16/08/21 - CR327 - Created column
SK 19/05/22 - CR388 - Tidied formula
*/

/* Sum of future reinsurance coverage units, for use if we are releasing the CSM by UNdiscounted
CUs */
if (t < commence_period_w+1)
return NO_AVG;
if (t > model_end_period)
return 0.0;
return cu_sum_reins(t+1) + cu_reins(t);
/* SK 11/09/22 - CR377 - Created column
*/

/* Calculates the investment income on fefferman reserves pre maturity */
if (t < commence_period_w+1 || t > maturity_period_last_w || !gimla_prod_ind)
return NO_AVG;
return gimla_feff_res_e_pre(t-1) * inv_ret_gross_hetz_incl_pre(t);
/*
OS 01/01/17 - Created column. Calculates the investment income on fefferman reserves pre
maturity.
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Rewrote initial condition
*/

//Lookup column key for lx and qx retirement rates
if (!savings_prod_ind && !klassi_prod_ind)
return 0.0;
if (savings_prod_ind)
return explicit_retage;
if ((klassi_nispach == 60 || klassi_nispach == 61) && abs(cash0_amt_e(0) + cash1_amt_e(0)) >
SMALL_DOUBLE) //Add double condition for policies
return klassi_nispach;
//Klassi without nispach
if (t < maturity_period_w)
return 10;
//After maturity
return 20;
/*
NB 07/11/23 - CR349 - Added lookup field for retirement rates, instead of explict_retage
*/

/*Calculates the excess hetz, based on the weighted BE value and the difference between the earned
rate and the RF rate*/
if (t < commence_period_w+1 )
return NO_AVG;
double rate =  inv_gross_hetz - inv_ret_gross_preret;
if(inv_gross_hetz > 1.0 || inv_ret_gross_preret > 1.0)
throw("The investment return is greater than 100%; please check the investment rate
table.");
double rate2 = pow(1.0 + rate, 1.0 / pv_period_im) - 1.0;
return be_neto_hetz(t) * rate2;
/*
NB 12/02/24 - CR420 - Added column
*/

/* Annuity payments received after or without guaranteed period  */
if (t < commence_period_w)
return NO_AVG;
if (contract_boundary_indicator)
return NO_AVG;
if (!gimla_prod_ind)
return NO_AVG;
if (t <= maturity_period_first_w)
return NO_AVG;
return sm_maslul -> ifrs_clms_ann(t);
/*
TA 17/08/21 - CR 355- Created for IFRS17 purposes.
NB 26/11/24 - CR490 - Zero out cashflows when contract boundary applies
*/

/* guaranteed annuity payments received  (defined period) */
if (t < commence_period_w)
return NO_AVG;
if (contract_boundary_indicator)
return NO_AVG;
if (!gimla_prod_ind)
return NO_AVG;
if (t <= maturity_period_first_w)
return NO_AVG;
return sm_maslul -> ifrs_clms_ann_sav(t);
/*
TA 17/08/21 - CR 355- Created for IFRS17 purposes.
NB 26/11/24 - CR490 - Zero out cashflows when contract boundary applies
*/

/* Claim payment of the "risk" component */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind || klassi_prod_ind)
return risk_claims_paid(t) - gtee_cost_equ(t);
if (prod_code == LTC)
return tot_clms(t) + tot_surrs(t);
return tot_clms(t);
/*
TA 17/08/21 - CR355 - Created for IFRS17 purposes
SK 16/01/23 - CR424 - Adding 'gtee_cost_equ' and 'lookthrough_adj'
SK 05/07/23 - CR433 - Removing 'lookthrough_adj'
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
*/

/* total surrenders & maturities for savings products */
double mat = tot_mats(t) + gimla_post_maturity(t);
if(contract_boundary_indicator)
mat = tot_mats_lumpsum(t);
if (savings_prod_ind || klassi_prod_ind)
return mat + tot_surrs(t) + claims_paid(t) + pup_clm_paid(t) - gtee_cost_equ(t)
- (ifrs_clms_ins(t) + ifrs_clms_ann(t) + ifrs_clms_ann_sav(t));
return 0.0;
/*
TA 17/08/21 - CR355 - Created for IFRS17 purposes
SK 16/01/23 - CR424 - Adding 'gtee_cost_equ' and 'lookthrough_adj'
SK 05/07/23 - CR433 - Removing 'lookthrough_adj'
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
NB 27/11/24 - CR490 - use lump sum maturities when contract boundaries are applied
*/

/* Initial commission */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (vol_comm_paid_agent1(t) + vol_comm_paid_agent2(t) + vol_comm_paid_agent3(t) +
vol_comm_paid_agency(t) + vol_comm_paid_super_agency(t) + prize_paid(t));
/* TA 17/08/21 - CR 355- Created for IFRS17 purposes. */

/* Renewal commission */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (tot_comm_paid(t) - ifrs_comm_init(t) - lookthrough_adj(t));
/*
TA 17/08/21 - CR355 - Created for IFRS17 purposes
SK 05/07/23 - CR433 - Adding 'lookthrough_adj'
*/

/* Total claim expenses, including gimla claim expenses */
if (t < commence_period_w+1)
return NO_AVG;
if (contract_boundary_indicator ||  !gimla_prod_ind) {
if (t > maturity_period_last_w)
return NO_AVG;
return expenses_claims(t) + pup_expenses_claims(t) + expenses_surrs(t) + expenses_mats(t);
}
// For gimla products include gimla cashflows
return expenses_claims(t) + pup_expenses_claims(t) + expenses_surrs(t) + expenses_mats(t) +
gimla_expenses(t) + expenses_gimlaconv(t);
/*
TA 17/08/21 - CR 355- Created for IFRS17 purposes.
NB 27/11/24 - CR490 - Gimla expenses removed when contract boundaries are applied
*/

/* Total initial expenses */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t == commence_period_w+1)
return expenses_perc_prem(t) + expenses_per_pol(t) + as_exp(t);
return 0.0;
/* TA 17/08/21 - CR 355- Created for IFRS17 purposes. */

/* Total renewal expenses */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t > commence_period_w+1)
return expenses_perc_prem(t) + expenses_per_pol(t) + as_exp(t) + expenses_res(t) +
pup_expenses_per_pol(t);
return 0.0;
/* TA 17/08/21 - CR355- Created for IFRS17 purposes. */

/* Investment income */
if (t < commence_period_w+1 )
return NO_AVG;
return tot_res(t) * inv_ret_gross_hetz_incl_pre(t);
/* TA 17/08/21 - CR 355- Created for IFRS17 purposes. */

/* Premium of the risk component */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind)
return risk_prem_recd(t) + prem_loads(t);
if (prod_code == CLSAVINGS)
return 0.0;
if (prod_code == END || prod_code == ENDM92 || prod_code == ENDP92 || prod_code == FTEND)
return tot_prem_paid(t) * (1.- ifrs_klasi_sav_perc);
return tot_prem_paid(t);
/*
TA 17/08/21 - CR355 - Created for IFRS17 purposes.
NB 15/05/23 - CR432 - Split added for END prem and allocated all CLSAVINGS to savings
*/

/* Premium of the savings component */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind)
return (tot_prem_paid(t) - ifrs_prem_ins(t));
if (prod_code == CLSAVINGS)
return tot_prem_paid(t);
if (prod_code == END || prod_code == ENDM92 || prod_code == ENDP92 || prod_code == FTEND)
return tot_prem_paid(t) * ifrs_klasi_sav_perc;
return 0.0;
/*
TA 17/08/21 - CR355 - Created for IFRS17 purposes.
NB 15/05/23 - CR432 - Split added for END prem and allocated all CLSAVINGS to savings
*/

/* Risk adjustment calculation for IFRS */
if (t < commence_period_w+1)
return NO_AVG;
if (!gimla_prod_ind) {
if (t > maturity_period_last_w)
return NO_AVG;
return (claims_paid(t) + pup_clm_paid(t) + tot_mats(t) + tot_surrs(t)) * ra_perc;
}
// Else gimla products
// Products with contract boundaries
if(bdry_by_mekademage_ind)
return (claims_paid(t) + pup_clm_paid(t) + tot_mats(t) + tot_surrs(t)) * ra_perc;
// Products without contract boundaries
return (claims_paid(t) + pup_clm_paid(t) + tot_mats(t) + tot_surrs(t) + gimla_post_maturity(t)) *
ra_perc;
/*
SK 24/11/24 - CR491 - Created column
*/

//PHI claims amount with duration multiplier neutralized
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t<1)
return 0.0;
double rate = 0.0;
double occ = avg_occ_load/100;
if (prod_fund_name == PHIFP_MH || prod_fund_name == PHIFP_SHLV || prod_fund_name == PHIVP_17 ||
prod_fund_name == PHIVP_MH || prod_fund_name == PHIVP_SHLV)
occ = phi_occ_add / 100;
if (sa_on_data_ind) //SA arrives from the input and we need to apply the Tosafot
rate = phi_vectors_inci_rates * phi_mpa_factors * umbclmmult // מטריה עבור הכפלה
* (1.0 + prem_ldg_prof_theo_pc) / (1.0 + prem_ldg_prof_act_pc)
* (1.0 + avg_mort_load/100) * (1.0 + occ) * phi_incidence_loading;
else //SA is calculated, Tosafot are already included
rate = phi_vectors_inci_rates * phi_mpa_factors * umbclmmult * phi_incidence_loading;
// מטריה עבור הכפלה
// Apply scalars and sensitivies and convert to a period rate
rate = 1.0 - pow(1.0 - (rate * select_factor_clm
* mort_params_mult_base
* morbid_trend_fac)
* (1.0 / prem_rate_factor)
, 1.0 / pv_period_im);
rate = (poli_if_b(t)
-(pol_surr(t) + pol_pupd(t)
+ pol_prem_reduct(t) + pol_death(t))/2.0)
* rate;
double inf = pow(1.0 + claim_infl_rt,
duration_b(t) + 1.0 / pv_period_im - elapsed_years);
return max((sum_assured_basic_b(t) + (bonus_b(t-1) + bonus_b(t)) / 2.0),0.0)
* inf * rate;
//NB 24/11/24 - CR483 - Column added

/* Returns investment return, adjusted for liquidity premium and the proportion invested in hetz,
post maturity. */
if (t < commence_period_w+1)
return NO_AVG;
// First derive liquidity premium.  Find the base LP to add on:
double lp = liqprem_rates;
double rate = 0.0;
if (act_return_use && t >= 1 && t <= int_period_adjust) //Actual returns
rate = pow(1.0 + actual_return_rate, 1.0 * pv_period_im / int_period_adjust) - 1.0;
else
rate = inv_ret_gross_postret;
// Multiply by product-dependent factor
lp = lp * liqprem_propn_post_maturity;
//for t=1 we apply the financial stress
if (t==1)
rate = (inv_gross_hetz * inv_pct_hetz)
+ (((1.0 + rate + lp) * pow(1.0 + sii_stress, pv_period_im) - 1.0)
* (1.0 - inv_pct_hetz));
// Find base rate, weighted according to hetz proportion, with LP applied just to the non-hetz
portion
else
rate = (inv_gross_hetz * inv_pct_hetz)
+ ((rate + lp)
* (1.0- inv_pct_hetz));
// Change to a period rate, and return
return pow(1.0 + rate, 1.0 / pv_period_im) - 1.0;
/*
DC 08/06/14   - Added code to include liquidity premium. Tidied formula.
DC 23/06/14  - Correction and reordering such that the liquidity premium is applied only to
the non-hetz portion.
ES 17/11/14 - Tidied formula.
OS 28/09/16 - replaced column to get the value directly from the variable inv_pct_hetz
OS 19/06/22 - CR385 - Adding sii_stress variable
NB 09/06/22 - CR392 - formula linked to inv_ret_gross_postret rather than inv_ret_gross for
deferred annuities
NB 04/07/24 - CR466 - Added condition to use actual return from the 'act_return_param tbl'
*/

/* Returns investment return, adjusted for liquidity premium and the proportion invested in hetz,
pre maturity. */
if (t < commence_period_w+1)
return NO_AVG;
// First derive liquidity premium.  Find the base LP to add on:
double lp = liqprem_rates;
double rate = 0.0;
if (act_return_use && t >= 1 && t <= int_period_adjust) //Actual returns (annualized)
rate = pow(1.0 + actual_return_rate, 1.0 * pv_period_im / int_period_adjust) - 1.0;
else
rate = inv_ret_gross_preret;
// Multiply by product-dependent factor
lp = lp * liqprem_propn_pre_maturity;
//for t=1 we apply the financial stress
if (t==1)
rate = (inv_gross_hetz * inv_pct_hetz)
+ (((1.0 + rate + lp) * pow(1.0 + sii_stress,pv_period_im) - 1.0)
* (1.0- inv_pct_hetz));
// Find base rate, weighted according to hetz proportion, with LP applied just to the non-hetz
portion
else rate = (inv_gross_hetz * inv_pct_hetz)
+ ((rate + lp)
* (1.0- inv_pct_hetz));
// Change to a period rate, and return
return pow(1.0 + rate, 1.0 / pv_period_im) - 1.0;
/*
DC 08/06/14 - Added code to include liquidity premium. Tidied formula.
DC 23/06/14 - Correction and reordering such that the liquidity premium is applied only to
the non-hetz portion.
ES 17/11/14 - Tidied formula.
OS 28/09/16 - replaced column to get the value directly from  the variable inv_pct_hetz
OS 19/06/22 - CR385 - Adding sii_stress variable
NB 04/07/24 - CR466 - Added condition to use actual return from the 'act_return_param tbl'
*/

/* Return on investments net of both fixed and partial variable management fees for actives - pre
retirement */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if ((!savings_prod_ind) && (prod_code != END) && (prod_code != ENDM92) && (prod_code != ENDP92) &&
(prod_code != FTEND) && (prod_code != LTC))
return 0.0;
// For mavtiach products, this code should not be relevant
if (prod_fund < 8)
return pow((1.0 + inv_non_partic_crediting_rate), 1.0 / pv_period_im) - 1.0;
double period = (t / pv_period_im);
if (period <= no_mgt_fees_var_period && period > 0.0)
return pow(1.0 + (pow(1.0 + inv_ret_gross_hetz_incl_pre(t), pv_period_im)
* (1.0 - mgt_fee_res_rate_act(t)) - 1.0), (1.0
/pv_period_im)) - 1.0;
// For mishtatef products, the amount of variable management fee deducted will depend on the
balance of the bor at the start and end of the period
double fee_factor = 0.0;
double bal_pre = 0.0;
double bal_post = 0.0;
// We calculate the balance at the end of the period, before survivorship.  If we are in a maturity
period, we need to remember to also
//  account for the portion of the bor/odef that has already moved to the sub-model.
if (!(poli_if_b(t+1) < SMALL_DOUBLE))
bal_pre = mgt_fee_bal_act_e(t) / poli_if_b(t+1) * (1.0 - gimla_ret_prob_b(t+1));
if (!(pol_matd(t) < SMALL_DOUBLE) && gimla_prod_ind)
bal_post = sm_maslul->mgt_fee_bal_gimact_matper(t)/pol_matd(t) * gimla_ret_prob_b(t+1);
// This will return a value only in a maturity period, because of the code in the sub-model
column
// Case 1a: We start and end in bor
if (mgt_fee_bal_act_b(t) < SMALL_DOUBLE) {
if (bal_pre + bal_post < SMALL_DOUBLE)
fee_factor = 0.0;
// Case 1b: We start in bor, come out within the period, and so first need to clear the bor and
then start taking management fee
else fee_factor = max(min((bal_pre + bal_post) / mgt_fee_vartheo_act(t),10.0),-10.0);
}
// Case 2a: We start in odef, go into bor within the period, and so take (negative) management fee
only until the bor is cleared
else if (bal_pre + bal_post < SMALL_DOUBLE)
fee_factor= max(min(-mgt_fee_bal_act_b(t)/ poli_if_b(t) / mgt_fee_vartheo_act(t),10.0),-
10.0);
// Case 2b: We start and end in odef, and so take the full variable fee
else fee_factor = 1.0;
// after the no_mgt_fees_var_period
return pow(1.0 + (pow(1.0 + inv_ret_gross_hetz_incl_pre(t) , pv_period_im)
* (1.0 - mgt_fee_res_rate_act(t)) - 1.0)
* (1.0 - mgt_fees_var * fee_factor), 1.0 /
pv_period_im) - 1.0;
/* Multiply mgt_fee_var from the table by the
part of mgt fee we need to collect */
/*
GR 06/03/19 - CR223 - Created column.
TA 27/12/20- CR90 Changed variable mgt_fee_res_rate(t) to mgt_fee_res_rate_act(t)
SK 05/08/21 - CR356 - Returning zero for products that are not savings and not {END, ENDM92,
FTEND, LTC}
*/

/* Return of investments net of both fixed and partial variable management fees for paid up's - pre
retirement */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// For mavtiach products, this code should not be relevant
if (prod_fund < 8)
return pow((1.0 + inv_non_partic_crediting_rate), 1.0 / pv_period_im) - 1.0;
// For mishtatef products, the amount of variable management fee deducted will depend on the
balance of teh bor at the start and end of the period
double fee_factor = 0.0;
double bal_pre = 0.0;
double bal_post = 0.0;
double period = (t / pv_period_im);
if (period <= no_mgt_fees_var_period && period > 0.0)
return pow(1.0 + (pow(1.0 + inv_ret_gross_hetz_incl_pre(t), pv_period_im)
* (1.0 - mgt_fee_res_rate_pup(t)) - 1.0), (1.0
/pv_period_im)) -1.0;
// We calculate the balance at the end of the period, before survivorship.  If we are in a maturity
period, we need to remember to also
//  account for the portion of the bor/odef that has already moved to the sub-model.
if (!(pups_if_b(t+1) < SMALL_DOUBLE))
bal_pre = mgt_fee_bal_pup_e(t) / pups_if_b(t+1) * (1.0 - gimla_ret_prob_b(t+1));
if (!(pups_matd(t) < SMALL_DOUBLE) && gimla_prod_ind)
bal_post = sm_maslul->mgt_fee_bal_gimpup_matper(t)/pups_matd(t) * gimla_ret_prob_b(t+1);
// Case 1a: We start and end in bor
if (mgt_fee_bal_pup_b(t) < SMALL_DOUBLE){
if (bal_pre + bal_post < SMALL_DOUBLE)
fee_factor = 0.0;
// Case 1b: We start in bor, come out within the period, and so first need to clear the bor
and then start taking management fee
else if (!(pups_if_b(t) < SMALL_DOUBLE))
fee_factor = max(min((bal_pre + bal_post)/(bal_pre + bal_post -
mgt_fee_bal_pup_b(t) / pups_if_b(t)),10.0),-10.0);
else fee_factor = 1.0;
}
// Case 2a: We start in odef, go into bor within the period, and so take (negative)
management fee only until the bor is cleared
else if ((bal_pre + bal_post < SMALL_DOUBLE) && !(pups_if_b(t) < SMALL_DOUBLE))
fee_factor = max(min(-(mgt_fee_bal_pup_b(t) / pups_if_b(t))
/ (bal_pre + bal_post - mgt_fee_bal_pup_b(t) /
pups_if_b(t)),10.0),-10.0);
// Case 2b: We start and end in odef, and so take the full variable fee
else fee_factor = 1.0;
return pow(1.0 + (pow(1.0 + inv_ret_gross_hetz_incl_pre(t) , pv_period_im)
* (1.0 - mgt_fee_res_rate_pup(t)) - 1.0)
* (1.0 - mgt_fees_var * fee_factor), 1.0 /
pv_period_im) - 1.0;
/* Multiply mgt_fee_var from the table by the
part of mgt fee we need to collect*/
/*
GR 11/03/19 - CR223 - Created column.
GR 16/06/19 - CR277 - Added condition in case 2a to avoid division by zero (cases where the
policy is active but there is positive pup res at t=1)
TA 27/12/20- CR90 Changed variable mgt_fee_res_rate(t) to mgt_fee_res_rate_pup(t)
*/

/* Calculates little a on a basis of best estimate experience. Used in calculation of the LTC
increase premium to cover the malus. */
if (t < commence_period_w + 1 || t >= maturity_period_w)
return NO_AVG;
if (pup_mult == 1)
return 0.0;
return (littlea_b_experience(t+1) * v_factor_pre(t) * poli_if_b(t+1) + poli_avg(t) / pv_period_im)
/ poli_if_b(t);
/*
OS 07/12/16 CR80 - created column
*/

/*Returns the lookthrough adjustment, which returns to profit the net commission cashflow of
subsidiaries of Migdal*/
if (t < commence_period_w+1)
return NO_AVG;
if (!lookthrough_run_ind)
return 0.0;
if (!lookthrough_pol_ind1 && !lookthrough_pol_ind2 && !lookthrough_pol_ind3 &&
!lookthrough_pol_ind_shochnut && !lookthrough_pol_ind_shochnut_al)
return 0.0;
// The adjustment amount is a percentage of the overall commission
double adj_amount = tot_comm_paid_miv(t) * lookthrough_perc;
// We also need to add on (regained) investment income on the lookthrough amount, for a full period
for
//  start period commissions, and half a period for mid-period commissions.
double inv_inc_beg = (vol_comm_paid_agent1(t) * lookthrough_pol_ind1
+
pers_comm_paid_agentgove(t) + prize_paid(t))
* lookthrough_perc * inv_ret_gross_hetz_incl_pre(t);
double inv_inc_mid = (init_comm_paid_agent1(t) * lookthrough_pol_ind1 + ren_comm_paid_agent1(t) *
lookthrough_pol_ind1
+ as_com_res(t) + as_ren_com(t))
* lookthrough_perc * 0.5 *
inv_ret_gross_hetz_incl_pre(t);
double total_inv_inc = adj_amount + inv_inc_beg + inv_inc_mid;
if (!reg_comm_tableread)
total_inv_inc = total_inv_inc + 0.5 * (init_comm_paid_agent2(t) * lookthrough_pol_ind2
+ init_comm_paid_agent3(t)
* lookthrough_pol_ind3
+ init_comm_paid_agency(t)
*
lookthrough_pol_ind_shochnut  + init_comm_paid_super_agency(t)
* lookthrough_pol_ind_shochnut_al
+ ren_comm_paid_agent2(t)       *
lookthrough_pol_ind2
+ ren_comm_paid_agent3(t)
* lookthrough_pol_ind3
+ ren_comm_paid_agency(t)       *
lookthrough_pol_ind_shochnut  + ren_comm_paid_super_agency(t)
*
lookthrough_pol_ind_shochnut_al)
* lookthrough_perc *
inv_ret_gross_hetz_incl_pre(t);
if (!volcomm_tableread)
total_inv_inc = total_inv_inc + (pers_comm_paid_agencygove(t) +
pers_comm_paid_super_agencygove(t)
+ vol_comm_paid_agent2(t) * lookthrough_pol_ind2
+ vol_comm_paid_agent3(t)       * lookthrough_pol_ind3
+ vol_comm_paid_agency(t) * lookthrough_pol_ind_shochnut
+ vol_comm_paid_super_agency(t) * lookthrough_pol_ind_shochnut_al)
* lookthrough_perc *
inv_ret_gross_hetz_incl_pre(t);
return total_inv_inc;
/*
MG 25/05/20 - CR286 - Added this column to identify the cashflow of subsidiaries in Migdal.
GA 02/02/21 - CR324 - Droping and/or Adding switches. Reorganize commissions where rates are
taken from data.
GA 24/12/24 - CR482 - Added\Changed conditions to idntify Mivtach Simon's policies with new
lookthrough indicators,
And calculating the adjustment based on a new column -
'tot_comm_paid_miv' instead of 'tot_comm_paid'
*/

/* Calculates the additional premium in the period to cover the malus before survivorship -
relevant to LTC only. */
if (t< commence_period_w + 1 || t >= maturity_period_w)
return NO_AVG;
if (t < 1 || pup_mult == 1)
return 0.0;
double old_part = ltc_incr_prem(t-1);
double new_part = -bonus_b(t-1) / littlea_b_experience(t) / pv_period_im;
//The additional premium cannot go above a certain limit (usually 15%). Maximum shekel increase is
divided by pv_period because basic_prem is annual.
double max_increase = ltc_incr_pct_max * basic_prem(commence_period_w+1) / pv_period_im;
// We apply the limit to the theoretical increase premium, and also do not allow it to go negative.
return max(0.0, min(old_part+new_part,max_increase));
/*
OS 07/12/16 CR80 - created formula for calculating the increase in premium to cover the
malus
*/

/* Returns the actual increase premium after survivorship. */
if (t < commence_period_w + 1 || t >= maturity_period_w)
return NO_AVG;
if (prod_code == LTC)
return ltc_incr_prem(t) * poli_avg(t);
return 0.0;
/*
OS 07/12/16 CR80- created column
*/

/* Variable management fee odef/bor on the active portion, start period, after survivorship */
if (t < 1 || t > maturity_period_last_w + 1 || pup_mult==1)
return NO_AVG;
if (t == 1)
{
if (cal_month(t-1) == 12 && !(mgt_fee_var_bal < SMALL_DOUBLE))
return 0.0;
//If it's the first period of the year, and there's positive balance,
zero it out.
// Otherwise, we start in a bor
return (res_bal_b(t) + as_res_b(t)) * mgt_fee_var_bal;
}
if (cal_month(t-1) == 12 && !(mgt_fee_bal_act_e(t-1) < SMALL_DOUBLE))
return 0.0;
//If it's the first period of the year, and there's positive balance, zero it
out.
return mgt_fee_bal_act_e(t-1);
/* the bal is only for the actives in force- pups and prem reds are transferred to
mgt_fee_bal_pups,
death and surrender, the balance is released on conversion to pension at maturity, the full
balance
should be continued. */
/* DC 1/11/15 - Removed the EV/AS run condition.  Tidied formula.
OS 03/01/17 - CR106 part I - changed code. we no longer need to calculate values at
retirement.
GR 06/02/19 - CR223 Removed the minus sign that comes befor the Bor from the tables (line 5)
GR 10/02/19 - CR223 Added condition of zeroing out positive balance at the end of a year.
GR 11/02/19 - CR223 Change Bor table name from mgt_fee_loss to mgt_fee_var_bal
GR 13/02/20 - CR303 Added condition for zeroing when theres positive balance and it's first
quarter at t=1.
*/

/* Variable management fee odef/bor on the active portion, end period, after survivorship */
if (t < 1 || t > maturity_period_last_w + 1 || pup_mult==1)
return NO_AVG;
if (poli_if_b(t) < SMALL_DOUBLE)
return NO_AVG;
return (mgt_fee_bal_act_b(t) / poli_if_b(t) + mgt_fee_vartheo_act(t))
* poli_if_b(t+1); // do on per pol basis and then take only for survivors
/* the bal is only for the actives in force- pups and prem reds are transferred to
mgt_fee_bal_pups,
death and surrender, the balance is released on conversion to pension at maturity, the full
balance
should be continued. */
/* GR 06/02/19 - CR223 Created column
*/

/* Variable management fee odef/bor on the paid-up portion, start period, after survivorship */
if (t < 1 || t > maturity_period_last_w + 1)
return NO_AVG;
if (t == 1)
{
if (cal_month(t-1) == 12 && !(mgt_fee_var_bal < SMALL_DOUBLE))
return 0.0;
//If it's the first period of the year, and there's positive balance,
zero it out.
//else we start in a bor
return pup_res_bal_b(t) * mgt_fee_var_bal;
}
if (cal_month(t-1) == 12 && !(mgt_fee_bal_pup_e(t-1) < SMALL_DOUBLE))
return 0.0;
//If it's the first period of the year, and there's positive balance, zero it
out.
return mgt_fee_bal_pup_e(t-1);
/* GR 12/02/19 - CR223 Created column
GR 13/02/20 - CR303 Added condition for zeroing when theres positive balance and it's first
quarter at t=1.
*/

/* Variable management fee odef/bor on the paid-up portion, end period, after survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w+1 || t<1)
return NO_AVG;
if (prod_code == ANPY)
return NO_AVG;
double rate;
double rate_surr = 0.0;
if (!gimla_prod_ind || age_exact_b(t) < 60.0) {
if (klassi_prod_ind) {
rate_surr = pup_surr_rate_klassi;
if (t >= maturity_period_w - 2)
rate_surr = surr_rate_klassi_mat;
if (t > maturity_period_w + 2)
rate_surr = surr_rate_klassi_postmat;
}
else
rate_surr = pup_surr_rate;
}
double rate_dth;
double ltc_impr_fac = 1.0;
if (prod_code == LTC)
ltc_impr_fac = ltc_mort_impr_fac;
if (age_exact_b(t) < mort_oldage_startage) // standard mortality
rate_dth = 1.0 - pow(1.0 - 0.001 * (mort_tbl_ageexact_poldthname
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ mort_vol_fac
+ mort_warrisk_addn),
1.0/pv_period_im);
else  // gimla mortality
rate_dth = (1.0 - pow(1.0 - (gimla_mortality_table
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ 0.001 * mort_vol_fac
+ 0.001 * mort_warrisk_addn),
1.0 / pv_period_im))
* gimla_mort_mult_sex1;
rate_surr = (1.0 - pow((1.0 - min((rate_surr + lapse_shock_factor)
* lapse_scaling_factor * lapse_scaling_factor_premium, 0.99999999)),
1.0 / pv_period_im));
rate = rate_dth * (1.0 - rate_surr / 2.0) + rate_surr;
double poli_if_eop;
if (pup_mult == 1 || abs(poli_if_b(t+1)) < SMALL_DOUBLE)
poli_if_eop = 1.0; // to fix division by zero
else poli_if_eop = poli_if_b(t+1);
if (t <= maturity_period_last_w) {
if ((pup_mult == 1 && abs(pups_if_b(t)) < SMALL_DOUBLE) || (pup_mult == 0 && poli_if_b(t) <
SMALL_DOUBLE))
return 0.0;
else if (pups_if_b(t) <= 0.0001)
return (mgt_fee_bal_pup_b(t)
+ mgt_fee_vartheo_pup(t) / (1.0 - 0.5*rate)) * (1.0 - rate)
+ mgt_fee_bal_act_e(t) / poli_if_eop * pups_new(t)  * (1.0 -
gimla_ret_prob_b(t+1));
return (mgt_fee_bal_pup_b(t) + mgt_fee_vartheo_pup(t) / (1.0 - 0.5*rate))
* ((pups_if_b(t+1) - pups_new(t)  * (1.0 -
gimla_ret_prob_b(t+1)))
/ pups_if_b(t))
+ mgt_fee_bal_act_e(t) / poli_if_eop * pups_new(t)  * (1.0 -
gimla_ret_prob_b(t+1));
}
return NO_AVG;
/* the bal is only for the pups in force- pups and prem reds are transferred to mgt_fee_bal_pups,
death and surrender, the balance is released
on conversion to pension at maturity, the full balance should be continued. */
/* DC 24/01/13 - added in lapse_scaling_factor_premium as an additional multiplier
DC 06/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_code_sub and not
prod_code
DC 30/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_fund_name and not
prod_code_sub
ES 01/02/15 - added a condition so that if the age is equal to or greater than
mort_old_startage, it uses
gimla mortality instead of standard mortality.
DC 01/11/15 - Removed the EV/AS run condition.  Tidied formula.
AH 04/11/15 - Added in clause for ANPY to zero out column
DC 01/02/16 - Added in a condition to zero out the surrender component for post-60 gimla
policies, as this is
already included in the take-up rates.
OS 17/08/16 - CR70  Type comparison correction - changed pup_mult type to int
and changed comparison to SMALL DOUBLE
OS 28/09/16 - replaced column lapse_scale_fac to get the value directly from  the variable
lapse_scaling_factor
OS 03/01/17 - CR106 part I - changed the code. changed maturity_period_w to
maturity_period_last_w
DC 18/01/17 - CR106 part P - multiplied the new pups bracket by 1-retirement probability
DC 15/08/17 - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
DC 31/12/18 - CR247 - now reads a select factor rather than calculating it from a select period
- removed unused variable dth_decr_clm_mult
OS 01/01/19 - CR250 - Added in LTC improvement factor
GR 06/02/19 - CR223 Removed the minus sign that comes befor the Bor from the tables (lines
50,54)
GR 11/02/19 - CR223 Change mgt_fee_var table name to mgt_fee_var_bal
GR 12/02/19 - CR223 Changed column name from mgt_fee_bal_pup_b to mgt_fee_bal_pup_e, removed
condition on t=1
and changed timing
NB 31/12/23 - Surrender rate drawn from Klassi table for Klassi policies rather than standard
table
*/

/* Total fixed management fee from reserve collected in period */
if (t < commence_period_w)
return NO_AVG;
if (!gimla_prod_ind) {
if (t > maturity_period_last_w)
return NO_AVG;
return mgt_fee_fxd_act(t) * poli_avg(t) + mgt_fee_fxd_pup(t);
}
// pups are already in force, actives are at pol level
// For gimla products, split into three periods
if (t <= maturity_period_first_w)
return mgt_fee_fxd_act(t) * poli_avg(t) + mgt_fee_fxd_pup(t);
if (t <= maturity_period_last_w)  // and past the first maturity period
return mgt_fee_fxd_act(t) * poli_avg(t) + mgt_fee_fxd_pup(t)
+ mgt_fee_fxd_gim(t);
// Otherwise we are after maturity_period_last_w
return mgt_fee_fxd_gim(t);   // gim is at in force level already
/*
DC 24/12/14 - Tidied formula
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
DC 17/01/17 - CR106o - added in a new clause for between the first and last maturity periods
where we
need to add together the pre- and post- retirement management
fees
DC 03/10/17 - Reformatted formula with split between non-gimla and gimla products
*/
/* Reporting column */

/* Fixed reserve management fee taken in the period for those who have already retired */
if (t <= maturity_period_first_w || !gimla_prod_ind)
return NO_AVG;
double rate1 = pow(pow(1.0 + inv_ret_gross_hetz_incl_post(t), pv_period_im), 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
double rate3 = pow(pow(1.0 + inv_ret_net_fxd_post(t), pv_period_im), 1.0 / 12.0);
double rate4 = pow(rate3, 12.0 / pv_period_im);
return (gimla_res_b(t) - gimla_post_maturity(t) * 0.5)
* (rate2 - rate4);
/*
DC 23/12/14 - Tidied formula
OS 25/12/16 - changed from invest_return_gross_hetz_incl to
invest_return_gross_hetz_incl_post
because of liquidity premium pre and post.
DC 17/1/17  - removed the erroneous condition that caused this column to be calculated only
after the
data retirement age
OS 22/02/17 - CR128 Replaced gimla res in the end of the period  (time t-1) with gimla res
in the beginning of the period (time t)
DC 03/10/17 - CR179 - Rewrote initial condition
*/

/* Management Fee from Premium - gorem polisa, dmei nihul */
if (t < commence_period_w+1 || t > maturity_period_w)
return NO_AVG;
if (t > 0 && premium_cancel == 1)
return 0.0;
return ((policy_fee * policy_fee_id) * (1.0 + prem_subannual_rt)
+ (1.0 -  policy_fee_id) * tarr_expenses(t) * basic_prem(t))
/ pv_period_im * poli_avg(t);
/* Reporting column */
/* GR 07/10/18 - CR201 - Created column for work plan purposes
*/

/* Contains the cash value of the management fee balance as of each relevant retirement age */
if (t < maturity_period_first_w || t > maturity_period_last_w+1)
return NO_AVG;
if (prod_code == ANPY)
return NO_AVG;
double rate;
double rate_surr = 0.0;
if (!gimla_prod_ind || age_exact_b(t) < 60.0) {
if (klassi_prod_ind) {
rate_surr = pup_surr_rate_klassi;
if (t >= maturity_period_w - 2)
rate_surr = surr_rate_klassi_mat;
if (t > maturity_period_w + 2)
rate_surr = surr_rate_klassi_postmat;
}
else
rate_surr = pup_surr_rate;
}
double rate_dth;
double ltc_impr_fac = 1.0;
if (prod_code == LTC)
ltc_impr_fac = ltc_mort_impr_fac;
if (age_exact_b(t) < mort_oldage_startage) // standard mortality
rate_dth = 1.0 - pow(1.0 - 0.001 * (mort_tbl_ageexact_poldthname
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ mort_vol_fac
+ mort_warrisk_addn),
1.0/pv_period_im);
else  // gimla mortality
rate_dth = (1.0 - pow(1.0 - (gimla_mortality_table
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ 0.001 * mort_vol_fac
+ 0.001 * mort_warrisk_addn),
1.0 / pv_period_im))
* gimla_mort_mult_sex1;
rate_surr = (1.0 - pow((1.0 - min((rate_surr + lapse_shock_factor)
* lapse_scaling_factor * lapse_scaling_factor_premium, 0.99999999)),
1.0 / pv_period_im));
rate = rate_dth * (1.0 - rate_surr / 2.0) + rate_surr;
if (t < maturity_period_last_w) {
if (fabs(pups_if_b(t+1)) < SMALL_DOUBLE)
return 0.0;
return mgt_fee_bal_pup_e(t) / pups_if_b(t+1);
}
if (t == maturity_period_last_w && gimla_prod_ind && !(pups_if_b(t) < SMALL_DOUBLE)) {
double pups_if_mat = pups_if_b(t) - pups_surr(t) + pups_new(t) - pups_death(t)
-
pups_clm(t)*decrem_after_clm;
double mgtfeeactb = 0.0;
if (!(abs(poli_if_b(t)) < SMALL_DOUBLE))
mgtfeeactb = mgt_fee_bal_act_b(t) / poli_if_b(t) + mgt_fee_vartheo_act(t);
if (abs(pups_if_b(t)) < SMALL_DOUBLE)
return (mgt_fee_bal_pup_b(t)
+ mgt_fee_vartheo_pup(t) / (1.0 - 0.5*rate))
+ mgtfeeactb * pups_new(t)
/ pups_if_mat;
return ((mgt_fee_bal_pup_b(t)
+ mgt_fee_vartheo_pup(t) / (1.0 - 0.5*rate))* (pups_if_mat -
pups_new(t)) / pups_if_b(t)
+ mgtfeeactb * pups_new(t))
/ pups_if_mat;
}
return NO_AVG;
/*
DC 24/01/13 - added in lapse_scaling_factor_premium as an additional multiplier
OS 03/01/17 - Created column.
DC 18/01/17 - CR106 part P - multiplied the new pups bracket by 1-retirement probability and
tidied formula
DC 03/10/17 - CR179 - Changed use of gimla_if_b to gimla_prod_ind
DC 31/12/18 - CR247 - now reads a select factor rather than calculating it from a select
period
- removed unused variable dth_decr_clm_mult
OS 01/01/19 - CR250 - Added in LTC improvement factor
GR 12/02/19 - CR223 Tided code
NB 31/12/23 - CR349 - Surrender rate drawn from Klassi table for Klassi policies rather than
standard table
*/

/* Returns value of claims in the period, net of reinsurance recoveries */
if (t < commence_period_w+1)
return NO_AVG;
if (savings_prod_ind || klassi_prod_ind)
return risk_clms_if_b(t) - reins_claims(t);
if (prod_code == ANPY)
return 0;
//All Health products
return tot_clms(t) - reins_claims(t);
/* Reporting column */
/*
GR 04/10/18 - CR242 - Created column to report the claims net of reinsurance for SII drivers
calculation.
OS 03/02/20
- CR334 - Change in column for Health products to return claims net of
reinsurance
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
*/

/* Returns the present value of the annuity outflow. The column will be used to determine
the Conversion rates for the coverage units calculation in IFRS */
if (t < commence_period_w)
return NO_AVG;
if (!gimla_prod_ind)
return NO_AVG;
return tot_pv_gimla_post_maturity(t);
/* SK 09/07/22 - CR394 - Created column
*/

/* Returns the present value of the savings outflow. The column will be used to determine
the Conversion rates for the coverage units calculation in IFRS */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
//For savings - we are looking only at the pre retirement period */
if (savings_prod_ind || klassi_prod_ind)
return tot_pv_surrs(t) + tot_pv_mats(t) + tot_pv_claims_pre(t) - outflow_risk_pv(t);
//Other products
return NO_AVG;
/*
SK 09/07/22 - CR394 - Created column
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == "PHI" && phi_reins_treaty == "ShalvaFlat")
return sum_assd_if_b(t) * phi_reins_prem_mult * phi_reins_res_factor/100.0;
// For other products other than PHI
return NO_AVG;
/*
OS 07/08/18 - CR14 - Created column
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == "PHI" && phi_reins_treaty == "ShalvaFlat")
return phi_reins_res_b(t) - phi_reins_res_b(t-1);
// For other products other than PHI
return NO_AVG;
/*
OS 07/08/18 - CR14 - Created column
*/

/* Reporting column for premium init bruto */
if (t == 1)
return prem_init_bruto;
return NO_AVG;
/*
OS 27/02/17 - Created column.
DC 16/08/17 - CR164 - Amended second return to return NO_AVG rather than zero
*/

/* Reporting column for premium init neto */
if (t == 1)
return prem_init_neto;
return NO_AVG;
/*
OS 27/02/17 - Created column.
DC 16/08/17 - CR164 - Amended second return to return NO_AVG rather than zero
*/

/* Returns paid-up conversion rate from the table, sometimes with adjustments */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (run_type_sub == K && t == 2)
return 1.0;
// Force pup rate of 0 for riders on savings policies
if (pup_zero)
return 0.0;
// For gimla products, we apply special conditions
if (gimla_prod_ind) {
if (postretpremcancel_ind == 1) {  // we wish to make the whole policy paid-up once we pass
the standard retirement age
// Define standard retirement age
double retage = gimla_standardretage;
if (t==2) {
// If we're already passed the standard retirement age, PUP straight away at t=2 (we
//   don't do at t=1 in order to avoid the t=1 PUP multiplier
if (age_exact_b(t) > retage)
return 1.0;
// For SII Mass Lapse – PUP
if (run_type_sub == ML_PUP)
return masslapse_pct;
}
// Otherwise, PUP whenever we hit the standard retirement age
if (t>1 && fabs(age_exact_b(t)-retage) < SMALL_DOUBLE)
return 1.0;
}
// If we are past a set age we should no longer be lapsing savings policies as this would
effectively
// be double counting with take-up decisions. As such, policies will PUP instead of lapsing.
if (age_exact_b(t) >= lapsecancel_age) {
if (klassi_prod_ind) {
double surr = surr_rate_klassi;
if (t >= maturity_period_w - 2)
surr =  surr_rate_klassi_mat;
if (t > maturity_period_w + 2)
surr =  surr_rate_klassi_postmat;
return surr + pup_rate_klassi;
}
return pup_rate +
surr_rate ;
}
}
// For SII Mass Lapse – PUP when not using a distribution
if (run_type_sub == ML_PUP && t==2 && (savings_prod_ind || klassi_prod_ind ||
prod_code == LTC))
return masslapse_pct;
if (klassi_prod_ind)
return pup_rate_klassi;
// At all other times, including for non-gimla products, return the table rate
return pup_rate;
/* DC 1/2/16 - Created column
AH 14/2/16 - Added in additional clause to absorb all lapses from age 60 as PUPs instead
DC 1/3/16 - Adjusted the gimla premium cancel condition to apply only when the new indicator
allows.
Adjusted the lapse-cancellation condition to apply only after a set age.
DC 15/8/17  - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
GR 24/03/19 - CR273 - Added 2 clauses for SII i090 run - MASS LAPSE PUP
TA 30/12/20- CR224 Added an if statment that sets up paid up conversion rate accordingly to k
runs.
NB 16/01/22 - CR361 - force pup rate of 0 for riders on savings pols
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind, added code for Klassi
lapses
*/

/* Returns the sum at risk */
if (t < commence_period_w+1)
return NO_AVG;
return sum_assd_if_b(t) - res_bal_b(t) - as_res_b(t);
/* Reporting column */
/*
GR 04/10/18 - CR242 - Created column to report the sum at risk for SII drivers calculation.
*/

/* Calculates the sum, net of reinsurance, that we would pay on immediate death or disability, for
the MCR calc */
if (t != 1)
return NO_AVG;
if (savings_prod_ind    // ADIFs and MIGs
|| klassi_prod_ind) // Klassi products
return (sum_assured_init_data - current_reserve)
* (1.0 - reins_risk_pct);
if (prod_code == RISK || prod_code == RMASH  || prod_code == DD ||
prod_code == PERS_ACC || prod_code == ADIS)
return sum_assured_init_data * (1.0 - reins_risk_pct);
if (prod_code == LTC)
return sum_assured_basic_b(t) * (1.0 - ltc_reins_claims_pct);
// For LTC, sum_assured_basic_b is based on the data monthly payment and
//  is already multiplied by claims duration
if (prod_code == PHI)
return sum_assured_init_data * phi_vectors_clm_durs * (1.0 - reins_risk_pct);
//Other products - ANPY and HO
return 0.0;
/* Reporting column */
/*
GR 04/10/18 - CR242 - Created column for the SII - MCR calc.
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
*/

/* Expected profits without future premiums - for SII EPIFP calculations */
/* The EPIFP is the VIF in a base run, less this column in an EPIFP run */
// Calculated only at t=1
if (t==1) {
// For savings products, we have cancelled premiums in set_work_variables for an EPIFP run,
and so the EPwoFP is the VIF
if (savings_prod_ind || klassi_prod_ind || prod_code == ANPY)
return tot_pv_dist(t);
// LTC - the future profit when there are no future premiums is equal to zero, as any
accumulated reserve is owed
// to the policyholder
if (prod_code == LTC)
return 0.0;
// For risk and health, the reserve is released to us on cancellation
return tot_res(t);
}
return NO_AVG;
/* Reporting column */
/*
OS 18/03/19 - CR271 - Created column.
NB 15/01/24 - CR349 - simplified prod_code condition to klassi_prod_ind
*/

// Returns the suppliers active claims expenses
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return claims_paid(t) * supplier_exp_rate;
/* MG 06/18/24 - CR336 - created column
*/

// Returns the supplier pup claims expenses
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return pup_clm_paid(t) * supplier_exp_rate;
/* MG 06/18/24 - CR336 - created column
*/

/* Returns surrender rate from the table, sometimes with adjustments */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// For non-savings policies, total lapse rate includes pup rate - lapse vector can be savings for
risk rider of savings
if (pup_zero)
return surr_rate + pup_rate;
// For gimla products, we wish to make all lapses be instead calculated as PUPs from a set age
if (gimla_prod_ind && age_exact_b(t) >= lapsecancel_age)
return 0.0;
//Rates differ for Klassi
if (klassi_prod_ind){
if (t < maturity_period_w - 2)
return surr_rate_klassi;
if (t <= maturity_period_w + 2)
return surr_rate_klassi_mat;
//After maturity
return surr_rate_klassi_postmat;
}
// At all other times, including for non-gimla products, return the table rate
return surr_rate;
//surr_rate (poli_year(t),
lapse_group(prod_fund_name))
/* AH 14/2/16 - Created column
DC 1/3/16  - set the zeroing out condition to be in relation to a table age rather than fixed 60
DC 15/8/17 - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
NB 21/12/21 - CR261 - for non-savings policies, total lapse rate includes pup rate - lapse
vector can be savings for risk rider of savings
NB 31/12/23 - CR349 - For Klassi policies, take surrender rates from Klassi table instead of
standard table
*/

//Surrender value after maturity, rolling up with credited interest
if (!klassi_prod_ind)
return NO_AVG;
if (t < maturity_period_w || t > maturity_period_last_w)
return NO_AVG;
if (t == 1 && age_exact_issue + elapsed_years > maturity_age)
return sum_assured_init_data + bonus_data;
if (t == maturity_period_w){
if (abs(poli_if_b(t) + pups_if_b(t)) > SMALL_DOUBLE)
return (res_bal_b(t) + pup_res_bal_b(t))
/ (poli_if_b(t) + pups_if_b(t))
* (1. + inv_ret_bonus_pup_pre(t));
}
//t > maturity_period_w
return surrender_value_postmat(t-1)
* (1. + inv_ret_bonus_pup_pre(t));
/*
NB 31/12/23 - CR349 - Added column
*/

/* Returns the number of starting coverages multiplied by inforce */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return tariffs_count * (poli_if_b(t) + pups_if_b(t));
/*
OS 09/05/17 - Added new field for the number of policies multiply by inforce.
DC 16/08/17 - Added a condition to limit calculation to between the commencement and last
maturity periods
*/

/* Reports the value of all maturities in the period */
/*For MiglifePost13, we calculate the maturities as if the TUR = 0 -  i.e all as a lump sum */
if (t < commence_period_w+1 || t < maturity_period_first_w || t > maturity_period_last_w)
return NO_AVG;
/*This column is only read when boundries exists.
Therefore, the folowing condition is correct even if it means that the code
in row 53 is not read.
The condition is for runs in Gen2, so no unnecessary code will run */
if (prod_code == ANPY || !bdry_by_mekademage_ind )
return NO_AVG;
if (maturity_pay == 0)
return NO_AVG;
if (prod_code == ANPY && t == maturity_period_first_w)
return 0.0;
// Otherwise at maturity period(s)
double persistency_bonus_act = 1.0;
double persistency_bonus_pup = 1.0;
double maturities_paid= 0.0;
double pup_maturities_paid= 0.0;
double as_maturities_paid= 0.0;
if ((prod_code == MIGM || prod_code == MIGP || prod_code == MIGLIFE)) {
if(prod_year == 2006){
persistency_bonus_act = 1.0 + mig_eff_bonus * duration_b(t)
* 1.0 *
mig_duration_fact *annuity_perc_mat(t);
persistency_bonus_pup = 1.0 + mig_eff_bonus * duration_b(t)
* 0.5 *
mig_duration_fact *annuity_perc_mat(t);
}
// Remaining products
//Calculation for Miglifepost13 contract boundaries, we assume that that all the maturities are
taken in a lump sum
if (bdry_by_mekademage_ind){
pup_maturities_paid =  persistency_bonus_pup
* (pup_res_bal_b(t) * (1.0 +
inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t) - pup_clm_paid(t)
- pup_surr_paid(t)/ sv_mult_prod * 100.0)
* (1.0 + inv_ret_bonus_pup_pre(t) / 2.0))
* gimla_ret_prob_b(t+1);
maturities_paid = (surrender_value_b(t) + bonus_b(t))
* persistency_bonus_act
* pol_matd(t) * maturity_pay;
as_maturities_paid =  sav_b_res(t) * pol_matd(t);
return as_maturities_paid+ maturities_paid + pup_maturities_paid;
}
maturities_paid = (surrender_value_b(t) + bonus_b(t))
* persistency_bonus_act
* pol_matd(t) * maturity_pay
* (1.0 - annuity_perc_mat(t));
pup_maturities_paid  = persistency_bonus_pup * (1.0 - annuity_perc_mat(t))
* (pup_res_bal_b(t) * (1.0 +
inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t) - pup_clm_paid(t)
- pup_surr_paid(t)/ sv_mult_prod * 100.0)
* (1.0 + inv_ret_bonus_pup_pre(t) / 2.0))
* gimla_ret_prob_b(t+1);
as_maturities_paid =  sav_b_res(t) * pol_matd(t) * (1.0 - annuity_perc_mat(t));
return as_maturities_paid+ maturities_paid + pup_maturities_paid;
}
if (prod_code == ADIF    ||
prod_code == ADIF92  ||
prod_code == ADIFOLD ) {
maturities_paid = (surrender_value_b(t) + bonus_b(t))
* persistency_bonus_act
* pol_matd(t) * maturity_pay
* (1.0 - annuity_perc_mat(t));
pup_maturities_paid = (1.0 - annuity_perc_mat(t))
* (pup_res_bal_b(t) * (1.0 +
inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t) - pup_clm_paid(t) -
pup_surr_paid(t))
* (1.0 + inv_ret_bonus_pup_pre(t) / 2.0))
* gimla_ret_prob_b(t+1);
as_maturities_paid =  sav_b_res(t) * pol_matd(t) * (1.0 - annuity_perc_mat(t));
return as_maturities_paid+ maturities_paid + pup_maturities_paid;
}
//Klassi products
if (t > maturity_period_w)
return (1.0 - annuity_perc_mat(t))
* surrender_value_postmat(t)
* maturity_pay * pups_matd(t);
if (t < maturity_period_w)
pup_maturities_paid = (1.0 - annuity_perc_mat(t))
* pup_res_bal_b(t)
/ pups_if_b(t)
* (1.0 + inv_ret_bonus_pup_pre(t)) // Add full period of
interest
* pups_matd(t);
else
pup_maturities_paid =  (1.0 - annuity_perc_mat(t)) * (maturity_pay * pups_matd(t)
* pups_reserve(t)
/ sum_assured_basic_b(t)
* pups_avg_value(t)
- (pups_if_b(t) + pups_new(t)) * pup_fee /
pv_period_im);
maturities_paid = (surrender_value_b(t) + bonus_b(t))
* persistency_bonus_act
* pol_matd(t) * maturity_pay* (1.0 - annuity_perc_mat(t));
as_maturities_paid =  sav_b_res(t) * pol_matd(t)* (1.0 - annuity_perc_mat(t));
return as_maturities_paid+ maturities_paid + pup_maturities_paid;
