ModelRes = ModelRes - bonus_data;
if (!(abs(ModelRes) < SMALL_DOUBLE))
return (DataRes - ModelRes) / (ModelRes + gimla_feff_res_b(t))
* (tot_pv_inv_inc(t) - tot_pv_res_inc(t))
* reserve_adj/v_factor_pre(t);
return DataRes;
//zero calculated reserve
}
return 0.0;
