lp = lp * liqprem_propn_post_maturity;
//liqprem_propn(prod_code,
"post_maturity")
// Add on the liquidity premium to base rate, change to a period discount rate, and return
return 1.0 / pow(1.0 + rate + lp, 1.0 / pv_period_im);
