return 0.0;
return res_dec_id
* (1.0 - pow(1. - res_pwdrwl_act_perc_tbl * lapse_scaling_factor_actres,
1.0/pv_period_im)) * (1.0 - gimla_ret_prob_b(t+1));
/* DC 18/02/13 - added data-level scaling factor
DC 06/04/14 - added case for MIGLIFE2013 to take from a separate row in the table.
DC 02/07/14 - correction to position of application of data-level scaling factor
DC 01/02/16 - zeroed out these lapses for gimla products post-age60
DC 01/03/16 - set the zeroing out condition to be in relation to a table age rather than fixed
60
OS 31/07/16 - Changed "Prod_code_sub" to be enumerated value
OS 08/08/16 - res_clm_act_perc - A variable that checks the lookup value , according to
res_clm_act_row_lkp (a scalar that calculates the row lookup : newpar /
oldpar/ nonpar/miglife2013)
DC 15/08/17 - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
GR 30/01/19 - CR69 - Added product by (1-gimla_ret_prob_b(t+1)) to relate to active (not
retired) population only. Changed column name from res_clm_active_reduct
*/

/* Cash value of partial withdrawals at time of going paid-up, basic savings */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (duration_b(t) < elapsed_years)
return 0.0;
return res_dec_id * sav_a_res_pwdrwl_atpup(t) * poli_if_b(t+1);
/*
OS 28/09/16 - CR83 - changed 0 to 0.0
GR 30/01/19 - CR69 - name changed from res_clm_payup
*/

/* Partial withdrawal rate from active policy at the point of it being made paid-up */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// For gimla products after a set age, these lapses are already included in the take-up rates,
//    so we zero here to avoid double counting
if (gimla_prod_ind && age_exact_b(t) >= lapsecancel_age)
return 0.0;
int cutoff = lapse_scaling_yr_oldprods;
double old_fac = 1.0;
if ((prod_year > cutoff) &&  ((valn_year + proj_yr(t))>=2012))
old_fac = 0.9;
return
res_dec_id * pup_rate_vector(t)
* res_pwdrwl_atpup_perc_tbl * old_fac
* lapse_scaling_factor_pupres;
/* DC 14/02/13 - added lapse scaling factor
DC 01/02/16 - zeroed out these lapses for gimla products post-age60
DC 01/03/16 - set the zeroing out condition to be in relation to a table age rather than fixed
60
DC 15/08/17 - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
DC 01/01/18 - CR250 - now use valn_year rather than valn_year-1
GR 30/01/19 - CR69 - renamed from res_clm_payup_reduct
*/

/* Start period regular reserve */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind)
return sav_a_res(t);
if (prod_code == RISK || prod_code == RMASH || prod_code == DD)
return 0.0;
if (prod_code == END || prod_code == ENDM92 || prod_code == ENDP92 ||
prod_code_sub == PHIFP) {
if (t < maturity_period_w+1 - pv_period_im)
return (reserve_rate_b(t+1) * (1.0 - poli_period(t+1))
+ reserve_rate_b(t + pv_period_im + 1) * poli_period(t+1))
* sum_assured_basic_b(t) / prem_rate_factor;
return (reserve_rate_b(t+1) * (1.0 - poli_period(t+1))
+ reserve_rate_b(maturity_period_w+1) * poli_period(t+1))
* sum_assured_basic_b(t) / prem_rate_factor;
}
if (prod_code == HO && prod_code_sub != SERVICE) {  // Katsman reserve calculation
if (t == commence_period_w+1)
return 0.0;
// Calculation in the rise period
if (duration_b(t) * pv_period_im <= res_briut_rise_periods)
return reserve_b(t-1)
+ basic_prem(t) / pv_period_im * res_briut_prem_pc
* (1.0 - (duration_b(t) * pv_period_im - 1.0)
/ (res_briut_rise_periods - 1.0));
// Calculation in the fall period
return reserve_b(t-1)
- reserve_b(commence_period_w + res_briut_rise_periods)
/ (0.5 * pow(benefit_term * pv_period_im - res_briut_rise_periods,
2.0)
+ 0.5 * (benefit_term * pv_period_im - res_briut_rise_periods))
* (duration_b(t) * pv_period_im - res_briut_rise_periods);
}
if (prod_code == FTEND || prod_code == LTC || prod_code == CLSAVINGS ||
(prod_code_sub == PERS_ACC && prem_type == "FP")) {
if (t < maturity_period_w+1 - pv_period_im)
return (reserve_rate_b(t+1) * (1.0 - poli_period(t+1))
+ reserve_rate_b(t + 1 + pv_period_im) * poli_period(t+1))
* sum_assured_init_model / prem_rate_factor;
return (reserve_rate_b(t+1) * (1.0 - poli_period(t+1))
+ reserve_rate_b(maturity_period_w+1) * poli_period(t+1))
* sum_assured_init_model / prem_rate_factor;
}
// All other products
return 0.0;
/* DC 17/11/14 - Tidied formula.  Moved CLSAVINGS code in with LTC as it was identical.
ES 29/12/14 - changed IF condition to be prod_code == "HO || prod_code == "PERS_ACC"
rather prod_code == "SURG" || prod_code == "H10" || prod_code == "HR".
DC 01/11/15 - Changed prod_code lookups to enumerated variables
ES 03/11/15 - Changed reserve calculation code (Katsman reserve) for  HO (except SERVICE).
Added clause for PERS_ACC_FP to do the same as LTC.
AH 04/11/15 - Removed clause for ANPY
DC 13/04/16 - Replaced calculated SA (basic prem / GPR ) with a link to the scalar
sum_assured_init_model / PRF in the clause including LTC
OS 31/07/16 - Changed "Prod_code_sub" to be enumerated value
OS 04/12/16 - replace the condition term with the scalar savings_prod_ind
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
OS 09/01/17 - Replaced 1 with 1.0
OS 06/11/17 - CR159 - Added RMash to condition in line 9
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
NB 31/12/23 - CR349 - Change maturity_period_last_w to maturity_period_w for Klassi policies
*/

/* Reserving rate to apply */
if (prod_code == CLSAVINGS && t > maturity_period_w)
return max(reserve_rate_b(t-1), prem_rate_factor);
if (t < commence_period_w+1 || t > max (maturity_period_w, maturity_period_last_w) + 6)
return NO_AVG;
int x1 = xint(age_exact_b_prem(t));
int xn = maturity_age;
double xx1 = age_exact_b_prem(t);
double xxn = maturity_age_prem;
if (prod_code == ADIF || prod_code == DD)
return 0.0;
if (prod_code == END) {
double biga = ((res_mx(x1,0)-res_mx(xn,0))
*(1.+tariff_int_rate/2.)+res_dx(xn,0))/res_dx(x1,0);
double littlea = (res_nx(x1,0)-res_nx(xn,0))/res_dx(x1,0);
double res_b = prem_rate_factor * biga
- net_prem_rate_b(t) * littlea;
double factor_b = max(1.0, sv_mult_prod_prev/100.0);
return res_b * factor_b;
}
if (prod_code == PERS_ACC && prem_type == "FP")
return prem_rate_factor * biga_b(t)
- net_prem_rate_b(t) * littlea_b(t);
if (prod_code == FTEND) {
double biga     = pow(1/(1+tariff_int_rate),maturity_age_prem-age_exact_issue-
poli_year(t)+1);
double littlea  = (res_nx(x1,0)-res_nx(xn,0))/res_dx(x1,0);
double factor_b = max(1.0, sv_mult_prod_prev / 100.0);
return (prem_rate_factor * biga - net_prem_rate_b(commence_period_w+1) * littlea)
* factor_b;
}
if (prod_code == ENDM92 || prod_code == ENDP92) {
if (poli_year(t)<2)
return 0.;
double biga = (res_mx(x1,0)-res_mx(xn,0)+res_dx(xn,0))/res_dx(x1,0);
double biga_bar = (res_mx_bar(x1,0)-res_mx_bar(xn,0)+res_dx(xn,0))/res_dx(x1,0);
double littlea = (res_nx(x1,0)-res_nx(xn,0))/res_dx(x1,0);
double res_b = prem_rate_factor*(biga*(1.-end_p1)+biga_bar*end_p1)-
net_prem_rate_b(t)*littlea;
double factor_b = max(1.0, sv_mult_prod_prev / 100.0);
return res_b * factor_b + end_p11/1000.0*1000.0*(poli_year(t)-1.0)*biga;
}
if (prod_code == CLSAVINGS || prod_fund_name == PHIFP_OLD || prod_fund_name == PHIFP_99)
return prem_rate_factor * biga_b(t)
- net_prem_rate_b(commence_period_w+1) * littlea_b(t);
if (prod_code_sub == PHIFP && prod_fund_name != PHIFP_OLD && prod_fund_name != PHIFP_99) { //
currently SHLV and MH
double biga = (res_adj_nx(xx1,0)-res_adj_nx(xxn,0)) / res_dx(xx1,0);
double littlea = (res_nx(xx1,0)-res_nx(xxn,0)) /res_dx(xx1,0);
double res_b = prem_rate_factor * biga
- net_prem_rate_b(commence_period_w+1) * littlea;
double factor_b = max( 1.,sv_mult_prod_prev/100.);
return res_b * factor_b;
}
if (prod_code == LTC) {
double res_b = prem_rate_factor * biga_b(t)
- net_prem_rate_b(t) * littlea_b(t);
double factor_b = max(1.0, sv_mult_prod_prev/100.0);
return res_b * factor_b;
}
// For all other products:
return 0.0;
/*
DC 07/10/14 - moved the lookup of morbid_trend_fac from prod_code to prod_fund_name. Tidied
formula.
ES 29/12/14 - Changed IF condition to be prod_code_sub == "SURG" rather than
prod_code == "SURG" || prod_code == "H10.
Moved the lookup of mort_sel_per from prod_code to prod_code_sub
DC 01/11/15 - Now looks up select years from the new scalar mort_params_select_yrs
DC 01/11/15 - Changed prod_code lookups to enumerated variables
ES 03/11/15 - Added a clause for PERS_ACC FP only to calculate a net premium reserve rate
ES 03/11/15 - Deleted the section for SURG, which had calculated a Rotfeld reserve rate
AH 04/11/15 - Removed ANPY clause
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
DC 06/01/19 - CR259 - LTC now uses sv_mult_prod_prev rather than sv_mult_ltc_prev
NB 09/02/22 - CR341 - Changed prod_codes for Adif
SK 14/02/22 - CR354 - Changing 'age_exact_b' to 'age_exact_b_prem' and 'maturity_age' to
'maturity_age_prem'
SK 09/07/23 - CR433 - Tidied code and comments
NB 31/12/23 - CR349 - Zeroed out after maturity for Klassi products
*/

/* Basic savings accumulation, including the period's premium and investment return */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!savings_prod_ind)
return 0.0;
// For active policies, we set the reserve just before t=1 to match to the data reserve
if (t==0 && pup_mult==0) {
// We remove the bonus from the accumulation, so the surrender value is only on "saving a"
accumulation
if (prod_code == ADIF    ||
prod_code == ADIF92  ||
prod_code == ADIFOLD)
return (current_reserve - current_reserve_as - bonus_data) * reserve_adj;
return current_reserve * reserve_adj;
}
double rate1 = pow(pow(1.0 + inv_ret_bonus_act_pre(t),pv_period_im), 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
return (sav_a_accm(t-1) * rate2 + (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) + mig_prem_sav(t))
* standard_savings * (rate2 - 1.0)
/ (rate1 - 1.0) * rate1)
* (1.0 - res_pwdrwl_act_rate(t) - res_pwdrwl_atpup_rate(t));
/*
DC 23/12/14 - Tidied formula, including removing t>0 clause that wasn't being picked up
DC 3/1/16 - At t=0end, grosses reserve up to data reserve, if the policy is active.  This is
in
place of the adjustment in pup_res_bal_b in these cases.
DC 3/1/16 - Changed adjustment to be just to the level of the basic savings reserve, because
we now
get the additional savings reserve as a separate additional data
item.
OS 17/8/16  - CR70  Type comparison correction - changed pup_mult type to int
OS 28/09/16 - replaced column sav_standard to get the value directly from  the variable
standard_savings
OS 18/03/21 - CR320 - Removed the bonus from the accumulation, and now the sv is calculated
on saving a only (no double counting)
SK 05/08/21 - CR356 - Returning zero for non-savings products
NB 09/02/22 - CR341 - Changed prod_codes for Adif
*/

/* Basic savings accumulation taken as partial withdrawal, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!savings_prod_ind)
return 0.0;
double rate1 = pow(1.0 + inv_ret_bonus_act_pre(t), pv_period_im);
rate1 = pow(rate1, 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
return (sav_a_accm(t-1) * rate2
+ (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) + mig_prem_sav(t))
* standard_savings
* (rate2 - 1.0) / (rate1 - 1.0)
* rate1)
* res_pwdrwl_act_rate(t);
/*
DC 04/11/14 - tidied formula
OS 28/09/16 - replaced column sav_standard to get the value directly from  the variable
standard_savings
GR 30/01/19 - CR69 - renamed from sav_a_accm_active
SK 05/08/21 - CR356 - Returning zero for non-savings products
*/

/* Partial withdrawal from basic savings accumulation at point of going paid-up, before
survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!savings_prod_ind)
return 0.0;
double rate1 = pow(pow(1.0 + inv_ret_bonus_act_pre(t),pv_period_im), 1.0 / 12.0 );
double rate2 = pow(rate1, 12.0 / pv_period_im);
return (sav_a_accm(t-1) * rate2 + (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) + mig_prem_sav(t))
* standard_savings * (rate2 - 1.0)
/ (rate1 - 1.0) * rate1)
* res_pwdrwl_atpup_rate(t);
/* DC 23/12/14 - Tidied formula, including removing t>0 clause that wasn't being picked up
OS 28/09/16 - replaced column sav_standard to get the value directly from  the variable
standard_savings
GR 30/01/19 - CR69 - renamed from sav_a_accm_payup
SK 05/08/21 - CR356 - Returning zero for non-savings products
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return max(sav_a_accm(t), sav_a_sv(t));
/* DC 17/12/14 - Tidied formula
*/

/* Cash value of partial withdrawals from active basic savings, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return max(sav_a_accm_pwdrwl_act(t), sav_a_sv_pwdrwl_act(t));
/* DC 24/12/14 - Tidied formula
GR 30/01/19 - CR69 - changed name from sav_a_res_active
*/

/* Partial withdrawal from basic savings reserve at point of going paid-up, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return max(sav_a_accm_pwdrwl_atpup(t), sav_a_sv_pwdrwl_atpup(t));
/* DC 24/12/14 - Tidied formula
GR 30/01/19 - CR69 - renamed from sav_a_res_payup
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return sav_a_accm(t) * (sv_mult_prod_prev * (1.0 - poli_period(t))
//sv_mult(poli_year(t) - 1, prod_code)
+ sv_mult_prod * poli_period(t))
//sv_mult(poli_year(t), prod_code)
/ 100.0;
/* DC 24/12/14 - Tidied formula
*/

/* Decrease in surrender value on active basic savings because of partial
withdrawals, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return sav_a_accm_pwdrwl_act(t) * (sv_mult_prod_prev * (1.0 - poli_period(t))
+ sv_mult_prod * poli_period(t))
/ 100.0;
/* DC 24/12/14 - Tidied formula
GR 30/01/19 - CR69 - changed name from sav_a_sv_active
*/

/* Partial withdrawal from basic savings surrender value at point of going paid-up, before
survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return sav_a_accm_pwdrwl_atpup(t) * (sv_mult_prod_prev * (1.0 - poli_period(t))
+ sv_mult_prod * poli_period(t))
/ 100.0;
/* DC 24/12/14 - Tidied formula
GR 30/01/19 - CR69 - renamed from sav_a_sv_payup
*/

/* Additional savings accumulation, including the period's premium and investment return */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if(!savings_prod_ind)
return 0.0;
// For active policies, we set the reserve just before t=1 to match to the data additional savings
reserve
if (t==0 && pup_mult==0) {
if (prod_code == ADIF ||
prod_code == ADIF92  ||
prod_code == ADIFOLD)
return current_reserve_as * reserve_adj;
//reserve_adj(par_nonpar,1)
return 0.0;
}
double rate1 = pow(pow(1.0 + inv_ret_bonus_as(t), pv_period_im), 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
return (sav_b_accm(t-1) * rate2
+ (fxd_sa_add_sav(t) + fxd_sav_add_sav(t)) * (rate2 - 1.0) / (rate1 - 1.0) *
rate1)
* (1.0 - res_pwdrwl_atpup_rate(t) - res_pwdrwl_act_rate(t));
/* DC 24/12/14 - Tidied formula
DC 3/1/16 - At t=0end, grosses reserve up to data reserve, if the policy is active.  This is in
place of the adjustment in pup_res_bal_b in these cases.
DC 3/1/16 - Changed t=0end adjustment to be to the exact level of the additional savings
reserve,
as we now receive this as a separate additional data item.
DC 3/1/16 - Changed the source of the investment return to be from the new column
invest_return_bonus_as
SK 05/08/21 - CR356 - Returning zero for non-savings products
NB 09/02/22 - CR341 - Changed prod_codes for Adif
*/

/* Partial withdrawals from active addition savings accumulation, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!savings_prod_ind)
return 0.0;
double rate1 = pow(pow(1.0 + inv_ret_bonus_as(t), pv_period_im), 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
return (sav_b_accm(t-1) * rate2
+ (fxd_sa_add_sav(t) + fxd_sav_add_sav(t)) * (rate2 - 1.0) / (rate1 - 1.0) *
rate1)
* res_pwdrwl_act_rate(t);
/* DC 24/12/14 - Tidied formula
DC 03/01/16 - Changed the source of the investment return to be from the new column
invest_return_bonus_as
GR 30/01/19 - CR69 - changed name from sav_b_accm_active
SK 05/08/21 - CR356 - Returning zero for non-savings products
*/

/* Additional savings active accumulation withdrawn when going paid-up, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!savings_prod_ind)
return 0.0;
double rate1 = pow(pow(1.0 + inv_ret_bonus_as(t), pv_period_im), 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
return (sav_b_accm(t-1) * rate2
+ (fxd_sa_add_sav(t) + fxd_sav_add_sav(t)) * (rate2 - 1.0) / (rate1 - 1.0) *
rate1)
* res_pwdrwl_atpup_rate(t);
/* DC 24/12/14 - Tidied formula
DC 03/01/16 - Changed the source of the investment return to be from the new column
invest_return_bonus_as
GR 30/01/19 - CR69 - renamed from sav_b_accm_payup
SK 05/08/21 - CR356 - Returning zero for non-savings products
*/

/* Additional savings active reserve, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind == 1)
return sav_b_accm(t);
// Other products
return 0.0;
/* DC 24/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 04/12/16 - replace the condition term with the scalar savings_prod_ind
GR 30/01/19 - CR69 - renamed from sav_res
*/

/* Additional savings active accumulation taken as partial withdrawal, before survivorship */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind == 1)
return sav_b_accm_pwdrwl_act(t);
// Other products
return 0.0;
/* DC 23/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 04/12/16 - replace the condition term with the scalar savings_prod_ind
GR 30/01/19 - CR69 - renamed from sav_b_res_active
*/

/* Additional savings active reserve withdrawn at point of going paid-up */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind == 1)
return sav_b_accm_pwdrwl_atpup(t);
// Other products
return 0.0;
/* DC 23/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 04/12/16 - replace the condition term with the scalar savings_prod_ind
GR 30/01/19 - CR69 - renamed from sav_b_res_payup
*/

if (t < commence_period_w+1 || t > maturity_period_w+1)
return NO_AVG;
if (klassi_prod_ind && age_exact_issue + elapsed_years > maturity_age)
return NO_AVG;
if (prod_code == FTEND || prod_code == CLSAVINGS || prod_code == LTC) {
double factor = min(1.0, sv_mult_prod_prev/100.0);
return reserve_rate_b(t) * factor;
}
/* Endowment products */
if (prod_code == END) {
int x1 = xint(age_exact_b(t));
int xn = maturity_age;
if(res_dx(x1,0) == 0)
return 0.0;
double biga = ((res_mx(x1,0)-res_mx(xn,0)) * (1.0 + tariff_int_rate / 2.0) + res_dx(xn,0))
/res_dx(x1,0);
double littlea = (res_nx(x1,0)-res_nx(xn,0)) / res_dx(x1,0);
double res_b = prem_rate_factor * biga - net_prem_rate_b(t) * littlea;
double factor_a = min(1.0, sv_mult_prod_prev / 100.0);
double factor_b = max(1.0, sv_mult_prod_prev / 100.0);
return res_b * factor_a * factor_b;
}
if (prod_code == ENDM92 || prod_code == ENDP92) {
double big_a_x = (surr_mx_bar(age_exact_b(t), 0) - surr_mx_bar(maturity_age, 0)
+
surr_dx(maturity_age, 0))
/ surr_dx(age_exact_b(t), 0);
double big_a_issue = (surr_mx_bar(age_exact_issue, 0)- surr_mx_bar(maturity_age, 0)
+ surr_dx(maturity_age, 0))
/ surr_dx(age_exact_issue, 0);
double little_a_x = (surr_nx(age_exact_b(t), 0) - surr_nx(maturity_age, 0))
/ surr_dx(age_exact_b(t), 0);
double little_a_issue = (surr_nx(age_exact_issue, 0) - surr_nx(maturity_age, 0))
/ surr_dx(age_exact_issue, 0);
double z = gross_prem_rate_b(t) / prem_rate_factor
* min(end_p7 * (maturity_age -
age_exact_issue), end_p8)
* end_p5 * (1.0 + end_p9)
* min(poli_year(t) - 1.0,
end_p10)/end_p10
+ end_p3;
if (poli_year(t) < 2 && t < maturity_period_w+1)
return 0.0;
if (poli_year(t) == 2)
return end_p12 * gross_prem_rate_b(t) * (poli_year(t) - 1.0);
if (poli_year(t) >= 3 && t < maturity_period_w+1)
return max((big_a_x - (big_a_issue / little_a_issue + z / little_a_issue) *
little_a_x
+ (poli_year(t) - 1.0) * end_p11 / 1000.0 * big_a_x) *
1000.0,
end_p12 * gross_prem_rate_b(t) * (poli_year(t) - 1.0));
if (t == maturity_period_w+1)
return max((1.0 + (poli_year(t) - 1.0) * end_p11 / 1000.0 * big_a_x) * 1000.0,
end_p12 * gross_prem_rate_b(t) * (poli_year(t) - 1.0));
}
// Remaining products
return 0.0;
/* DC 23/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
AH 04/11/15 - Removed ANPY clause
OS 28/09/16 - changed condition of prod_code ADIFM + DD
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
DC 06/01/19 - CR259 - LTC now uses sv_mult_prod_prev
NB 31/12/23 - CR349 - Zeroed out for Klassi policies if age at valuation is greater than
maturity age
*/

/* Present value of reserves coming to maturity at all future maturity periods  */
if (t < 1)
return NO_AVG;
if (t > maturity_period_last_w)
return 0.0;
return (tot_pv_final_reserve(t+1) + final_reserve(t)) * v_factor_pre(t);
/* Reporting column */
/*
ES 06/05/15 - Added column.
OS 22/12/16 - Changed calculation to return the Present value of reserves coming to maturity
at all future maturity periods
*/

/* Present value of reserves going to gimla at all future maturity periods  */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (tot_pv_final_reserve_togimla(t+1) + maturities_togimla(t) + as_maturities_togimla(t) +
pup_maturities_togimla(t)) * v_factor_pre(t);
/* Reporting column */
/*
DC 18/02/19 - Added column.
SK 05/08/21 - CR356 - Adjusting the time guard
*/

/* PV of the deficiency in the gimla reserve */
if (t < commence_period_w+1 || !gimla_prod_ind)
return NO_AVG;
if(bdry_by_mekademage_ind)
if (t >= maturity_period_first_w && t<= maturity_period_last_w){
double gimlaData = 0.0;
int i, j;
for (i = 0; i < sm_maslul.size(); i++)
for (j =xint(age_exact_b(t))-gimla_firstretage; j >=0 && j< gimla_lastretage-
gimla_firstretage; j--)
gimlaData = gimlaData + sm_maslul[i][j]->tot_pv_gimla_def(t);
return gimlaData;
}
//no contract bounadries
if (t > maturity_period_first_w)
return sm_maslul->tot_pv_gimla_def(t);
// Before maturity_period_first_w we discount back
return tot_pv_gimla_def(t+1) * v_factor_pre(t);
/* Reporting column */
/* DC 16/12/15 - Added column.
DC 01/02/16 - Changed code completely to reflect new calculation methodology.
OS 09/04/17 - CR145 - Change reporting column to use the sub model gimla deficiency field
DC 15/08/17 - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Changed the condition to use gimla_prod_ind rather than gimla_postmat_ind
OS 20/01/22 - CR379 - Contract boundaries full implementation
*/

/* Returns the start-period value of all reserves */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w && !gimla_prod_ind)
return NO_AVG;
return as_res_b(t) + res_bal_b(t) + pup_res_bal_b(t)
+ gimla_res_b(t) + gimla_feff_res_b(t);
/* ES 13/11/14 - Moved initial conditions check to indicator column nogimla_postmat_ind.
AH 4/11/15 - Removed anpy_add_res from equation - this reserve no longer exists
OS 22/02/17 - CR128 Replaced gimla feff res in the end of the period  (time t-1) with gimla feff
res in the beginning of the period (time t)
OS 22/02/17 - CR128 Replaced gimla res in the end of the period  (time t-1) with gimla res in
the beginning of the period (time t)
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Rewrote initial conditions
*/

/* Total reserve entitled to hetz */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w && !gimla_prod_ind)
return NO_AVG;
return tot_res(t) * inv_pct_hetz;
/*
ES 13/11/14 - Moved initial conditions check to indicator column nogimla_postmat_ind.
OS 28/09/16 - replaced column  to get the value directly from  the variable inv_pct_hetz
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Rewrote initial conditions
*/

/* Returns the increase in the hetz-backed reserve in the period */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w && !gimla_prod_ind)
return NO_AVG;
return tot_res_hetz(t+1) - tot_res_hetz(t);
/*
ES 13/11/14 - Moved initial conditions check to indicator column nogimla_postmat_ind.
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Rewrote initial conditions
*/

/* Claims ceded to reinsurer in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == LTC) {
//from 2017 treaty, paid up policies are also in the reinsurance calculations
if (ltc_reins_pup_ind)
return ltc_reins_claims_pct * (claims_paid(t) + pup_clm_paid(t)) * (1 +
supplier_exp_rate);
return ltc_reins_claims_pct * claims_paid(t) * (1 + supplier_exp_rate);
}
if (prod_code == HO) {
if (ho_reins_treaty == "Maccabi_Single")
return claims_paid(t) * (1 + supplier_exp_rate) * ho_reins_pct;
if (prod_year < ho_prod_year && (ho_reins_treaty != "na"))
return claims_paid(t) * (1 + supplier_exp_rate) * ho_reins_pct;
}
// All other products
return reins_sum_risk(t) * pol_clm(t) * (1 + supplier_exp_rate);
/*
OS 04/12/16 - changed formula to calculate reinsurance claims for LTC
MG 21/01/20 - CR296 - changed LTC clause to include PUP policies in the reinsurance
calculations
TA 27/12/20 - CR276 - Added rein claims calculations according to treaty type for HO
products.
MG 06/18/24 - CR336 - added suppliers expense rate
*/

/* Claims ceded to reinsurer in the period - including future business for IFRS */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (run_type != "IFRS" || !nb_ind || treaty_period / pv_period_im == 1)
return reins_claims(t);
/*
When the valuation date is the end of the first quarter, we assume that sales in the 2nd quarter
will be the same as in the first, and so we multiply by 2.
(Hard-coding to avoid incorrect calculation due to zero claims at t=0.)
Once a full valuation year has been completed (and t=0 is no longer referenced), the calculation
progresses recursively.
*/
if (valn_month == 3){
if (t == 1)
return reins_claims(t) * 2.0;
if (t == 2)
return reins_claims(t) + reins_claims(t - 1) * 2.0;
if (t == 3)
return reins_claims(t) + reins_claims(t - 1) + reins_claims(t - 2) * 2.0;
return reins_claims(t) + reins_claims(t - 1) + reins_claims(t - 2) + reins_claims(t - 3);
}
// When the valuation date is the end of the 2nd quarter, the value at time 1 is equal to 2
quarters' worth of sales - hence we divide by 2
if (valn_month == 6){
if (t == 1)
return reins_claims(t) + reins_claims(t) * 1.0/2.0;
if (t == 2)
return reins_claims(t) + reins_claims(t - 1) * 1.0/2.0 + reins_claims(t - 1) *
1.0/2.0;
return reins_claims(t) + reins_claims(t - 1) * 1.0/2.0 + reins_claims(t - 2) * 1.0/2.0;
}
// When the valuation date is the end of the 3rd quarter, the value at time 1 is equal to 3
quarters' worth of sales - hence we divide by 3
if (valn_month == 9){
if (t == 1)
return reins_claims(t) + reins_claims(t) * 1.0/3.0;
return reins_claims(t) + reins_claims(t - 1) * 1.0/3.0;
}
// When the valuation date is the end of the 4th quarter, the reinsurance contract is due for
renewal and so there is no need to assume future sales
return reins_claims(t);
/*
SK 04/02/22 - CR376 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Commission received from reinsurer */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == DD ) {
if (poli_year(t) == 1)
return reins_prem(t) * dd_reins_comm_fac_yr1;
// Year 2 and onwards
return reins_prem(t) * dd_reins_comm_fac_fromyr2;
}
if (prod_code == ADIS && poli_year(t) > 1)
return reins_prem(t) * 0.25;
if (prod_code == PHI) {
if (phi_reins_treaty == "ShalvaFlat")
return reins_prem(t) * phi_reins_comm_fac;  // 32.5% of premium for the whole policy
lifetime
if (poli_year(t) == 1)  // for other PHI treaties, commission - where it exists - is only in
the first year
return reins_prem(t) *phi_reins_comm_fac;
return 0.0;
}
if ((prod_code == HO) &&  (poli_year(t) == 1) && (ho_reins_treaty!= "na"))
return reins_prem(t) * ho_comm_fac_yr1;
// For other products, commission is 100% 1st year premium
if (poli_year(t) == 1)
return reins_prem(t);
return 0.0;
/* DC 22/12/14 - Tidied formula
DC 01/11/15 - Removed the clause for the deprecated DI product
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 06/11/17 - CR159 - Removed ADISOLD from the condition as not needed in new hierarchy
OS 23/01/19 - CR14 - added new conditions for DD and PHI reinsurance
TA 27/12/20- CR276- Added rein comm calculations (first year only) for HO products.
TA 10/01/21 - CR331 - Correction for "shalva2017" to match reinsurance treaty - commission in
first year.
*/

/* Commission received from reinsurer - including future business for IFRS */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (run_type != "IFRS" || !nb_ind || treaty_period / pv_period_im == 1)
return reins_comm(t);
/*
When the valuation date is the end of the first quarter, we assume that sales in the 2nd quarter
will be the same as in the first, and so we multiply by 2.
(Hard-coding to avoid incorrect calculation due to zero claims at t=0.)
Once a full valuation year has been completed (and t=0 is no longer referenced), the calculation
progresses recursively.
*/
if (valn_month == 3){
if (t == 1)
return reins_comm(t) * 2.0;
if (t == 2)
return reins_comm(t) + reins_comm(t - 1) * 2.0;
if (t == 3)
return reins_comm(t) + reins_comm(t - 1) + reins_comm(t - 2) * 2.0;
return reins_comm(t) + reins_comm(t - 1) + reins_comm(t - 2) + reins_comm(t - 3);
}
// When the valuation date is the end of the 2nd quarter, the value at time 1 is equal to 2
quarters' worth of sales - hence we divide by 2
if (valn_month == 6){
if (t == 1)
return reins_comm(t) + reins_comm(t) * 1.0/2.0;
if (t == 2)
return reins_comm(t) + reins_comm(t - 1) * 1.0/2.0 + reins_comm(t - 1) * 1.0/2.0;
return reins_comm(t) + reins_comm(t - 1) * 1.0/2.0 + reins_comm(t - 2) * 1.0/2.0;
}
// When the valuation date is the end of the 3rd quarter, the value at time 1 is equal to 3
quarters' worth of sales - hence we divide by 3
if (valn_month == 9){
if (t == 1)
return reins_comm(t) + reins_comm(t) * 1.0/3.0;
return reins_comm(t) + reins_comm(t - 1) * 1.0/3.0;
}
// When the valuation date is the end of the 4th quarter, the reinsurance contract is due for
renewal and so there is no need to assume future sales
return reins_comm(t);
/*
SK 04/02/22 - CR376 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Net cost to Migdal of reinsurance in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return reins_prem(t) - reins_claims(t)
- reins_comm(t)
- reins_prof_comm(t)
- phi_reins_res_inc(t) // relevant to PHI only, 0 for other
products
- reins_delta_ibnr_prem(t)
+ reins_interest_prem(t);
/*
DC 22/12/14 - Tidied formula
OS 23/01/19 - CR14 - added phi reinsurance reserve increase term
SK 06/10/22 - CR403 - Added IBNR columns
*/

/* Reinsurance IBNR from prem - Delta */
if (t < commence_period_w+1 || t > maturity_period_last_w+1)
return NO_AVG;
return reins_ibnr_prem_b(t) - reins_ibnr_prem_b(t-1);
/*
SK 06/10/22 - CR403 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Reinsurance IBNR from prem for IFRS - Delta */
if (t < commence_period_w+1 || t > maturity_period_last_w+1)
return NO_AVG;
return reins_ibnr_prem_b_ifrs(t) - reins_ibnr_prem_b_ifrs(t-1);
/*
SK 06/10/22 - CR403 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Reinsurance IBNR from prem - bop */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
//The IBNR is claculated on an annual basis
return reins_prem(t) * pv_period_im * reins_ibnr_prem_factor;
/*
SK 06/10/22 - CR403 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Reinsurance IBNR from prem - Bop - including future business for IFRS */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (run_type != "IFRS" || !nb_ind || treaty_period / pv_period_im == 1)
return reins_ibnr_prem_b(t);
/*
When the valuation date is the end of the first quarter, we assume that sales in the 2nd quarter
will be the same as in the first, and so we multiply by 2.
(Hard-coding to avoid incorrect calculation due to zero claims at t=0.)
Once a full valuation year has been completed (and t=0 is no longer referenced), the calculation
progresses recursively.
*/
if (valn_month == 3){
if (t == 1)
return reins_ibnr_prem_b(t) * 2.0;
if (t == 2)
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t - 1) * 2.0;
if (t == 3)
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t - 1) + reins_ibnr_prem_b(t - 2) *
2.0;
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t - 1) + reins_ibnr_prem_b(t - 2) +
reins_ibnr_prem_b(t - 3);
}
// When the valuation date is the end of the 2nd quarter, the value at time 1 is equal to 2
quarters' worth of sales - hence we divide by 2
if (valn_month == 6){
if (t == 1)
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t) * 1.0/2.0;
if (t == 2)
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t - 1) * 1.0/2.0 +
reins_ibnr_prem_b(t - 1) * 1.0/2.0;
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t - 1) * 1.0/2.0 + reins_ibnr_prem_b(t - 2) *
1.0/2.0;
}
// When the valuation date is the end of the 3rd quarter, the value at time 1 is equal to 3
quarters' worth of sales - hence we divide by 3
if (valn_month == 9){
if (t == 1)
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t) * 1.0/3.0;
return reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t - 1) * 1.0/3.0;
}
// When the valuation date is the end of the 4th quarter, the reinsurance contract is due for
renewal and so there is no need to assume future sales
return reins_ibnr_prem_b(t);
/*
SK 06/10/22 - CR403 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Reinsurance interest on IBNR in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (reins_ibnr_prem_b(t) + reins_ibnr_prem_b(t-1)) / 2.0
* (pow(1.0 + reins_interest_on_ibnr, 1.0 / pv_period_im) - 1.0);
/*
SK 06/10/22 - CR403 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Reinsurance interest on IBNR for IFRS in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (reins_ibnr_prem_b_ifrs(t) + reins_ibnr_prem_b_ifrs(t-1)) / 2.0
* (pow(1.0 + reins_interest_on_ibnr, 1.0 / pv_period_im) - 1.0);
/*
SK 06/10/22 - CR403 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

/* Reinsurance premium payable in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code_sub == ADISOLD)
return reins_sum_risk(t)
* mort_tbl_ageexact_reins * tariff_multiplier * 1.42857
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (prod_code_sub == ADISNEW)
return reins_sum_risk(t)
* mort_tbl_ageexact_reins * tariff_multiplier
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (prod_code == RISK || prod_code == ADIF ||
prod_code == MIGM || prod_code == MIGP  || prod_code == MIGLIFE) {
double sexsmokefactor = 1.0;
if (sex1 == M && smoking_status == "N")
sexsmokefactor = 0.825;
else if (sex1 == M && smoking_status == "Y")
sexsmokefactor = 1.65;
else if (sex1 == F && smoking_status == "N")
sexsmokefactor = 0.515625;
else // sex1 == F && smoking_status == "Y"
sexsmokefactor = 1.03125;
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins * tariff_multiplier * 0.82 * sexsmokefactor + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
}
if (prod_code == ADIFOLD) {
if (sex1 == M && smoking_status == "N")
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins * 0.6765 + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (sex1 == M && smoking_status == "Y")
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins  * 1.353 + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (sex1 == F && smoking_status == "N")
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins * 0.4228 + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (sex1 == F && smoking_status == "Y")
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins * 0.8456 + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
}
if (prod_code == END   || prod_code == RMASH)
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins * tariff_multiplier * 0.82 + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (prod_code == PHI) {
double murchav_factor = 1.0;
if (phi_murchav_ind) //the rate is 10% or 15% more if it's a policy with a harchava
murchav_factor = phi_reins_murchav_fac;
if (phi_reins_treaty == "ShalvaFlat")
return (tot_prem_paid(t) + prem_disc_value(t)) * phi_reins_prem_mult *
murchav_factor;
// גיא .מהקלט הביטוח סכום נלקח כאשר שנגרעו ורפואית מקצועית תוספת הוספת
if (sa_on_data_ind)
return sum_assd_if_b(t) * phi_reins_prem_rate * murchav_factor * phi_modular_mult
/ prem_rate_factor / pv_period_im * phi_reins_prem_mult
* (1 + avg_mort_load/100.0) * (1 + avg_occ_load/100.0);
//SA is calculated
return sum_assd_if_b(t) * phi_reins_prem_rate * murchav_factor * phi_modular_mult
/ prem_rate_factor / pv_period_im * phi_reins_prem_mult;
}
if (prod_code == DD){
if (sa_on_data_ind)
return reins_sum_risk(t) * poli_if_b(t) * dd_reins_prem_rate / prem_rate_factor /
pv_period_im
* (1 + avg_mort_load/100.0) * (1 + avg_occ_load/100.0);
//SA is calculated
return reins_sum_risk(t) * poli_if_b(t) * dd_reins_prem_rate / prem_rate_factor /
pv_period_im;
}
if (prod_code == ADIF92  ||
prod_code == ENDM92  || prod_code == ENDP92)
return reins_sum_risk(t)
* (mort_tbl_ageexact_reins * tariff_multiplier + 0.2)
/ prem_rate_factor / pv_period_im * poli_if_b(t);
if (prod_code == LTC) {
double LTC_SA = sum_assured_init_model * poli_if_b(t); // SA for active part
if (ltc_reins_pup_ind) //SA for pupped part, only where the reinsurance treaty covers paid-
up policies
LTC_SA = LTC_SA + pups_avg_value(t) * pups_if_b(t);
return LTC_SA
* ltc_reins_prem_rate / 1000.0 / pv_period_im * ltc_reins_prem_mult;
}
if ((prod_code == HO) && (((prod_year < ho_prod_year) && (ho_reins_treaty == "Prat")) ||
(ho_reins_treaty == "Maccabi_Single")))
return ho_reins_prem * ho_reins_pct * ho_prem_load * poli_if_b(t) * tariffs_count * (cpi /
ho_int_index)* (1 + avg_mort_load/100.0) * (1 + avg_occ_load/100.0) / pv_period_im;
if ((prod_code == HO) && (prod_year < ho_prod_year) && (ho_reins_treaty == "Prat_OT"))
return prem_recd(t) * ho_reins_pct;
return 0.0;
/* DC 22/12/14 - Tidied formula.
ES 29/03/15 - changed lookup to morbidity_tbl to be prod_fund_name from prod_code_sub.
DC 01/11/15 - Removed the clause for the deprecated DI product
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 31/07/16 - change sex1 to be enumerated value
OS 28/09/16 - replaced column tarr_mult to get the value directly from  the table
tariff_multiplier
OS 04/12/16 - added reinsurance caclculation for LTC (CR89)
OS 06/11/17 - CR159 - Replaced the condition to match the new risk products hierarchy
Plus added  tariff_multiplier values hard coded for RISK and ADISOLD
CR183 - Added ADIF and MIG to the RISK condition
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
DC 24/06/18 - CR234 - reinsurance percentage now comes from scalar rather than directly from
table
OS 22/01/19 - CR14 - new code for PHI and DD reinsurance
MG 21/01/20 - CR296 - changed LTC clause to include PUP policies in the reinsurance calculations
SK 25/05/20 - CR299 - Reinsurance premium adjustment for modular PHI Harchavot
TA 27/12/2020- CR276- Added rein premium calculations for HO products.
NB 09/02/22 - CR341 - Changed prod_codes for Adif
GA 18/01/22 - CR354 - Adding Tosafot from the input to the claims prob (since we now take the
real SA from the input, and not the inflated one)
*/

/* Reinsurance premium payable in the period - including future business for IFRS */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (run_type != "IFRS" || !nb_ind || treaty_period / pv_period_im == 1)
return reins_prem(t);
/*
When the valuation date is the end of the first quarter, we assume that sales in the 2nd quarter
will be the same as in the first, and so we multiply by 2.
(Hard-coding to avoid incorrect calculation due to zero claims at t=0.)
Once a full valuation year has been completed (and t=0 is no longer referenced), the calculation
progresses recursively.
*/
if (valn_month == 3){
if (t == 1)
return reins_prem(t) * 2.0;
if (t == 2)
return reins_prem(t) + reins_prem(t - 1) * 2.0;
if (t == 3)
return reins_prem(t) + reins_prem(t - 1) + reins_prem(t - 2) * 2.0;
return reins_prem(t) + reins_prem(t - 1) + reins_prem(t - 2) + reins_prem(t - 3);
}
// When the valuation date is the end of the 2nd quarter, the value at time 1 is equal to 2
quarters' worth of sales - hence we divide by 2
if (valn_month == 6){
if (t == 1)
return reins_prem(t) + reins_prem(t) * 1.0/2.0;
if (t == 2)
return reins_prem(t) + reins_prem(t - 1) * 1.0/2.0 + reins_prem(t - 1) * 1.0/2.0;
return reins_prem(t) + reins_prem(t - 1) * 1.0/2.0 + reins_prem(t - 2) * 1.0/2.0;
}
// When the valuation date is the end of the 3rd quarter, the value at time 1 is equal to 3
quarters' worth of sales - hence we divide by 3
if (valn_month == 9){
if (t == 1)
return reins_prem(t) + reins_prem(t) * 1.0/3.0;
return reins_prem(t) + reins_prem(t - 1) * 1.0/3.0;
}
// When the valuation date is the end of the 4th quarter, the reinsurance contract is due for
renewal and so there is no need to assume future sales
return reins_prem(t);
/*
SK 04/02/22 - CR376 - Created column
SK 09/07/23 - CR433 - Tidied code and comments
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
double prof = 0.0;
if (prod_code == DD)
prof = dd_reins_prof_prem_fac * (reins_prem(t) - reins_comm(t))- reins_claims(t);
else if (prod_code == PHI)
prof = phi_reins_prof_prem_fac * (reins_prem(t) -reins_comm(t)) - reins_claims(t) -
phi_reins_res_inc(t);
/*OS - checked with Liran lev that the expenses are from premium only*/
else if ((prod_code == HO) && (ho_reins_treaty!= "na"))
prof= (reins_prem(t) * ho_prof_comm_exp - reins_comm(t) - reins_claims(t))*
ho_prof_comm_fac;
//Not PHI or DD or HO
else prof = (reins_prem(t) - reins_comm(t)) * 0.96 - reins_claims(t);
if (t == commence_period_w+1)
return prof;
if (reins_pro(t-1) >= 0)
return prof;
// otherwise (reins_pro(t-1) < 0)
return prof + reins_pro(t-1);
/* DC 22/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 23/01/19 - CR14 - new code for PHI and DD.  Note that this code is not picked up.
TA 27/12/20- CR276- Added calculations for HO products.
*/

/*Profit commision received from reinsurer*/
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == LTC)
return (0.9 * reins_prem(t) - reins_claims(t)) * 0.5;
if (prod_code == DD)
return (dd_reins_prof_prem_fac * (reins_prem(t) - reins_comm(t)) - reins_claims(t))  *
dd_reins_prof_comm_fac;
if (prod_code == PHI)
return (phi_reins_prof_prem_fac * (reins_prem(t) - reins_comm(t)) - reins_claims(t) -
phi_reins_res_inc(t) - reins_delta_ibnr_prem(t) + reins_interest_prem(t)) *
phi_reins_prof_comm_fac;
if (prod_code == HO) {
if (ho_reins_treaty== "Maccabi_Single")
return 0.0;
if ((ho_reins_treaty!= "na") && (prod_year < ho_prod_year))
return (reins_prem(t) * ho_prof_comm_exp - reins_comm(t) - reins_claims(t))*
ho_prof_comm_fac * ho_comm_ind;
}
// Other products
if (reins_pro(t) > 0.0)
return reins_pro(t) * 0.7;
return 0.0;
/* DC 22/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 04/12/16 - added condition for LTC - CR89 calculating reinsurance for LTC products
OS 23/01/19 - CR14 - added new code for DD and PHI
TA 27/12/20 - CR276 - Added reins prof comm calculations for HO products. It was found that
Macabi treaty will not yield any future profit commissions.
SK 06/10/22 - CR403 - Added IBNR columns to PHI products
*/

/* Sum at risk covered by reinsurance */
if (t < commence_period_w+1 || t > maturity_period_last_w || (klassi_prod_ind && t >
maturity_period_w))
return NO_AVG;
if (savings_prod_ind == 1 || prod_code == END ||
prod_code == ENDM92   || prod_code == ENDP92 )
return max(0.0, sum_assured_basic_b(t) - reserve_b(t-1) - sav_b_res(t-1))
* reins_risk_pct;
// Other products
return sum_assured_basic_b(t) * reins_risk_pct;
/* DC 23/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 04/12/16 - replace the condition term with the scalar savings_prod_ind
DC 22/08/17 - CR167 - Added the Savings B reserve (sav_res) into the calculation of the savings
sum at risk
- Renamed from sum_risk to reins_sum_risk
DC 24/06/18 - CR234 - reinsurance percentage now comes from scalar rather than directly from
table
NB 31/12/23 - CR349 - Zeroed out for Klassi policies after maturity
*/

/* Cash1 proportion on the policy at the end of period */
if (!gimla_prod_ind)
return NO_AVG;
if (t < 0 || t > maturity_period_last_w)
return NO_AVG;
if (t == 0)
return curr_perc_frozen;
if (t == maturity_period_last_w)
return annuity_perc_frozen(t-1);
if (abs(pup_res_bal_e(t) + res_bal_e(t) + as_res_e(t)) <= 0.1)
return 0.0;
return min((annuity_perc_frozen_pup(t) * pup_res_bal_e(t)
+ annuity_perc_frozen_act(t) * (res_bal_e(t)+as_res_e(t)))
/ (pup_res_bal_e(t) + res_bal_e(t) + as_res_e(t))
, 1.0);
/* DC 02/12/14 - Tidied formula
DC 01/01/15 - Changed the condition on small reserves to be absolute values.
Put a maximum of 100% on the percentage returned.
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 17/08/16 - CR70 - Type comparison correction - changed comparison to SMALL DOUBLE
OS 11/12/16 - replaced all maturity_period_w with maturity_period_last_w.
GR 21/01/19 - CR261 - Changed gimla prod classification
*/

/* Cash1 proportion on the active portion at the end of period, projected from a known value at the
valuation date. */
if (!gimla_prod_ind)
return NO_AVG;
if (t < 0)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
if (t == 0)
return curr_perc_frozen;
if (t == maturity_period_last_w)
return annuity_perc_frozen_act(t-1);
if (fabs(res_bal_e(t) + as_res_e(t)) <= 0.1) // not at maturity period
return 0.0;
double rate1act = pow(pow(1.0 + inv_ret_bonus_act_pre(t), pv_period_im), 1.0 / 12.0);
double rate2act = pow(rate1act, 12.0 / pv_period_im);
double rate1as  = pow(pow(1.0 + inv_ret_bonus_as(t), pv_period_im), 1.0 / 12.0);
double rate2as  = pow(rate1as, 12.0 / pv_period_im);
/* The code below calculates the rolled-forward cash1 proportion.  If prat, we allocate new
premiums
to cash0 (or cash2), otherwise they go to cash1.  The formula for the prat case should look
something
like this:
frozen%(1e) = [cash1(0e) * (1+i) * surv] / [cash0(1e) + cash1(1e)]
and for the menahalim/atzmaim case should be:
frozen%(1e) = [cash1(0e) * (1+i) * surv  + new_prem(1)] / [cash0(1e) + cash1(1e)]
However, for circular references reasons, the formulae can't be written like this, and so we use
the
formulation below.  It can be proved (see CR225) that the formula below are equivalent to the
intuitive
version given above.
*/
double mult_fac;
if (managers == "P")
mult_fac = -annuity_perc_frozen_act(t-1);
else mult_fac = (1.0 - annuity_perc_frozen_act(t-1));
// For Klassi products
if (klassi_ind)
return min (1.0,
annuity_perc_frozen_act(t-1)
+ ifrs_prem_sav(t)
* (rate2act - 1.0) / (rate1act - 1.0) * rate1act
* poli_if_b(t+1)
* mult_fac
/ res_bal_e(t) );
// Other then klassi (Adif, Mig etc...)
return min(annuity_perc_frozen_act(t-1)
+ ((fxd_sa_add_sav(t) + fxd_sav_add_sav(t))
* (rate2as - 1.0) / (rate1as - 1.0) * rate1as
+ (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) + mig_prem_sav(t)) *
standard_savings
* (rate2act - 1.0) / (rate1act - 1.0) * rate1act)
* poli_if_b(t+1)
* mult_fac
/ (res_bal_e(t) + as_res_e(t))
, 1.0);
/* DC 02/12/14 - Tidied formula
DC 01/01/15 - Set to always return the previous period's value at the maturity period.
Changed the small reserve check to be an absolute value, and if met
then to
return the previous period's value.
Set a maximum of 100% on the percentage returned.
DC 01/11/15 - Changed prod_code lookups to enumerated variables
DC 03/01/16 - Set a differential return for the additional savings premium
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 28/09/16 - replaced column sav_standard to get the value directly from  the variable
standard_savings
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
DC 21/01/19 - CR225 part A - added a separate condition for prat policies
GR 21/01/19 - CR261 - Changed gimla prod classification
NB 06/11/23 - CR349 - Added code for Klassi calculation
*/

/* Cash1 proportion on the paid-up portion at the end of period, projected from a known value at
the valuation date. */
if (!gimla_prod_ind)
return NO_AVG;
if (t < 0)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
if (t == 0)
return curr_perc_frozen;
if (t == maturity_period_last_w)
return annuity_perc_frozen_pup(t-1);
if (fabs(pup_res_bal_e(t)) <= 0.1)
return annuity_perc_frozen_pup(t-1);
return min(((pup_res_bal_e(t) - (sv_of_pups(t) + as_pup(t)) * (1.0 - gimla_ret_prob_b(t+1)) * (1.0
+ inv_ret_bonus_pup_pre(t)/2.0))
* annuity_perc_frozen_pup(t-1)
+ (sv_of_pups(t) + as_pup(t)) * (1.0 - gimla_ret_prob_b(t+1)) * (1.0 +
inv_ret_bonus_pup_pre(t)/2.0)
* annuity_perc_frozen_act(t))
/ pup_res_bal_e(t)
, 1.0);
/* DC 02/12/14 - Tidied formula
DC 01/01/14 - Changed the condition for small PUP reserves to check the absolute value, and if
met
to return the previous period's value.
Set a maximum of 100% in the percentage returned.
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
DC 18/01/17 - CR106 part P - multiplied the new pups bracket by 1-retirement probability
GR 21/01/19 - CR261 - Changed gimla prod classification
*/

/* Returns the percentage annuitising */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!gimla_prod_ind || prod_code == ANPY)
return NO_AVG;
if (gimla_retagedistr_use == 0) // not using retirement age distribution
return annuity_perc_frozen(t-1) * gimla_tur1(maturity_period_last_w+1)
+ (1.0 - annuity_perc_frozen(t-1)) * cash0_percofnonfrozen *
gimla_tur0(maturity_period_last_w+1);
return annuity_perc_frozen(t-1) * gimla_tur1(t+1)
+ (1.0 - annuity_perc_frozen(t-1)) * cash0_percofnonfrozen * gimla_tur0(t+1);
/* DC 25/11/14 - Renamed from annuity_percent.  Converted to scalar as it is in practice only used
at
maturity period.  Simplified code and changed lookup to new gimla_params table.
DC 03/12/14 - Correction of the TUR0_adj condition to be an or condition between the four sub-
products.
DC 25/12/14 - Changed the TUR0 and TUR1 lookups to use the existing scalars rather than going to
tables.
DC 01/01/15 - Removed the adjustment to TUR0 - this is now done in the scalar gimla_tur0 itself
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 19/09/16 - after changing gimla_tur0 and gimla_tur1 from scalar to column, added
(maturity_period_w+1)
MO 02/11/16 - changed from a scalar to a column
OS 04/12/16 - split the column with or without distribution, to take gimla tur correct value
from the table
OS 11/12/16 - changed annuity_perc_frozen(t) to annuity_perc_frozen(t-1) in order to avoid
circular error.
OS 09/03/17 - CR132 - multiply the cash0 calculation by cash0_percofnonfrozen.
GR 21/01/19 - CR261 Changed gimla prod classification
SK 05/08/21 - CR356 - Adding time guard for gen2 engine
*/

/* Returns additional savings accumulation coverting to gimla (before the effect of the cash0
antiselection factor) */
if (t < maturity_period_first_w || t > maturity_period_last_w || !gimla_prod_ind  || prod_code ==
ANPY)
return NO_AVG;
return sav_b_res(t) * pol_matd(t) * annuity_perc_mat(t);
/* DC 27/11/14 - Created formula as an extract from activ_perc
DC 1/11/15  - Changed prod_code lookups to enumerated variables
MO 21/10/16 - Converted to a column from a scalar
DC 17/1/17  - Restricted calculation to be between the first and last maturity periods only
OS 13/3/17  - CR133 - Changed annuity_perc_mat to annuity_perc_mat_withantisel in the return
value
DC 15/8/17  - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
DC 07/02/19 - CR262 - now returns amount before the effect of the cash0 antiselection factor
*/

/* Returns the pre-retirement best estimate cashflow, without reinsurance */
/* Assuming maturities are taken as a lump sum for miglife post 2013 products*/
if (t < commence_period_w+1 || t > maturity_period_last_w )
return NO_AVG;
return - tot_prem_paid(t)
//claims pre maturity
+ claims_paid(t) + suppliers_claims_expense(t) + pup_clm_paid(t) +
suppliers_pup_claims_expense(t)
- gtee_cost_equ(t)
+ tot_surrs(t) + tot_mats_lumpsum(t)
//expenses and commissions pre maturity
+ expenses_perc_prem (t) + expenses_per_pol (t) + as_exp(t) + pup_expenses_per_pol(t)
+ expenses_res(t) + expenses_claims(t)
+ pup_expenses_claims(t)
+ tot_comm_paid(t) - lookthrough_adj(t);
/*
OS 20/07/2021 CR353 - Created column for Miglife post 2013 contract boundaries.
MG 06/18/24 - CR336 - added suppliers claims expense
*/

/* Returns the pre-retirement best estimate cashflow including reinsurance */
/* Assuming maturities are taken as a lump sum for miglife post 2013 products*/
if (t < commence_period_w+1 || t > maturity_period_last_w )
return NO_AVG;
return be_cf_pre_bruto_lumpsum(t)
+ reins_cost(t) * reins_includ;
/*
OS 20/07/2021 CR353 - Created column for Miglife post 2013 contract boundaries.
*/

/* Returns the discounted value of the future pre-retirement BE cashflows, without reinsurance */
/* Assuming maturities are taken as a lump sum for miglife post 2013 products*/
if (t < commence_period_w+1 || t > maturity_period_last_w+1 )
return NO_AVG;
return (be_cf_pre_bruto_lumpsum(t) + be_pre_bruto_lumpsum(t+1))
*v_factor_pre(t);
/*
OS 20/07/2021 CR353 - Created column for Miglife post 2013 contract boundaries.
*/

/* Returns the discounted value of the future pre-retirement BE cashflows including reinsurance */
/* Assuming maturities are taken as a lump sum for miglife post 2013 products*/
if (t < commence_period_w+1 || t > maturity_period_last_w+1 )
return NO_AVG;
return (be_cf_pre_neto_lumpsum(t) + be_pre_neto_lumpsum(t+1))
*v_factor_pre(t);
/*
OS 20/07/2021 CR353 - Created column for Miglife post 2013 contract boundaries.
*/

/* Returns the discounted value (by maazan rate) of the future pre-retirement BE cashflows
including reinsurance */
/* Assuming maturities are taken as a lump sum for miglife post 2013 products*/
if (t < commence_period_w+1 || t > maturity_period_last_w+1 )
return NO_AVG;
return (be_cf_pre_neto_lumpsum(t) + be_pre_neto_lumpsum_maazan(t+1))
*v_factor_maazan_solvency_pre(t);
/*
NB 20/03/2024 - CR420 - Added column
*/

/* Sum of reserves designated as Cash0 (end-period) */
if (!gimla_prod_ind)
return NO_AVG;
if (t < 0)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
return (1.0 - annuity_perc_frozen(t))
* cash0_percofnonfrozen
* (res_bal_b(t+1) + as_res_b(t+1) + pup_res_bal_b(t+1));
// We have to use the b(t+1) reserves rather than the e(t) reserves so that at t=0end the PUP
// reserve includes the makeup to the data reserve.
/* DC 30/11/14 - Introduced formula
DC 15/12/14 - Correction to refer to the reserves at t-1 rather than t
DC 16/12/14 - Change to refer to total reserve less annuity reserves
DC 17/12/14 - Renmaed with a _e suffix.  Changed reserve lookup to start period reserves at t+1
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 09/03/17 - Multiply the value cash0 amount calculation by cash0_percofnonfrozen
GR 21/01/19 - CR261 - Changed gimla prod classification
*/

/* Sum of reserves designated as Cash1 (end-period) */
if (!gimla_prod_ind)
return NO_AVG;
if (t < 0)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
return annuity_perc_frozen(t)
* (res_bal_b(t+1) + as_res_b(t+1) + pup_res_bal_b(t+1));
// We have to use the b(t+1) reserves rather than the e(t) reserves so that at t=0end the PUP
// reserve includes the makeup to the data reserve.
/* DC 30/11/14 - Introduced formula
DC 15/12/14 - Correction to refer to the reserves at t-1 rather than t
DC 16/12/14 - Change to refer to total reserve less annuity reserves
DC 17/12/14 - Renamed with a _e suffix.  Changed reserve lookup to start period reserves at t+1
DC 01/11/15 - Changed prod_code lookups to enumerated variables
GR 21/01/19 - CR261 - Changed gimla prod classification
*/

/* Total reserve being paid out or converted to gimla on retirement at the end of the period */
if (t < maturity_period_first_w || t > maturity_period_last_w)
return NO_AVG;
return maturities_togimla(t) + as_maturities_togimla(t) + pup_maturities_togimla(t)
+ maturities_paid(t) + as_maturities_paid(t) + pup_maturities_paid(t);
/*
DC 17/11/14 - Tidied formula
DC 25/11/14 - Now picks up the scalar annuity_perc_mat instead of the (deprecated) column
annuity_percent.
OS 22/12/16 - Changed the reporting column to return the reserve that is about to be
matured.
GR 26/12/18 - CR203 - Removed the multiplication by gimla_ret_prob_b(t+1), as this is
already coming through in previous terms
*/

/* Straight sum of reserves coming to maturity at all future maturity periods
Results are meaningful at t=1 only */
if (t < 1)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
if (t >= maturity_period_first_w)
return final_reserve_t1(t+1) + final_reserve(t);
return final_reserve_t1(t+1);
/*
DC 22/12/14 - Tidied formula
OS 04/12/16 - The references to annuity_perc_mat should be at time maturity_period_last_w
(and not at t)
OS 22/12/16 - CR106 part F. Changed the reporting column to sum up the reserves coming to
maturity at all future maturity periods
DC 16/08/17 - CR164 - Amended second return to return NO_AVG rather than zero beyond the
last maturity period
*/
/* Reporting column */

/* Straight sum of reserves converting to gimla at all future maturity periods
Results are meaningful at t=1 only */
if (t < 1)
return NO_AVG;
if (t > maturity_period_last_w)
return NO_AVG;
if (t >= maturity_period_first_w)
return final_reserve_togimla_t1(t+1) + maturities_togimla(t) + as_maturities_togimla(t) +
pup_maturities_togimla(t);
return final_reserve_togimla_t1(t+1);
/*
DC 22/12/14 - Tidied formula
OS 04/12/16 - The references to annuity_perc_mat should be at time maturity_period_last_w
(and not at t)
OS 22/12/16 - Changed the calculation to sum up the reserves converting to gimla at all
future maturity periods.
DC 30/1/17  - Corrected the recursive reference in the final line to be back to this
formula.
DC 16/08/17 - CR164 - Amended second return to return NO_AVG rather than zero beyond the
last maturity period
*/
/* Reporting column */

/* Returns the anti-selection factor to be used in the post-maturity Fefferman calculation
at the sub-model level, weighted by the cash0 proportion at maturity */
double perc_cash0_atret = 0.0;
if (prod_code == ANPY)
perc_cash0_atret = gimla_params_anpy_cash0_pct;
//gimla_params("ANPY_Cash0_pct", gimla_params_collookup)
else {
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (abs((cash0_amt_e(t-1) * gimla_tur0(t+1)
+ cash1_amt_e(t-1) * gimla_tur1(t+1))) <
SMALL_DOUBLE)
return 0.0;
// to avoid DIV/0 errors in the next line
perc_cash0_atret = cash0_amt_e(t-1) * gimla_tur0(t+1)
/ (cash0_amt_e(t-1) * gimla_tur0(t+1)
+ cash1_amt_e(t-1) * gimla_tur1(t+1));
}
return perc_cash0_atret * gimla_antiselfac_feffbasis + (1.0 - perc_cash0_atret);
/* DC 24/12/14 - Introduced formula
