DC 1/2/16   - Created column
OS 4/12/16  - fund interest chaged to  -
sm_maslul[SL_0][0]->gimla_interest_reserve
OS 09/01/17 - CR106 M - changed from sm_maslul[SL_0][0] to sm_maslul[0][0] because we dont
always have SL_0 maslul
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Changed the condition to use gimla_prod_ind rather than
gimla_postmat_ind
*/
/* Reporting column */

/* Present value of all future maturity payments */
if (t < commence_period_w+1 || t > maturity_period_last_w+1)
return NO_AVG;
//For savings products without promised Mekadem
if (bdry_by_mekademage_ind && prod_code != ANPY)
return (tot_mats_lumpsum(t) + tot_pv_mats(t+1))
* v_factor_pre(t);
return (tot_mats(t) + tot_pv_mats(t+1))
* v_factor_pre(t);
/*
OS 26/02/17 - Created column.
OS 31/03/22 - CR379 - For miglife 2012+, we take the maturities as lumpsum for the BE
calculation with contract boundaries
*/

/* Present value of future distributable profits from the gimla period, net of tax */
if (t < commence_period_w+1 || !gimla_prod_ind)
return NO_AVG;
if(bdry_by_mekademage_ind)
if (t >= maturity_period_first_w && t<= maturity_period_last_w){
double gimlaData = 0.0;
int i, j;
for (i = 0; i < sm_maslul.size(); i++)
for (j =xint(age_exact_b(t))-gimla_firstretage; j >=0 && j< gimla_lastretage-
gimla_firstretage; j--)
gimlaData = gimlaData + sm_maslul[i][j]->tot_pv_neto_gimla(t);
return gimlaData;
}
//no contract bounadries
if (t > maturity_period_first_w)
return sm_maslul->tot_pv_neto_gimla(t);
//Before maturity_period_first_w we discount back
return tot_pv_neto_gimla(t+1) * v_factor_pre(t);
/*
OS 03/04/17 - CR140 Created column to correct the calculation of tot_pv_neto tax treatment
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Changed the condition to use gimla_prod_ind rather than
gimla_postmat_ind
OS 20/01/22 - CR379 - Contract boundaries full implementation
*/

/* Returns the PV of future gross profit, pre retirement, net of tax */
if (prod_code == ANPY && t==1)
return tot_pro_dist_pre(t) * (1.0 - tax_tbl) * v_factor_pre(t);
if (t < commence_period_w+1 || t > maturity_period_last_w + 1)
return NO_AVG;
return (tot_pro_dist_pre(t) * (1.0 - tax_tbl) + tot_pv_neto_pre(t+1))
* v_factor_pre(t);
/*
OS 03/04/17 - CR140 Created column to correct the calculation of tot_pv_neto tax treatment
MG 11/02/20 - CR306 removed req_cap_cost from the calculation.
*/

/* Present value of all future surrender payments */
if (t < commence_period_w+1 || t > maturity_period_last_w+1)
return NO_AVG;
return (tot_surrs(t) + tot_pv_surrs(t+1))
* v_factor_pre(t);
/*
OS 26/02/17 - Created column.
*/

/* Reports the value of all surrenders in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w+1)
return NO_AVG;
return sv_paid(t) + pup_surr_paid(t) + as_sur(t)
+ res_pwdrwl_act(t) + res_pwdrwl_atpup(t)
+ res_as_pwdrwl_act(t) + res_as_pwdrwl_atpup(t);
/*
OS 26/02/17 - Created column.
*/

/* Claim rate (or claim cost) on active portion in period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// For risk and savings products, the claim event is death, and so we return the death decrement
if (death_is_clm_ind)
return pol_death(t);
// For all other products, there is a separate decrement for claims from that of death
if (t<1)
return 0.0;
double rate = 0.0;
// Most health products claim rates are based on annual claim costs
if (prod_code == PERS_ACC || prod_code == HO) {
rate = briut_vectors_clm_costs
* select_factor_clm
* mort_params_mult_base
* morbid_trend_fac
* 1.0/prem_rate_factor
/ pv_period_im;
return (poli_if_b(t)
- (pol_surr(t)+pol_pupd(t) + pol_prem_reduct(t) + pol_death(t))/2.0)
* rate;
}
// LTC incidence rates come from a different table to other products' claim rates
if (prod_code == LTC)
rate = ltc_vectors_inci_rates * ltc_inci_act_mult * ltc_morb_impr_fac;
// PHI incidence rates also come from a different table, and are adjusted for the
//  discrepancy between the theoretical and actual professional loadings
else if (prod_code == PHI){
double occ = avg_occ_load/100;
if (prod_fund_name == PHIFP_MH || prod_fund_name == PHIFP_SHLV || prod_fund_name == PHIVP_17
|| prod_fund_name == PHIVP_MH || prod_fund_name == PHIVP_SHLV)
occ = phi_occ_add / 100;
if (sa_on_data_ind) //SA arrives from the input and we need to apply the Tosafot
rate = phi_vectors_inci_rates * phi_mpa_factors * umbclmmult // מטריה עבור הכפלה
* (1.0 + prem_ldg_prof_theo_pc) / (1.0 + prem_ldg_prof_act_pc)
* (1.0 + avg_mort_load/100) * (1.0 + occ) * phi_incidence_loading;
else //SA is calculated, Tosafot are already included
rate = phi_vectors_inci_rates * phi_mpa_factors * umbclmmult * phi_incidence_loading;
// מטריה עבור הכפלה
}
else if (prod_code == DD){
if(sa_on_data_ind) //SA arrives from the input and we need to apply the Tosafot
rate = briut_vectors_clm_costs
* (1.0 + avg_mort_load/100) * (1.0 + avg_occ_load/100);
else//SA is calculated, Tosafot are already included
rate = briut_vectors_clm_costs;
}
else if (prod_code == ADIS)
rate = mort_tbl_ageexact_adis;
else {
log_strm << "Primary key " << primary_key << " - unrecognised product in pol_clm" << endl;
throw NonFatalError("");
}
// Apply scalars and sensitivies and convert to a period rate
rate = 1.0 - pow(1.0 - (rate * select_factor_clm
* mort_params_mult_base
* morbid_trend_fac)
* (1.0 / prem_rate_factor)
, 1.0 / pv_period_im);
// For PHI only, multiply by the claim duration, adding on the months where we back-pay premiums
where there is a Francisa
if (prod_code == PHI)
rate = rate * (phi_vectors_clm_durs + phi_franchiza_mths);
return (poli_if_b(t)
-(pol_surr(t) + pol_pupd(t)
+ pol_prem_reduct(t) + pol_death(t))/2.0)
* rate;
/*
DC 29/10/13 - changed source of LTC incidence rates to come from the new ltc_vectors_inci_rates
table rather than from mortality_tbl.  Tidied formula.
DC 12/06/14 - added scaling of PHI rates by loadings.
DC 03/08/14 - changes to PHI code: rather than reading a combined claim rate, it first reads the
incidence
rate, then applies the loadings adjustment, then applies the
senstivities, then multiplies
by claim duration.
DC 07/10/14 - moved the lookup of morbid_trend_fac from prod_code to prod_fund_name.
ES 29/12/14 - Replaced clause of "SURG OR HR" with clause of "HO or PERS_ACC"; changed their lookup
from mortality_tbl to briut_vectors_clm_costs.
Separated out lookup of DD rates to also be from briut_vectors_clm_costs.
Moved the lookup of mort_sel_per from prod_code to prod_code_sub
DC 01/11/15 - Now looks up select years from the new scalar mort_params_select_yrs
DC 01/11/15 - Changed prod_code lookups to enumerated variables
AH 04/11/15 - Removed ANPY conditions as annuity payments now are dealt with in the maslul sub-
model
OS 06/09/16 - added  phi_mpa_factors to phi_incidence rate according to PRAT ATZMAI MANAGER
OS 07/12/16 - for LTC products -  added multiply in ltc_inci_act_mult (CR80 part b)
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
DC 21/06/18 - CR232 - Added Francisa months to the claim duration for PHI
DC 31/12/18 - CR247 - For risk/savings products, now returns pol_clm
Removed other usages of death_clm_indicator and mortality
factors, including war risk
Select adjustment now comes as a factor rather than as a
number of years
OS 01/01/18 - CR250 - Added in LTC morbidity improvement factor
DC 14/02/19 - CR267 - changed the lookup for ADIS, and added error trapping for other products
SK 05/08/21 - CR356 - Deleting 'makeRunLogYellow()' and 'skipModelPoint()', instead we added 'throw
NonFatalError("")'
GA 18/01/22 - CR354 - Adding Tosafot from the input to the claims prob (since we now take the real
SA from the input, and not the inflated one)
NB 24/11/24 - CR483 - New multipliers added to PHI
*/

/* Returns number of death terminations from active policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (decrem == "N")
return 0.0;
if (t < 1)
return 0.0;
double rate = 0.0;
double risk_loadings = 1.0;
if (prod_code == RISK || prod_code == RMASH)
risk_loadings = (1.0 + avg_mort_load / 100.0) * (1.0 + avg_occ_load / 100.0);
double ltc_impr_fac = 1.0;
if (prod_code == LTC)
ltc_impr_fac = ltc_mort_impr_fac;
if (age_exact_b(t) < mort_oldage_startage)  // standard mortality
rate = 1.0 - pow(1.0 - 0.001 * (mort_tbl_ageexact_poldthname
* risk_loadings
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ mort_vol_fac
+ mort_warrisk_addn),
1.0 / pv_period_im);
else // gimla mortality
rate = (1.0 - pow(1.0 - (gimla_mortality_table
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ 0.001 * mort_vol_fac
+ 0.001 * mort_warrisk_addn),
1.0 / pv_period_im))
* gimla_mort_mult_sex1;
return (poli_if_b(t) - (pol_surr(t) + pol_pupd(t) + pol_prem_reduct(t)) / 2.0)
* rate;
/* JB 14/09/10 - added (poli_if_b(t)-(pol_surr(t)+pol_pupd(t)+pol_prem_reduct(t))/2.)* to ANPY
clause to fix bug that deaths were not multiplied by lx
JB 15/12/10 - changed the mortality rate for post ret age to the standard annuitant mortality,
with relevant stress multipliers for actives and war risk.
DC 12/11/14 - tidied formula
DC 25/11/14 - removed the option to use gimla mortality after a parameterised std_qx_age (apart
from ANPY)
DC 26/11/14 - changed ANPY lookup from gimla mortality table to be by birth year
ES 01/02/15 - added a condition so that if the age is equal to or greater than
mort_old_startage, it uses
gimla mortality instead of standard mortality.
DC 01/11/15 - Changed prod_code lookups to enumerated variables
AH 04/11/15 - Removed ANPY clause as ANPY now runs through the maslul sub-model post-retirement
code and
this field no longer applies.
OS 09/01/17 - Tidied formula.
DC 31/12/18 - CR247 - now reads a select factor rather than calculating it from a select period
- removed unused variable dth_decr_clm_mult
OS 01/01/19 - CR250 - LTC improvement factor now comes directly from a table
SK 09/07/23 - CR354 - Within the accurate age development for RISK policies - we added the
loadings to the mortality
GA 28/09/23 - CR354 - Within the accurate age development for RISK-Mashkanta policies - we added
the loadings to the mortality
*/

/* Policies maturing from active in the period */
if (t < maturity_period_first_w || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == ANPY && t == maturity_period_last_w)
return 1.0;
return (poli_if_b(t) - pol_death(t)
- pol_surr(t)
- pol_pupd(t)
- pol_prem_reduct(t)
- pol_clm(t) * decrem_after_clm)
* gimla_ret_prob_b(t+1);
/* DC 16/12/14 - Tidied formula
AH 4/11/15  - Added in clause for ANPY to always equal one at commencement. This
maintains consistency with treatment of ANPY in submodels as
"maturing" at
commencement of ANPY policy.
OS 09/01/17 - CR 106 part L - changed code to be more efficient.
*/

/* Amount of active survivorship becoming paid-up as a result of premium reduction */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (duration_b(t) < elapsed_years)
return 0.0;
if (poli_if_b(t) < SMALL_DOUBLE)
return 0.0;
if (prod_code == LTC) {  // this exclusion has been introduced to avoid a circular reference, and
can be removed when CR223 is developed fully
if (pup_value_b(t) < pup_low_sa)
return 0.0;
}
// Calculate lapse due to persistence commission cancelled for policy for prod_year before 2001
double old_fac = 1.0;
if (prod_year <= lapse_scaling_yr_oldprods)
old_fac = 1.0 + lapse_scaling_perc_oldprods;
// Calculate overall lapse rate for year
double rate = surr_tablerate_adj(t)
+ prem_reduction_rate
+ pup_tablerate_adj(t);
if (rate < SMALL_DOUBLE)
return 0.0;
double period_rate = (1.0 - pow((1.0 - min((rate + lapse_shock_factor) * old_fac
* lapse_scaling_factor * lapse_scaling_factor_premium,
0.99999999)),1.0/pv_period_im));
if (t == 1 && elapsed_years > 0)
return poli_if_b(t) * period_rate * prem_reduction_rate/rate * per1_lapse_fact;
return   poli_if_b(t) * period_rate * prem_reduction_rate/rate;
/* DC 24/01/13 - added in lapse_scaling_factor_premium as an additional multiplier
DC 06/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_code_sub and not
prod_code.  Deleted commented-out code
DC 30/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_fund_name and not
prod_code_sub
DC 01/02/16 - changed lookup of the paid-up rate to come from the intermediate column
pup_tablerate_adj.
AH 14/02/16 - changed lookup of the surrender rate to come from the intermediate column
surr_tablerate_adj.
OS 28/09/16 - replaced column lapse_scale_fac to get the value directly from  the variable
lapse_scaling_factor
OS 09/01/17 - Tidied formula.
DC 05/06/18 - CR228 - Added condition to return zero if all lapse types are zero.  Also some
formula tidying.
GR 31/01/19 - CR223 - Added condition for not saving products
NB 06/11/23 - CR349 - Corrected condition for circular error, zeroed out if initial poli_if_b is
0
*/

/* Amount of active survivorship becoming paid-up in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (noins_ind == 1 && (run_type == "SII" || run_type == "BE" || run_type == "IFRS") && managers ==
"P" && t==0)
return poli_if_b(t);
if (klassi_prod_ind && t >= maturity_period_w && gimla_ret_prob_b(t+1) < 1.0)
return poli_if_b(t);
if (pup_mult == 1 && t == 0)
return policies_curr;
if (duration_b(t) < elapsed_years)
return 0.0;
if (prod_code == LTC) { // this exclusion has been introduced to avoid a circular reference, and
can be removed when CR223 is developed fully
if (pup_value_b(t) < pup_low_sa)
return 0.0;
}
// Calculate lapse due to persistence commission cancelled for policy for prod_year before 2001
double old_fac = 1.0;
if (prod_year <= lapse_scaling_yr_oldprods)
old_fac = 1.0 + lapse_scaling_perc_oldprods;
// Calculate overall lapse rate for year
double rate = surr_tablerate_adj(t)
+ prem_reduction_rate
+ pup_tablerate_adj(t);
if (rate < SMALL_DOUBLE)
return 0.0;
double period_rate = (1.0 -pow((1.0 -min((rate + lapse_shock_factor) * old_fac
* lapse_scaling_factor_premium * lapse_scaling_factor,
0.99999999)), 1.0/pv_period_im));
if (t == 1 && elapsed_years > 0)
return poli_if_b(t) * period_rate * pup_tablerate_adj(t)/rate * per1_lapse_fact;
return     poli_if_b(t) * period_rate * pup_tablerate_adj(t)/rate;
/* DC 24/01/13 - added in lapse_scaling_factor_premium as an additional multiplier
DC 06/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_code_sub and not
prod_code.  Deleted commented-out code
DC 30/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_fund_name and not
prod_code_sub
DC 01/02/16 - changed lookup of the paid-up rate to come from the intermediate column
pup_tablerate_adj.
AH 14/02/16 - changed lookup of the surrender rate to come from the intermediate column
surr_tablerate_adj.
OS 28/09/16 - replaced column lapse_scale_fac to get the value directly from  the variable
lapse_scaling_factor
OS 09/01/17 - Tidied formula.
DC 05/06/18 - CR228 - Added condition to return zero if all lapse types are zero.  Also some
formula tidying.
GR 31/01/19 - CR223 - Added condition for not saving products
NB 13/12/21 - CR357 - Added full PUP for noins_ind for SII runs
MG 20/9/23  - CR444 - Changed the 3rd condition to be just pup_mult = 1 and t = 0 and the clause
to return 1.
NB 06/11/23 - CR349 - Klassi policies retiring after their maturity date become fully paid-up,
corrected condition for circular error
*/

/* Amount of active survivorship cancelling fully in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (duration_b(t) < elapsed_years)
return 0.0;
if (poli_if_b(t) < SMALL_DOUBLE)
return 0.0;
// Calculate lapse due to persistence commission cancelled for policy for prod_year before 2001
double old_fac = 1.0;
if (prod_year <= lapse_scaling_yr_oldprods)
old_fac = 1.0 + lapse_scaling_perc_oldprods;
// Calculate overall lapse rate for year
double rate = surr_tablerate_adj(t)
+ prem_reduction_rate
+ pup_tablerate_adj(t);
if (rate < SMALL_DOUBLE)
return 0.0;
double period_rate = (1.0 - pow((1.0 - min((rate + lapse_shock_factor) * old_fac
* lapse_scaling_factor * lapse_scaling_factor_premium,
0.99999999)), 1.0/pv_period_im));
if (prod_code == LTC) {  // this exclusion has been introduced to avoid a circular reference, and
can be removed when CR223 is developed fully
if (pup_value_b(t) < pup_low_sa) {
if (t == 1 && elapsed_years > 0)
return poli_if_b(t) * period_rate * per1_lapse_fact;
else
return poli_if_b(t) * period_rate;
}
}
if (t == 1 && elapsed_years > 0)
return poli_if_b(t) * period_rate * surr_tablerate_adj(t)/rate * per1_lapse_fact;
return   poli_if_b(t) * period_rate * surr_tablerate_adj(t)/rate;
/* DC 24/01/13 - added in lapse_scaling_factor_premium as an additional multiplier
DC 06/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_code_sub and not
prod_code.  Removed commented-out code
DC 30/04/14 - changed lapse_group and lapse_shock factor lookups to be by prod_fund_name and not
prod_code_sub
DC 01/02/16 - changed lookup of the paid-up rate to come from the intermediate column
pup_tablerate_adj.
AH 14/02/16 - changed lookup of the surrender rate to come from the intermediate column
surr_tablerate_adj.
OS 28/09/16 - replaced column lapse_scale_fac to get the value directly from  the variable
lapse_scaling_factor
OS 09/01/17 - Tidied formula
DC 05/06/18 - CR228 - Added condition to return zero if all lapse types are zero.  Also some
formula tidying.
GR 31/01/19 - CR223 - Added condition for not saving products
NB 06/11/23 - CR349 - Corrected condition for circular reference, zeroed out when initial
poli_if_b is 0 to avoid errors
*/

/* Active survivorship in the middle of the period, for use in premium-based calculations */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return poli_if_b(t)
- (pol_surr(t) + pol_pupd(t) + pol_prem_reduct(t)
+ pol_death(t) + pol_clm(t) * decrem_after_clm)
/ 2.0;
/* DC 22/12/14 - Tidied formula
*/

/* Active survivorship at the start of the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t == commence_period_w+1)
return policies_curr;
return max (0.0, poli_if_b(t-1)
- pol_surr(t-1) - pol_pupd(t-1) - pol_prem_reduct(t-1)
- pol_death(t-1) - pol_clm(t-1) * decrem_after_clm
- pol_matd(t-1));
/* Note: all product types decrement on death via pol_death.  This includes claim decrements in
products
where death is a claim (risk and savings).  For health-type products that cannot reclaim
(Adis,
DD and LTC), there is an additional decrement on claim via pol_clm.  There is no
double-counting
of death claims on risk/savings, because for these products decrem_after_clm = 0
*/
/*
DC 22/12/14 - Tidied formula
NB 31/12/23 - Set to a minimum of zero to disallow small negative when pup/mat is double-
counted
*/

/* Return percentage of pension arising from actives at maturity */
if (t < commence_period_w || t < maturity_period_first_w)
return NO_AVG;
if (gimla_prod_ind && prod_code != ANPY) {
if (t > maturity_period_last_w+1)
return activ_perc(t-1);
if (maturities_togimla(t) + as_maturities_togimla(t) + pup_maturities_togimla(t) > 0.0)
return  (maturities_togimla(t) + as_maturities_togimla(t))
/ (maturities_togimla(t) + as_maturities_togimla(t) +
pup_maturities_togimla(t));
return activ_perc(t-1);
}
return 1.0;
/* ES 10/11/14 - Tidied formula
DC 25/11/14 - Now picks up the scalar annuity_perc_mat instead of the (deprecated) column
annuity_percent.
Removed the dividing of each section by ann_conv_fac_gteed, as this
gets cancelled out in the
final taking of the ratio.
DC 27/11/14 - Moved most of the calculation to the three new accum_at_mat_ scalars.
DC 1/11/15  - Changed prod_code lookups to enumerated variables
MO 21/10/16 - Converted from a scalar to a column
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
OS 14/12/16 - remove the restriction that it is calculated only once a year
GR 21/01/19 - CR261 - Changed gimla prod classification
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind ==1) {
double rate1 = pow(pow(1.0 + inv_ret_gross_hetz_incl_pre(t), pv_period_im), 1.0 / 12.0);
double rate2 = pow(rate1, 12.0 / pv_period_im);
double rate3 = pow(1.0 - gtee_cost, 1.0 / 12.0);
double rate4 = pow(rate3, 12.0 / pv_period_im);
// take the difference between return after fixed mgt fee and after fixed and var
// and apply to components from reserve_b column
return ((sav_b_accm(t-1) * rate2 + (fxd_sa_add_sav(t) + fxd_sav_add_sav(t))
* (rate2 - 1.0)
/ (rate1 - 1.0)
* rate1)
* (1.0 - res_pwdrwl_atpup_rate(t) - res_pwdrwl_act_rate(t))
* (rate4 - 1.0)
+ (sav_a_accm(t-1) * rate2 + (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) +
mig_prem_sav(t))
*
standard_savings
* (rate2 -
1.0)
/ (rate1 -
1.0)
* rate1)
* (1.0 - res_pwdrwl_act_rate(t) - res_pwdrwl_atpup_rate(t))
* (rate4 - 1.0))
* poli_avg(t)  // to get it in terms of in_force
+ (pup_res_bal_b(t) + (sv_of_pups(t) + as_pup(t) - pup_clm_paid(t) - pup_surr_paid(t))
