+
(sav_a_accm(t-1) * rate2
+ (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) + mig_prem_sav(t)) * standard_savings
* (rate2 - 1.0) / (rate1 - 1.0) * rate1)
* (1.0 - res_pwdrwl_act_rate(t) - res_pwdrwl_atpup_rate(t))
-
(sav_a_accm(t-1) * rate4
+ (fxd_sav_b_prm(t) + fxd_sa_b_prm(t) + mig_prem_sav(t)) * standard_savings
* (rate4 - 1.0) / (rate3 - 1.0) * rate3)
* (1.0 - res_pwdrwl_act_rate(t) - res_pwdrwl_atpup_rate(t));
}
if (prod_code == END    || prod_code_sub == PHIFP ||
prod_code == ENDM92 || prod_code == ENDP92) {
