*/

/* Calculates the premium discount in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// We calculate the discount rate to apply by averaging over the discount rates applying at each
//  month in the period
double calc_rate = 0.0;
for (int i = pol_mth_b(t); i < (pol_mth_b(t) + (12.0/pv_period_im)); i++)
calc_rate = calc_rate + prem_disc_mthly_rates(i, 0);
calc_rate = calc_rate / (12.0/pv_period_im);
return min(calc_rate, 1.0);
/* DC 6/8/13 - The data fields for discount periods (disc_pd1 and disc_pd2) have been adjusted such
that
they are relative to the start of the policy rather than the balance sheet date.
Accordingly,
proj_yr(t) has been replaced with duration(t) in the last lines of the formula.
Also, tidied up formula without any other changes to functionality.
DC 22/8/13 - Corrected the first condition to apply where a discount was less than 95% and not
100%, as it was previously leading to an inconsistency for those policies with discounts in the
95-100% range.
ES 28/10/14 - Adjusted formula to fit new structure (of up to five discount rates and periods):
1. In the calculation of the adjustment, refers to the discount rate in the first *projection*
month
(previously used "disc_perc1+disc_perc2").
2. Calculates the average discount rate over the months in the period.
DC 10/12/14 - Added initial condition not to return a discount before commencement or after
maturity.
DC 1/11/15 - Changed prod_code lookups to enumerated variables
AH 17/1/16 - Removed adjustments from the formula as the discounts are now explicitly
identified in the data. Also removed the 95% limitation.
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind|| prod_code == PHI ||
prod_code == DD || prod_code == END ||prod_code == FTEND)
return prem_init_bruto / pv_period_im;
return 0.0;
/* DC 22/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
AH 17/01/16 - Now a function of prem_init_bruto instead of prem_init_neto
OS 28/09/16 - replace the condition term eith the scalar savings_prod_ind
OS 06/11/17 - CR159 - Removed RISK from condition
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
*/

/* Calculates the pure risk premium received in the period (basic and additional) for savings
policies*/
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t > 0 && premium_cancel == 1)
return 0.0;
if (prod_code == ADIF ||
prod_code == ADIF92  ||
prod_code == ADIFOLD)
return (prem_init_neto / (1.0 + prem_subannual_rt) * (1.0 + inc_acm_pct(t))
- policy_fee * policy_fee_id)
* (1.0 - sav_prm_pct(t))
/ (1.0 - prem_disc_perc(1))
* (1.0 - prem_disc_perc(t))
* (1.0 + prem_subannual_rt) / pv_period_im
* poli_avg(t);
if (prod_code == MIGLIFE   || prod_code == MIGM
|| prod_code == MIGP) {
if (abs(mig_prem_risk(t) + mig_prem_sav(t) + mig_prem_exp(t)) < SMALL_DOUBLE)
return 0.0;
return (prem_init_bruto / (1.0 + prem_subannual_rt) * (1.0 + inc_acm_pct(t)))
* mig_prem_risk(t) / (mig_prem_risk(t) + mig_prem_sav(t) +
mig_prem_exp(t))
* (1.0 - prem_disc_perc(t))
* (1.0 + prem_subannual_rt) / pv_period_im
* poli_avg(t);
}
return NO_AVG;
/*
DC 16/12/15 - Created column
OS 17/08/16 - CR70 - Type comparison correction - changed comparison to SMALL DOUBLE
and premium_cancel type to int
GA 15/10/17 - CR158 - calculation for MIGs based on prem_init_bruto instead of prem_init_neto to
avoid div/0
- policy_fee * policy_fee_id deleted as not relevant for MIGs
NB 09/02/22 - CR341 - Changed prod_codes for Adif
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == ADIF)
return 12.0 * 100.0 * prem_rate_factor * 0.2 / net_prem_rate_b(t);
if (prod_code == ADIF92 || prod_code == ADIFOLD)
return 12.0 * 100.0 * prem_rate_factor * 0.25 / net_prem_rate_b(t);
if (prod_code == MIGM || prod_code == MIGP || prod_code == MIGLIFE)
return 1200000 * risk_min_pct / net_prem_rate_b(t);
return 0.0;
/*
DC 1/11/15 - Changed prod_code lookups to enumerated variables.  Tidied formula.
OS 25/03/18 - CR191 - Replaced the code for all six ADIF products.
NB 09/02/22 - CR341 - Changed prod_codes for Adif
*/

// Returns the cumulative reduction, to apply on the sum assured and premiums
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t <= 1)
return 1.0;
return sa_reduction(t-1) * pow(1.0 - sa_reduct, 1.0 / pv_period_im);
/* SK 22/12/22 - CR418 - created column
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind == 1)
return (fxd_sa_add_sav(t) + fxd_sav_add_sav(t)) * 12.0;
// Other products
return 0.0;
/* DC 23/12/14 - Tidied formula
DC 1/11/15 - Changed prod_code lookups to enumerated variables
OS 04/12/16 replace the condition term with the scalar savings_prod_ind
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (abs(prem_basic_b(t)) < SMALL_DOUBLE)
return 0.0;
if (abs(prem_init_bruto - policy_fee * policy_fee_id) < SMALL_DOUBLE)
//policy_fee_id(prod_code_sub)
return NO_AVG;
return ((fxd_sa_b_prm(t) + fxd_sav_b_prm(t) + mig_prem_sav(t)) * standard_savings
+ fxd_sa_add_sav(t) + fxd_sav_add_sav(t))
/ ((prem_basic_b(t) / (12.0 / pv_period_im) + policy_fee * policy_fee_id / 12.0)
// policy_fee_id(prod_code_sub)
* (1.0 + inc_acm_pct(t)) - policy_fee * policy_fee_id / 12.0);
//policy_fee_id(prod_code_sub)
/* DC 24/12/14 - Tidied formula
AH 31/12/15 - Changed calculation for ADIF type policies to calculate percentage of gross
premium
OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 28/09/16 replaced column sav_standard to get the value directly from  the variable
standard_savings
*/

/* Returns the PV of future premiums */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (tot_prem_paid(t) + tot_pv_prem_paid(t+1))
* v_factor_pre(t);
/* Reporting column */

/* Maturity payments on the additional savings component */
if (t < maturity_period_first_w || t > maturity_period_last_w)
return NO_AVG;
if (gimla_prod_ind)
return sav_b_res(t) * pol_matd(t) * (1.0 - annuity_perc_mat(t));
return pol_matd(t) * sav_b_res(t);
/*
DC 17/11/14 - Tidied formula
DC 25/11/14 - Now picks up the scalar annuity_perc_mat instead of the (deprecated) column
annuity_percent.
DC 1/11/15  - Changed prod_code lookups to enumerated variables
DC 17/1/16  - Restricted calculation to be between first and last maturity periods only
DC 15/8/17  - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
*/

/* Returns the value of paid-ups on the additional savings portion in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (pol_pupd(t) + pol_prem_reduct(t))
* (sav_b_res(t-1) + sav_b_res(t)) / 2.0;
/* ES 18/11/2014 - Tidied formula.
*/

/* Returns the value of surrenders on the additional savings portion in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return pol_surr(t)
* (sav_b_res(t-1) + sav_b_res(t)) / 2.0;
/* ES 18/11/2014 - Tidied formula.
*/

/* Calculates the actual claim amount as sum assured + bonus, adjusted for claims inflation,
multiplied by the claims rate */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
double rate = pow(1.0 + claim_infl_rt,
duration_b(t) + 1.0 / pv_period_im - elapsed_years);
// For LTC, in the case of Malus, Migdal covers the first part of the sum assured reduction
if (prod_code == LTC) {
if ((bonus_b(t-1) + bonus_b(t)) / 2.0 < SMALL_DOUBLE)
return max((sum_assured_basic_b(t) + min((bonus_b(t-1) + bonus_b(t)) / 2.0 +
ltc_migdal_part * sum_assured_basic_b(t),0.0)),0.0)
* rate * pol_clm(t);
}
// Other products, and LTC not in malus
return max((sum_assured_basic_b(t) + (bonus_b(t-1) + bonus_b(t)) / 2.0),0.0)
* rate * pol_clm(t);
/*
DC 04/08/14 - added claims inflation adjustment.
ES 18/11/14 - Tidied formula.
OS 01/09/16 - CR62 part B - add the check that there won't be negative payment by max(sum-bonus,0)
SK 13/05/20 - CR315 - Adding a restriction on lowering the malus from the Sum-assured in LTC
*/

/* Cash payments at maturity from the active portion */
if (t < commence_period_w+1 || t < maturity_period_first_w || t > maturity_period_last_w)
return NO_AVG;
if (prod_code == ANPY && t == maturity_period_first_w)
return 0.0;
// Otherwise at maturity period(s)
double persistency_bonus = 1.0;
if ((prod_code == MIGM || prod_code == MIGP || prod_code == MIGLIFE) && prod_year == 2006)
persistency_bonus = 1.0 + mig_eff_bonus * duration_b(t)
* 1.0
* mig_duration_fact
//mig_duration_fact(duration(t))
*
annuity_perc_mat(t);
return (surrender_value_b(t) + bonus_b(t))
* persistency_bonus
* pol_matd(t) * maturity_pay
* (1.0 - annuity_perc_mat(t));
/* YT 12/2/06 - added the persistency bonus clause for Migdalor 2006
DC 17/11/14 - Extensive tidying of formula, including: (i) Added clause at start to return 0
outside
of maturity period; (ii) Removed the distinction between what to do
when cash1 >0 and
when cash1 <=0 - this was the same other than multiplying by (1 -
annuity%(t)) in the
former case - but annuity%(t) will be zero when cash1 <= 0.
DC 25/11/14 - Now picks up the scalar annuity_perc_mat instead of the (deprecated) column
annuity_percent.
DC 1/11/15 - Changed prod_code lookups to enumerated variables
AH 4/11/15 - Added in clause to zero out ANPY at maturity
OS 09/01/17 - CR106 part L - tidied formula.
*/

/* Returns the present value of the risk outflow. The column will be used to determine
the Conversion rates for the coverage units calculation in IFRS */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (risk_claims_paid(t) + outflow_risk_pv(t+1))
* v_factor_pre(t);
/*
SK 09/07/22 - CR394 - Created column
*/

/* Calculates the actual risk claims in the period, including the death claims on the pure risk
(basic and additional)
component of savings policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
//For klassi products the risk claims is the difference between the sum assured and the reserve
multiplied by the number of claims
if (prod_code == END || prod_code == ENDM92 || prod_code == ENDP92 || prod_code == FTEND)
return (sum_assured_basic_b(t) - reserve_b(t)) * pol_clm(t) * (1 + supplier_exp_rate);
//The bonus does not appear here because it is offset, i.e. both, sum_assured_basic_b and
// reserve_b don't include the bonus, so the calculation is correct.
//For pure savings return zero
if (prod_code == CLSAVINGS)
return 0.0;
//When none of the products is a savings product
if (!savings_prod_ind)
{
if (prod_code == LTC)
return claims_paid(t) + suppliers_claims_expense(t) + pup_clm_paid(t) +
suppliers_pup_claims_expense(t) + tot_surrs(t);
return claims_paid(t) + suppliers_claims_expense(t) + pup_clm_paid(t) +
suppliers_pup_claims_expense(t);
}
//Other cases are Adif and Migdalor policies
if (abs(cost_of_add_risk(t)) < SMALL_DOUBLE)
return 0.0;
double infl_rate = pow(1 + claim_infl_rt,
duration_b(t) + 1.0 / pv_period_im - elapsed_years);
return (sa_per_mth_prem(t) * (fxd_sa_b_prm(t) + fxd_sav_b_prm(t)) * 0.01  // sa_per_mth_prem takes
into account the standard risk proportion
+ (fxd_sa_add_risk(t) + fxd_sav_add_risk(t)) / cost_of_add_risk(t) * 1000.0
+ mig_sum_risk(t))
* infl_rate * pol_clm(t) * (1 + supplier_exp_rate);
/*
DC 16/12/15 - Created column
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 04/12/16 - replace the condition term with the scalar savings_prod_ind
SK 09/07/22 - CR394 - Adjusting the column to return the actual risk claims, including the
death claims on the pure risk component of savings policies
MG 06/18/24 - CR336 - added suppliers claims expense
*/

/* Returns the average value of paid-up surrenders in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
double avge_sv1 = (surrender_value_b(t) + bonus_b(t)
+ surrender_value_b(t-1) + bonus_b(t-1)) / 2.0;
double avge_sv2 = (reserve_b(t) + bonus_b(t)
+ reserve_b(t-1) + bonus_b(t-1)) / 2.0;
if (surr_charge_pups == 0)
return (pol_pupd(t) + pol_prem_reduct(t)) * avge_sv1;
return (pol_pupd(t) + pol_prem_reduct(t)) * avge_sv2;
/*
ES 18/11/2014 - Tidied formula.
OS 17/8/16  - CR70  Type comparison correction - changed surr_charge_pups type to int
*/

/* Returns the value of active surrenders in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
double avge_sv = (surrender_value_b(t) + bonus_b(t)
+ surrender_value_b(t-1) + bonus_b(t-1)) / 2.0;
return pol_surr(t) * avge_sv;
/* ES 18/11/2014 - Tidied formula.
*/

/* Returns the present value of all future claims */
if (t < commence_period_w+1 || t > model_end_period)
return NO_AVG;
if (!gimla_prod_ind)
return tot_pv_claims_pre(t);
return tot_pv_claims_pre(t) + tot_pv_gimla_post_maturity(t);
/*
ES 11/11/14 - Moved initial conditions check to indicator column nogimla_postmat_ind.
ES 18/11/14 - Tidied formula.
OS 25/12/16 - Changed column to sum the pre and post calculation.
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Replaced use of gimla_postmat_ind with gimla_prod_ind
SK 05/08/21 - CR356 - Adding time guard for gen2 engine
*/
/* Reporting column */

/* Returns the denominator for calculating the Risk adjustment factors for IFRS */
if (t < commence_period_w+1 || t > model_end_period)
return NO_AVG;
// Products with contract boundaries
if(bdry_by_mekademage_ind)
return tot_pv_surrs(t) + tot_pv_mats(t) + tot_pv_claims_pre(t);
// Products without contract boundaries
return tot_pv_surrs(t) + tot_pv_mats(t) + tot_pv_claims(t);
/*
SK & LL 24/11/24 - CR491 - Created column
*/
/* Reporting column */

/* Returns the present value of future pure risk claims (above reserve) on savings policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind != 1)
return NO_AVG;
return (risk_prem_recd(t) - risk_claims_paid(t) + tot_pv_risk(t+1))
* v_factor_pre(t);
/*
DC 16/12/15 - Created column
OS 04/12/16 replace the condition term with the scalar savings_prod_ind
*/
/* Reporting column */

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (basic_prem(t) * poli_avg(t) < 0.00001) //prevent run skips
return 1.0;
return basic_prem(commence_period_w+1) * poli_avg(commence_period_w+1)
/ (basic_prem(t) * poli_avg(t));
/* DC 22/12/14 - Tidied formula
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
double term = maturity_age - age_exact_issue; // actualy it's "benefit_term" but it seems there's a
// problem to use
a scalar and a variable in "min" function.
if (16.-t+commence_period_w > min(amort_term, term))
return 0.0;
if (16.-t+commence_period_w < 3)
return 0.0;
return min(0.75, (16.-t+commence_period_w-3.+1.) / 16.);
/*
OS 14/12/16 - instead of using gimla_last_retage_dist - we use maturity_age in the term
calculation
*/

/* Returns value of expenses on additional savings portion */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t == commence_period_w+1)
return as_prm(t) * (exp_init_perc_prm_tbl * pv_period_im
//(expenses_tbl(prod_fund_name, "INIT_PERC_PRM")
- exp_ren_perc_prm_tbl * (pv_period_im-1))
* expenses_mult * exp_infl_factor(t);
return as_prm(t) * exp_ren_perc_prm_tbl
* expenses_mult
* exp_infl_factor(t);
/*DC 28/1/13 - Added expense multiplier.
DC 30/4/13 - Removed expense multiplier as it is now only to apply to renewal per policy expenses.
ES 16/11/14 - Tidied formula.
ES 08/12/15 - Moved lookup from prod_code to prod_fund_name level.
DC 5/1/16 - Changed lookup from old table variables exp_init/ren_perc_prem to new expenses_tbl
OS 22/2/17 - Added multiply by expenses_mult for LAT MAD calculations
OS 26/02/17 - CR131 - Added multiply by expenses inflation factor for all expenses (other than
initial expenses)
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return as_prm(t) * ren_com_add_sav * vat_mult(t);
//ren_com_add_sav(prod_code_sub,
1)
/* DC 22/12/14 - Tidied formula
*/

/* Claim expenses on active policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return
// percentage-of-claim expenses
((claims_paid(t) + suppliers_claims_expense(t)) * exp_perc_clm_tbl
// per-claim expenses
+ pol_clm(t) * exp_per_clm_tbl * tariffs_count)
* expenses_mult
* exp_infl_factor(t);
/*
DC 05/01/16 - Created column
OS 22/02/17 - Added multiply by expenses_mult for LAT MAD calculations
OS 26/02/17 - CR131 - Added multiply by expenses inflation factor for all expenses (other
than initial expenses)
MG 06/18/24 - CR336 - added suppliers claims expense
*/

/* Expenses on conversion to gimla - percentage of amount converting */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (!gimla_prod_ind)
return NO_AVG;
return (maturities_togimla(t) + as_maturities_togimla(t) + pup_maturities_togimla(t))
* exp_perc_gimlaconv_tbl
* expenses_mult
* exp_infl_factor(t);
/*
GA 07/02/19 - CR265 - Created column
*/

/* Expenses on maturity - fixed amount and percentage of payment */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (tot_mats(t) * exp_perc_mats_tbl // percentage-of-Mats expenses
+ (pol_matd(t) + pups_matd(t)) * tariffs_count * exp_mats_per_pol_tbl ) //
sum of-Mats expenses
* expenses_mult
* exp_infl_factor(t);
/*
GA 17/01/19 - CR260 - Created column
*/

/* Per-policy expenses on active policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// initial expenses
if (t == commence_period_w+1)
return (poli_if_b(t) * exp_ren_per_act_pol_tbl * tariffs_count * expense_ren_pp_mult /
pv_period_im
+ poli_if_b(t) * ((exp_init_per_pol_tbl - exp_ren_per_act_pol_tbl) *
tariffs_count * expense_ren_pp_mult))
* expenses_mult;
// else renewal expenses
return poli_if_b(t) * exp_ren_per_act_pol_tbl * tariffs_count / pv_period_im
* expense_ren_pp_mult
* expenses_mult
* exp_infl_factor(t);
/* GA 22/6/17 - CR155 - introduced column as part of the splitting of the old expenses column
GA 28/01/19 - CR260 - uses table values directly rather than intermediate scalars
*/

/* Percentage of premium expenses on active policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// initial expenses
if (t == commence_period_w+1)
return ((basic_prem(t) + policy_fee * policy_fee_id)
* (1.0 + prem_subannual_rt) * poli_avg(t)  / pv_period_im
* exp_ren_perc_prm_tbl
+ (basic_prem(t) + policy_fee * policy_fee_id)
* (1.0 + prem_subannual_rt) * poli_avg(t)
* (exp_init_perc_prm_tbl - exp_ren_perc_prm_tbl))
* expenses_mult ;
// else renewal expenses
return ((basic_prem(t) + policy_fee * policy_fee_id)
* (1.0 + prem_subannual_rt) * poli_avg(t) / pv_period_im
* exp_ren_perc_prm_tbl
+ ltc_incr_prem_recd(t) * exp_ren_perc_prm_tbl)
* expenses_mult
* exp_infl_factor(t);
/* GA 22/6/17 - CR155 - introduced column as part of the splitting of the old expenses column
*/

if (t < commence_period_w+1 || abs(tot_res(t)) < SMALL_DOUBLE)
return NO_AVG;
return (pow(1.0 + exp_perc_res_tbl, 1.0 /pv_period_im) - 1.0)
//expenses_tbl(prod_fund_name, "PERC_RES")
* (tot_res(t) + tot_res(t+1)) / 2.0
* expenses_mult
* exp_infl_factor(t);
/*
RR ? - added (pow(1. + exp_perc_res(prod_code),1./pv_period_im)-1) in place of
exp_perc_res(prod_code)
DC 23/1/13 - added expenses_mult
DC 30/4/13 - removed expenses multiplier as now only relevant to per policy renewal expenses
DC 16/12/14 - tidied formula
DC 5/1/16 - Moved lookup from old table variable exp_perc_res to new expenses_tbl
OS 22/2/17 - Added multiply by expenses_mult for LAT MAD calculations
OS 26/02/17 - CR131 - Added multiply by expenses inflation factor for all expenses (other than
initial expenses)
SK 05/08/21 - CR356 - Changing the condition 'tot_res(t) == NO_AVG' to 'abs(tot_res(t)) <
SMALL_DOUBLE'
*/

/* Expenses as a percentage of surrenders */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return tot_surrs(t) * exp_perc_surr_tbl
* expenses_mult
* exp_infl_factor(t);
/*
GA 17/01/19 - CR260 - Created column
*/

/* Returns the actual investment return credited to the active portion of the policy, net of
any applicable management fees or spread - pre retirement */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t < 1)
return inv_ret_net_pre_act(t);
if (prod_fund < 8)
return pow((1.0 + inv_non_partic_crediting_rate), 1.0 /pv_period_im) -1.0;
// Funds 8 and higher
double period = ((double)t / pv_period_im);
if (period <= no_mgt_fees_var_period && period > 0.0)
return inv_ret_net_fxd_pre_act(t);
// For non-gimla products in the maturity period, we decide whether to take variable fees based on
the start-period balance (as an approximation)
if (t == maturity_period_last_w && !gimla_prod_ind) {
if (mgt_fee_bal_act_b(t) < SMALL_DOUBLE)
return inv_ret_net_fxd_pre_act(t);
return inv_ret_net_pre_act(t);
}
// Conditions for gimla products
