if (fabs(current_reserve) < SMALL_DOUBLE)
return pow(1.0 + rate_act, 1.0 / pv_period_im) - 1.0;
return pow(((current_reserve - current_reserve_as) * pow(1.0 + rate_act,
years_to_mat)
+ current_reserve_as * pow(1.0 +
rate_as, years_to_mat))
/ current_reserve
, 1.0 / (pv_period_im * years_to_mat))
- 1.0;
}
// After t=1, continue to weight based on existing pups, new active pups, and new AS pups.
