increase premium, up to a prescribed limit.
The delta between ltc_incr_prem in this period and the last period represents the additional
period premium to clear
the last period's malus.  We multiply this by littlea_b_experience to quantify all the future
premiums expected to be received,
and again by pv_period_im because ltc_incr_prem is per-period and not annual. */
if (prod_code == LTC)
premadj = (ltc_incr_prem(t) - ltc_incr_prem(t-1)) * littlea_b_experience(t) * pv_period_im;
return oldbonus + newbonus + premadj;
/*
DC 29/1/14  - Picks up the bonus indicator from the scalar bonus_malus_ind rather than from
the
variable bonus_malus.
ES 17/11/14 - Tidied formula.
DC 13/4/16  - For LTC at t=0, where the switch is on, takes the bonus from data and replaces
what
has been calculated before that point.
OS 17/8/16  - CR70  Type comparison correction - changed ltcsa_on_data_sw type to int
OS 01/09/16 - CR62 part A -  divide the bonus data by bonus reserve percent
OS 05/09/16 - CR62 PART E - changed indicator :sa_on_data_ind to be the indicator  :
res_grossup_ind
OS 07/12/16 - CR80 part A - calculate bonus b plus premium adjustment for LTC products.
OS 25/01/17 - CR119 remove restriction on res_grossup_ind in the condition of t==0
*/

/* Reports value of discount from premium */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if  (t > 0 && premium_cancel == 1)
return 0.0;
return basic_prem(t) * prem_disc_perc(t) * (1.0 + prem_subannual_rt)
/ pv_period_im * poli_avg(t);
/*
ES 17/11/2014 - Tidied formula.
OS 30/08/2016 - CR#64,75,77 - reporting columns for solvency II
*/

/* Reporting loadings on premiums received */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t > 0 && premium_cancel == 1)
return 0.0;
if (prod_code_sub == PHIVP)
return
//pol fee
((policy_fee * policy_fee_id) * (1.0 + prem_subannual_rt) +
//prem frequ loading
basic_prem(t) * (1 - prem_disc_perc(t)) * prem_subannual_rt +
// expense loading on risk premium (diff between gross and net premium rates discounts = loss of
loading (may lead to
expense_ldg * basic_prem(t) -
basic_prem(t) * (prem_disc_perc(t))*(1.0 + prem_subannual_rt)) /
// total overall negative loading)
pv_period_im * poli_avg(t);
double grossup_fac;
if (prod_code == LTC)
grossup_fac = (1.0 - net_prem_rate_b(commence_period_w+1) /
ltc_vectors_prem_rates);
else grossup_fac  = expense_ldg;
return
//pol fee
(( policy_fee * policy_fee_id) * (1 + prem_subannual_rt) +
//tarr expenses for migs
(1 -  policy_fee_id) * tarr_expenses(t) * basic_prem(t) +
//prem frequ loading
basic_prem(t) * (1 - prem_disc_perc(t)) * prem_subannual_rt +
// expense loading on risk premium (diff between gross and net premium rates
grossup_fac * basic_prem(t)  *(1.0 -   prem_disc_perc(t)) -
//discounts = loss of loading (may lead to total overall negative loading)
basic_prem(t) * (prem_disc_perc(t)) * (1.0 + prem_subannual_rt)) /
pv_period_im * poli_avg(t);
/* DC 29/10/13 - removed commented out code and tidied formula.  Set LTC grossup_fac formula to
take premium
rates from the new ltc_vectors_prem_rates table rather than from mortality_tbl.
ES 17/11/14 - Tidied formula.
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
*/
/* Reporting column */

/* Returns the value of the actual premium received */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if  (t > 0 && premium_cancel == 1)
return 0.0;
return (basic_prem(t) * (1.0 - prem_disc_perc(t)) + policy_fee * policy_fee_id)
//policy_fee_id(prod_code_sub)
* (1.0 + prem_subannual_rt) / pv_period_im * poli_avg(t);
/* ES 17/11/2014 - Tidied formula.
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (savings_prod_ind || prod_code == CLSAVINGS) {
if (abs(pups_if_b(t)) < SMALL_DOUBLE)
return 0.0;
return pup_res_bal_b(t)  * (1.0 + inv_ret_bonus_pup_pre(t) / 2.0)
* pow(1.0 + claim_infl_rt, duration_b(t) + 1.0 / pv_period_im -
elapsed_years)
//claim_infl_rt(prod_fund_name)
* pups_clm(t) / pups_if_b(t);
}
// Other products (non-ADIF or MIG)
//Klassi after maturity
if (klassi_prod_ind && t > maturity_period_w){
if (t == 1 && age_exact_issue + elapsed_years > maturity_age)
return surrender_value_postmat(t) * pups_clm(t);
return (surrender_value_postmat(t) + surrender_value_postmat(t-1)) / 2.0 //Half-period
interest
* pups_clm(t) ;
}
if (abs(sum_assured_init_model) < SMALL_DOUBLE)
return 0.0;
return sum_assured_basic_b(t)
* pow(1.0 + claim_infl_rt, duration_b(t) + 1.0 / pv_period_im - elapsed_years)
//claim_infl_rt(prod_fund_name)
* pups_clm(t) * pups_avg_value(t)
/ sum_assured_init_model;
/* DC 4/8/14  - added claims inflation adjustment; tidied formula
DC 1/11/15 - Changed prod_code lookups to enumerated variables
DC 13/4/16 - Replaced calculated SA (basic prem / GPR ) with a link to the scalar
sum_assured_init_model.
Changed the div/0 check line to refer to sum_assured_init_model.
OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 28/09/16 replace the condition term eith the scalar savings_prod_ind
NB 14/01/24 - CR349 - Corrected CLSAVINGS to take reserve as death payment, simplified
savings_prod_ind as TRUE instead of == 1, Add code for Klassi claims after maturity
*/

/* Per-policy expenses on paid-up policies in period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return exp_ren_per_pup_pol_tbl * tariffs_count * expense_ren_pp_mult * pups_if_b(t) / pv_period_im
* expenses_mult
* exp_infl_factor(t);
/* DC 22/12/14 - Tidied formula
DC 3/1/16   - Changed lookup from old table variable exp_per_pol_infl to new expenses_tbl
OS 22/2/17  - Added multiply by expenses_mult for LAT MAD calculations
OS 26/2/17  - CR131 - Added multiply by expenses inflation factor for all expenses (other than
initial expenses)
GA 15/4/17  - CR155 - Renamed from pup_expenses for clarity
GA 20/01/19  - CR260 - exp_ren_per_pup_pol insted of exp_ren_per_act_pol
*/

/* Cash payments at maturity from the paid-up portion */
if (t < commence_period_w+1 || t < maturity_period_first_w || t > maturity_period_last_w)
return NO_AVG;
if (maturity_pay == 0)
return NO_AVG;
if (prod_code == ADIF ||
prod_code == ADIF92  ||
prod_code == ADIFOLD ||
prod_code == CLSAVINGS)
return (1.0 - annuity_perc_mat(t))
* (pup_res_bal_b(t) * (1.0 + inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t) - pup_clm_paid(t) -
pup_surr_paid(t))
* (1.0 + inv_ret_bonus_pup_pre(t) / 2.0))
* gimla_ret_prob_b(t+1);
if (prod_code == MIGM || prod_code == MIGP || prod_code == MIGLIFE) {
double persistency_bonus = 1.0;
if (prod_year == 2006)
persistency_bonus = 1.0 + mig_eff_bonus * duration_b(t)
* 0.5
*
mig_duration_fact
*
annuity_perc_mat(t);
return persistency_bonus * (1.0 - annuity_perc_mat(t))
* (pup_res_bal_b(t) * (1.0 +
inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t) -
pup_clm_paid(t)
- pup_surr_paid(t)
/ sv_mult_prod *
100.0)
//sv_mult(poli_year(t), prod_code)
* (1.0 + inv_ret_bonus_pup_pre(t)
/ 2.0))
* gimla_ret_prob_b(t+1);
}
// Remaining products
//After maturity, get surrender_value_postmat
if (t > maturity_period_w)
return (1.0 - annuity_perc_mat(t))
* maturity_pay * pups_matd(t)
* surrender_value_postmat(t);
//Before maturity, get same as at surrender
if (t < maturity_period_w)
return (1.0 - annuity_perc_mat(t))
* pup_res_bal_b(t)
//
/ pups_if_b(t)// To remove
* (1.0 + inv_ret_bonus_pup_pre(t)) // Add full period of interest
//
* pups_matd(t) //To remove
//To add: * gimla_ret_prob_b(t+1)
* gimla_ret_prob_b(t+1);
//Claim at maturity date
return (1.0 - annuity_perc_mat(t))
* (maturity_pay * pups_matd(t)
* pups_reserve(t)
/ sum_assured_basic_b(t)
* pups_avg_value(t)
- (pups_if_b(t) + pups_new(t)) * pup_fee / pv_period_im)
//Add value from full pup at maturity
+ (1.0 - annuity_perc_mat(t))
* maturity_pay * pups_new(t) * gimla_ret_prob_b(t+1)
* (surrender_value_b(t) + bonus_b(t));
/* RR ?date - Added first maturity_pay condition to prevent div0 for RISKM
DC 17/11/14 - Extensive tidying of formula, including: (i) Added clause at start to return 0
outside
of maturity period; (ii) Removed the distinction between what to do
when cash1 >0 and
when cash1 <=0 - this was the same other than multiplying by (1 -
annuity%(t)) in the
former case - but annuity%(t) will be zero when cash1 <= 0.
DC 25/11/14 - Now picks up the scalar annuity_perc_mat instead of the (deprecated) column
annuity_percent.
DC 1/11/15  - Changed prod_code lookups to enumerated variables
OS 11/12/16 - added multipling in gimla_ret_prob in the two first returns.
OS 13/12/16 - CR106 - part C - removed check condition
OS 09/01/17 - CR106 part L - tidied formula.
NB 09/02/22 - CR341 - Changed prod_codes for Adif
NB 14/01/24 - CR349 - Corrected CLSAVINGS to take reserve as maturity value, Added code for
Klassi maturities pre- and post-maturity, and active from maturity period
*/

/* Start-period paid-up reserve */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// At t=1, compares data reserve to calculated reserves. Puts any discrepancy into this PUP reserve
if
//  either: (i) not an ADIF/MIG/LTC product; or (ii) a paid-up ADIF/MIG product.
if (t==1) {
bool do_transfer = false;
if (prod_code == LTC) {
if (res_grossup_ind == 0)
do_transfer = true;
}
else if (pup_mult == 1)
do_transfer = true;
else if (savings_prod_ind == 1) {
if (abs(sav_a_accm(t-1) + sav_b_accm(t-1)) < SMALL_DOUBLE)
do_transfer = true;
}
else do_transfer = true;
if (do_transfer) {
return pup_res_bal_e(t-1)
+ (current_reserve * reserve_adj)
- (res_bal_b(t) + as_res_b(t) + pup_res_bal_e(t-1));
}
}
return pup_res_bal_e(t-1);
/* DC 09/12/14 - Tidied formula
DC 01/11/15 - Removed EV/AS condition
DC 01/11/15 - Changed prod_code lookups to enumerated variables
DC 03/01/16 - Restricted the t1 reserve grossup to the indicated circumstances only
DC 13/04/16 - Further restricted the t1 reserve grossup to not apply to active LTC policies
where the
SA from data switch is on.
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 05/09/16 - CR62 PART E - changed indicator :sa_on_data_ind to be the indicator  :
res_grossup_ind
OS 28/09/16 - replace the condition term eith the scalar savings_prod_ind
GR 21/01/19 - CR261 Removed gimla prod classification
MG 02/02/20 - CR304 - switched order of if-else statement so that LTC products are also
accounted for
MG 06/02/20 - CR115 - removed condition that zillmerised for production < 1999.
*/

/* PUP Reserve balance at end of period, including linear release of fictional reserves */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if ((!gimla_prod_ind)
&& abs(pups_if_b(t+1) + pups_new(t+1)) < SMALL_DOUBLE)
return pup_res_bal_e_prelim(t) * (maturity_period_last_w - t) / maturity_period_last_w;
return pup_res_bal_e_prelim(t);
/* DC 09/12/14 - Tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
GR 21/01/19 - CR261 - Changed gimla prod classification
*/

/* Paid-up reserve at end of period, after survivorship. */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if ((gimla_prod_ind)
&& t == maturity_period_last_w)
return 0.0;
if (klassi_prod_ind && t >= maturity_period_w)
return pups_if_b(t+1) * surrender_value_postmat(t);
if (abs(pups_avg_value(t)) <= SMALL_DOUBLE
|| prod_code == ADIF     ||
prod_code == ADIF92   ||
prod_code == ADIFOLD  || prod_code == CLSAVINGS)
return pup_res_bal_b(t) * (1.0 + inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t)- pup_clm_paid(t) - pup_surr_paid(t))
* (1.0 + inv_ret_bonus_pup_pre(t)/2.0)
- pup_maturities_paid(t)
- pup_maturities_togimla(t)
- (pups_if_b(t) + pups_new(t)) * pup_fee / pv_period_im;
if (prod_code == MIGM || prod_code == MIGP || prod_code == MIGLIFE)
{
double persistency_bonus = 1.0;
if (prod_year == 2006)
persistency_bonus = 1.0 + mig_eff_bonus * duration_b(t)
* 0.5
*
mig_duration_fact
*
annuity_perc_mat(t);
return  pup_res_bal_b(t) * (1.0 + inv_ret_bonus_pup_pre(t))
+ (sv_of_pups(t) + as_pup(t) - pup_clm_paid(t)
- pup_surr_paid(t) / sv_mult_prod * 100.0)
* (1.0 + inv_ret_bonus_pup_pre(t)/2.)
- pup_maturities_paid(t) / persistency_bonus
- pup_maturities_togimla(t) / persistency_bonus
- (pups_if_b(t) + pups_new(t)) *  pup_fee / pv_period_im;
}
// Remaining cases
return pups_if_b(t+1) * pups_reserve(t)
/ sum_assured_init_model
* pups_avg_value(t)
- (pups_if_b(t) + pups_new(t)) * pup_fee / pv_period_im;
/* DC 17/11/14 - tidied formula
DC 01/11/15 - Changed prod_code lookups to enumerated variables
DC 13/04/16 - Replaced calculated SA (basic prem / GPR * PRF) with a link to the scalar
sum_assured_init_model
OS 31/07/16 - Changed line 10 : comparison to SMALL DOUBLE instead of 0
OS 11/12/16 - Added the subtraction of the amount going to gimla (accum_at_mat_pup)
OS 13/12/16 - CR106 part C - replaced the condition that checks if gimla_ret_prob(t+1)=1 with a
condition of t==maturity_period_last_w
OS 12/01/17 - CR106 part N2 - Added persistency bonus to MIG products calculation
GR 21/01/19 - CR261 - Changed gimla prod classification
NB 09/02/22 - CR341 - Changed prod_codes for Adif
NB 31/12/23 - CR349 - Set to surrender_value_postmat for Klassi policies after maturity
*/

if (t < commence_period_w+1 || t > maturity_period_last_w || reservecomm_tableread)
return NO_AVG;
if (abs(pups_if_b(t)) < SMALL_DOUBLE || poli_year(t) < comm_pup_res_newprods_first_yr)
return 0.0;
return pup_res_bal_e(t) *  pup_res_comm_newprods_rate_agencygove(t)
* vat_mult(t) / pv_period_im;
