every preiod
*/

if (reservecomm_tableread)
return NO_AVG;
if (valn_year + proj_yr(t) > comm_pup_res_newprods_lastcalyear)
return 0.0;
int cutoff = comm_pupsres_yr_newprods;
if (prod_year <= cutoff || prod_fund_name == KESHET_PRE13 || prod_fund_name == KESHET_POST13)
return 0.0;
return comm_pup_res_newprods_agencygove_rate;
