OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
GA 02/02/21 - CR324 - Droping and/or Adding switches.  Adding comm_res_perc_agency where rates are
taken from data.
Droping the duration Adj In order to calculate this column every period
ADIF policies get reserve commission from tables because there is no automisation foe them in the
data
NB 09/02/22 - CR341 - Changed prod_codes for Adif
GA 24/12/24 - CR482 - Adjusting the code for ADIF policies, to take the commission on the reserve
from the input file instead from tables
*/

if (t < commence_period_w+1 || t > maturity_period_last_w || reservecomm_tableread)
return NO_AVG;
if (abs(pups_if_b(t)) < SMALL_DOUBLE)
return 0.0;
double rate = mgt_fee_res_rate_pup(t) * comm_res_perc_mgtfee_agent3 + comm_res_perc_agent3;
return pup_res_bal_e(t) * rate * vat_mult(t) / pv_period_im;
/*
DC 8/4/13
For runs where rates are taken from data, reserve commission to  agent 2 is a percentage of the
reserve
management fee.  In other runs it is not calculated.
OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
GA 02/02/21 - CR324 - Droping and/or Adding switches.  Adding comm_res_perc_agency where rates are
taken from data.
Droping the duration Adj In order to calculate this column every period
ADIF policies get reserve commission from tables because there is no automisation foe them in the
data
NB 09/02/22 - CR341 - Changed prod_codes for Adif
GA 24/12/24 - CR482 - Adjusting the code for ADIF policies, to take the commission on the reserve
from the input file instead from tables
*/

if (t < commence_period_w+1 || t > maturity_period_last_w || reservecomm_tableread)
return NO_AVG;
if (abs(pups_if_b(t)) < SMALL_DOUBLE)
return 0.0;
double rate = mgt_fee_res_rate_pup(t) * comm_res_perc_mgtfee_super_agency +
comm_res_perc_super_agency;
return pup_res_bal_e(t) * rate * vat_mult(t) / pv_period_im;
/*
DC 19/2/13
For runs where rates are taken from data, reserve commission to the agency is a percentage of the
reserve
management fee.  In other runs it is not calculated.
OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
GA 02/02/21 - CR324 - Droping and/or Adding switches.  Adding comm_res_perc_agency where rates are
taken from data.
Droping the duration Adj In order to calculate this column every period
ADIF policies get reserve commission from tables because there is no automisation foe them in the
data
NB 09/02/22 - CR341 - Changed prod_codes for Adif
GA 24/12/24 - CR482 - Adjusting the code for ADIF policies, to take the commission on the reserve
from the input file instead from tables
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (abs(pups_if_b(t)) < SMALL_DOUBLE)
return 0.0;
if (klassi_prod_ind && t > maturity_period_w)
return (surrender_value_postmat(t) + surrender_value_postmat(t-1)) / 2.0 //Half-period
interest
* pups_surr(t) ;
double a =  pup_res_bal_b(t) * pups_surr(t) / pups_if_b(t)
* (1.0 + inv_ret_bonus_pup_pre(t)/2.);
if (surr_charge_pups == 0.0)
return a;
else
return a * sv_mult_prod/100.;
//sv_mult(poli_year(t),prod_code)
/*
OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
and changed surr_charge_pups type to int
NB 31/12/23 - CR349 - Surrender value for Klassi post-maturity
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if ((fabs(pups_if_b(t)) < SMALL_DOUBLE) && (fabs(pups_new(t)) < SMALL_DOUBLE))
return 0.0;
//Take the sum assured directly from the input for LTC PUP policies.
if ((t == 0 || t == 1) && prod_code == LTC && pup_mult == 1 && sa_on_data_ind)
return sum_assured_init_data;
double return_scale = 1.0;
if (par_nonpar == "Par" && prod_code == LTC)
return_scale = 1.0 + inv_ret_bonus_pup_pre(t-1)
- (pow(1.0 + tariff_int_rate, 1.0 / pv_period_im) - 1.0);
double SV_scale = 1.0;
if (!(abs(surrender_value_b(t)) < SMALL_DOUBLE))
SV_scale = surrender_value_b(t);
double bonus_scale = 0.0;
if (t==1 || pup_value_b(t-1) < pup_low_sa) {
if (abs(pups_new(t)) < SMALL_DOUBLE)
bonus_scale = 1.0 + (bonus_b(t) + pup_res_bal_b(t)) / SV_scale;
else bonus_scale = 1.0 + (bonus_b(t) + pup_res_bal_b(t) / pups_new(t)) / SV_scale;
}
else bonus_scale = 1.0 + bonus_b(t) / SV_scale;
double amt_scale = 1.0;
if (!(abs(pups_if_b(t) + pups_new(t)) < SMALL_DOUBLE))
amt_scale = amt_scale / (pups_if_b(t) + pups_new(t));
if ((t==1 || pup_value_b(t-1) < pup_low_sa) && pups_new(t-1) >= 1.0) {
amt_scale = amt_scale * pup_res_bal_b(t);
if (pup_res_bal_e(t-1) != 0.0)
amt_scale = amt_scale / pup_res_bal_e(t-1);
}
return (pups_avg_value(t-1) * return_scale * pups_if_b(t)
+ pups_new(t) * pup_value_b(t) * bonus_scale)
* amt_scale;
/* DC 09/02/14 - tidied up, removed commented-out code - no other changes to formula
DC 01/11/15 - removed EV/AS condition
DC 01/11/15 - Changed prod_code lookups to enumerated variables
DC 11/11/15 - Restructured formula, no change to result
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
and pups_new(t-2) >= 1.0 instead of >=1
OS 21/08/16 - CR71 - added check for madad_factor
MG 30/01/20 - CR304 - added condition in calculation of LTC PUP SA to take directly from data
MG 20/9/23  - CR444 - Changed the amt_scale to be conditioned on pups_new(t-1) instead of
pups_new(t-2)
*/

/* Number of paid-ups claiming in the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
// For risk and savings products, the claim event is death, and so we return the death decrement
if (death_is_clm_ind)
return pups_death(t);
// For all other products, there is a separate decrement for claims from that of death
if (duration_b(t) < elapsed_years)
return 0.0;
double rate = 0.0;
if (prod_code == HO || prod_code == PERS_ACC) {
rate = briut_vectors_clm_costs
* select_factor_clm
* mort_params_mult_base
* morbid_trend_fac
* 1.0/prem_rate_factor
/ pv_period_im;
return (pups_if_b(t) + (pups_new(t)-pups_surr(t)-pups_death(t))/2.0)
* rate;
}
// LTC incidence rates come from a different table to other products' claim rates
if (prod_code == LTC)
rate = ltc_vectors_inci_rates * ltc_inci_pup_mult * ltc_morb_impr_fac;
// PHI incidence rates also come from a different table, and are adjusted for the
//  discrepancy between the theoretical and actual professional loadings.
//  Even though PHI does not have PUPs, it does have premium reductions and so this code is used.
else if (prod_code == PHI){
double occ = avg_occ_load/100;
if (prod_fund_name == PHIFP_MH || prod_fund_name == PHIFP_SHLV || prod_fund_name ==
PHIVP_17 || prod_fund_name == PHIVP_MH || prod_fund_name == PHIVP_SHLV)
occ = phi_occ_add / 100;
if (sa_on_data_ind)
rate = phi_vectors_inci_rates * phi_mpa_factors * umbclmmult // מטריה עבור הכפלה
* (1.0 + prem_ldg_prof_theo_pc) / (1.0 + prem_ldg_prof_act_pc)
* (1.0 + avg_mort_load/100) * (1.0 + occ) * phi_incidence_loading;
else
rate = phi_vectors_inci_rates * phi_mpa_factors * umbclmmult *
phi_incidence_loading; // מטריה עבור הכפלה
}
else if (prod_code == DD){
if(sa_on_data_ind)
rate = briut_vectors_clm_costs
* (1.0 + avg_mort_load/100) * (1.0 + avg_occ_load/100);
else
rate = briut_vectors_clm_costs;
}
else if (prod_code == ADIS)
rate = mort_tbl_ageexact_adis;
else {
log_strm << "Primary key " << primary_key << " - unrecognised product in pups_clm" << endl;
throw NonFatalError("");
}
// Apply scalars and sensitivies and convert to a period rate
rate = 1.0 - pow(1.0 - (rate * select_factor_clm
* mort_params_mult_base
* morbid_trend_fac)
* (1.0/prem_rate_factor)
, 1.0 /pv_period_im);
// For PHI only, multiply by the claim duration
if (prod_code == PHI)
rate = rate * (phi_vectors_clm_durs + phi_franchiza_mths);
return (pups_if_b(t) + (pups_new(t)-pups_surr(t)-pups_death(t))/2.0)
* rate;
/* DC 29/10/13 - changed source of LTC incidence rates to come from the new ltc_vectors_inci_rates
table rather than from mortality_tbl.  Tidied formula and removed commented out code.
DC 03/08/14 - changes to PHI code (applies here to premium reductions rather than straight
PUPs):
rather than reading a combined claim rate, it first reads the incidence rate, then applies
the
loadings adjustment, then applies the senstivities, then multiplies by claim duration.
DC 07/10/14 - moved the lookup of morbid_trend_fac from prod_code to prod_fund_name.
ES 29/12/14 - Replaced clause of "SURG OR HR" with clause of "HO or PERS_ACC"; changed their
lookup
from mortality_tbl to briut_vectors_clm_costs.
Separated out lookup of DD rates to also be from
briut_vectors_clm_costs.
Moved the lookup of mort_sel_per from prod_code to prod_code_sub
DC 01/11/15 - Now looks up select years from the new scalar mort_params_select_yrs
DC 01/11/15 - Changed prod_code lookups to enumerated variables
OS 06/09/16 - added  phi_mpa_factors to phi_incidence rate according to PRAT ATZMAI MANAGER
OS 07/12/16 - for LTC products - added multiply in ltc_inci_pup_mult (CR80 part b)
OS 12/11/17 - CR101 - Changed conditions with PHI new hierarchy
DC 21/06/18 - CR232 - Added Francisa months to the claim duration for PHI
DC 31/12/18 - CR247 - For risk/savings products, now returns pol_clm
Removed other usages of death_clm_indicator and mortality
factors, including war risk
Select adjustment now comes as a factor rather than as
a number of years
OS 01/01/18 - CR250 - Added in LTC morbidity improvement factor
DC 14/02/19 - CR267 - changed the lookup for ADIS, and added error trapping for other products
SK 05/08/21 - CR356 - Deleting 'makeRunLogYellow()' and 'skipModelPoint()', instead we added
'throw NonFatalError("")'
GA 18/01/22 - CR354 - Adding Tosafot from the input to the claims prob (since we now take the
real SA from the input, and not the inflated one)
NB 24/11/24 - CR483 - New multipliers added to PHI
*/

/* Returns number of death terminations from paid-up policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (duration_b(t) < elapsed_years)
return 0.0;
double rate = 0.0;
double ltc_impr_fac = 1.0;
if (prod_code == LTC)
ltc_impr_fac = ltc_mort_impr_fac;
if (age_exact_b(t) < mort_oldage_startage)  // standard mortality
rate= 1.0 - pow(1.0 - 0.001 * (mort_tbl_ageexact_poldthname
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ mort_vol_fac +
mort_warrisk_addn)
, 1.0 / pv_period_im);
else  // gimla mortality
rate = (1.0 - pow(1.0 - (gimla_mortality_table
* select_factor_dth
* mort_trend_fac
* ltc_impr_fac
+ 0.001 * mort_vol_fac
+ 0.001 * mort_warrisk_addn),
1.0 / pv_period_im))
* gimla_mort_mult_sex1;
return (pups_if_b(t) + (pups_new(t) - pups_surr(t)) / 2.0) * rate;
/* DC 23/12/14 - Tidied formula
ES 01/02/15 - added a condition so that if the age is equal to or greater than
mort_old_startage, it uses
gimla mortality instead of standard mortality.
DC 31/12/18 - CR247 - now reads a select factor rather than calculating it from a select period
- removed unused variable dth_decr_clm_mult
OS 01/01/19 - CR250 - Added in LTC improvement factor
*/

/* Number of paid-ups in force at the start of the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return pups_if_b(t-1) + pups_new(t-1)
- pups_surr(t-1)
- pups_death(t-1)
- pups_clm(t-1) * decrem_after_clm
- pups_matd(t-1);
/* DC 23/12/14 - Tidied formula
*/

/* Number of paid-ups coming to maturity at the end of the period */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t >= maturity_period_first_w)
return (pups_if_b(t) + pups_new(t)
- pups_surr(t)
- pups_death(t)
- pups_clm(t) * decrem_after_clm)
* gimla_ret_prob_b(t+1);
return 0.0;
/* DC 9/12/14 - Tidied formula
*/

/* Number of new paid-ups in the period, whether from full pups or from premium reductions */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return pol_pupd(t) + pol_prem_reduct(t);
/* DC 23/12/14 - Tidied formula
*/

if (t < commence_period_w+1 || t > maturity_period_last_w+1)
return NO_AVG;
if (savings_prod_ind == 1 || prod_code == ANPY)
return 0.0;
if (prod_code == ENDM92 || prod_code == ENDP92 || prod_code == END) {
if (t < maturity_period_last_w+1-pv_period_im)
return (biga_e(t+1) * (1.0 - poli_period(t+1)) + biga_e(t+pv_period_im+1) *
poli_period(t+1))
* sum_assured_basic_b(t);
else
return (biga_e(t+1) * (1.0 - poli_period(t+1)) + biga_e(maturity_period_last_w+1) *
poli_period(t+1))
* sum_assured_basic_b(t);
}
// Other products
if (t < maturity_period_last_w+1 - pv_period_im)
return (biga_e(t+1) * (1.0 - poli_period(t+1)) + biga_e(t+pv_period_im+1) *
poli_period(t+1))
* sum_assured_init_model;
return (biga_e(t+1) * (1.0 - poli_period(t+1)) + biga_e(maturity_period_last_w+1) *
poli_period(t+1))
* sum_assured_init_model;
/* DC 9/12/14 - Tidied formula
DC 1/11/15 - Changed prod_code lookups to enumerated variables
AH 4/11/15 - Removed clause for ANPY and zeroed it out instead
DC 13/4/16 - Replaced calculated SA (basic prem / GPR * PRF) with a link to the scalar
sum_assured_init_model
OS 28/09/16 replace the condition term eith the scalar savings_prod_ind
OS 14/12/16 - CR106 part E - changed any reference to maturity_period_w to instead be to
maturity_period_last_w
*/

/* Period amount of full surrenders from paid-up policies */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
if (t == commence_period_w)
return 0.0;
// For gimla products after a set age, these lapses are already included in the take-up rates,
//    so we zero here to avoid double counting
if (gimla_prod_ind && age_exact_b(t) >= lapsecancel_age)
return 0.0;
// Calculate lapse rate for year
double rate = pup_surr_rate;
// pup_surr_rate(poli_year(t), lapse_group(prod_fund_name))
if (klassi_prod_ind){
if (t < maturity_period_w - 2)
rate = pup_surr_rate_klassi;
if (t <= maturity_period_w + 2 && t >= maturity_period_w - 2)
rate = surr_rate_klassi_mat;
if (t > maturity_period_w + 2)
rate = surr_rate_klassi_postmat;
}
rate = (1.0 - pow((1.0 - min((rate + lapse_shock_factor)
//lapse_shock_factor(prod_fund_name,proj_yr(t))
* lapse_scaling_factor * lapse_scaling_factor_pupres, 0.99999999)),
1.0/pv_period_im));
return pups_if_b(t) * rate;
/*
DC 24/1/13  - added in lapse_scaling_factor_pupres as an additional multiplier
DC 6/4/14   - changed lapse_group and lapse_shock factor lookups to be by prod_code_sub and not
prod_code.  Removed commented-out code
DC 30/4/14  - changed lapse_group and lapse_shock factor lookups to be by prod_fund_name and not
prod_code_sub
DC 1/2/16   - zeroed out these lapses for gimla products post-age60
DC 1/3/16   - set the zeroing out condition to be in relation to a table age rather than fixed 60
OS 28/09/16 - replaced column lapse_scale_fac to get the value directly from  the variable
lapse_scaling_factor
DC 15/8/17  - CR156 - condition is now based on gimla_prod_ind rather than nogimla_prod_ind
NB 31/12/23 - CR349 - Surrender rates for Klassi set to reference Klassi table rather than standard
table
*/

if (t < commence_period_w+1 || t > maturity_period_last_w && prod_code != ANPY)
return NO_AVG;
return current_reserve * reserve_adj;
//reserve_adj(par_nonpar,1)
/*
DC 21/12/14 - Tidied formula
OS 15/01/17 - Added ANPY to condition in order to calculate the data reserve for ANPY
*/

/* Increase in the pre-retirement Feff reserve, net of RF interest */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w || !gimla_prod_ind)
return NO_AVG;
return gimla_feff_res_e_pre(t)
- gimla_feff_res_e_pre(t-1) * (1.0 + inv_ret_gross_hetz_incl_pre(t));
/*
DC 18/02/18 - CR206 - created column
*/

/* Total claims in the period, including gimla payments */
if (t < commence_period_w+1)
return NO_AVG;
if (!gimla_prod_ind) {
if (t > maturity_period_last_w)
return NO_AVG;
return claims_paid(t) + suppliers_claims_expense(t) + pup_clm_paid(t) +
suppliers_pup_claims_expense(t);
}
// For gimla products include gimla cashflows
return   claims_paid(t) + suppliers_claims_expense(t) + pup_clm_paid(t) +
suppliers_pup_claims_expense(t) + gimla_post_maturity(t);
/*
JB 12/6/10 - removed  res_clm_active(t) + res_clm_payup(t) + res_as_clm_active(t) +
res_as_clm_payup(t)
and put it tot_surr_mat as they are surrender pmts, not claims
ES 11/11/14 - Moved initial conditions check to indicator column nogimla_postmat_ind.
DC 21/12/14 - Tidied formula
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Changed the format of the formula to split the calculation for gimla and
non-gimla products
MG 06/18/24 - CR336 - added suppliers claims expense
*/

/* Returns the total of all types of expenses in the period */
if (t < commence_period_w+1)
return NO_AVG;
if (!gimla_prod_ind) {
if (t > maturity_period_last_w)
return NO_AVG;
return expenses_perc_prem(t) + expenses_per_pol(t) + as_exp(t) + pup_expenses_per_pol(t)
+ expenses_res(t) + expenses_claims(t) + pup_expenses_claims(t) +
expenses_surrs(t) + expenses_mats(t);
}
// For gimla products include gimla-related cashflows
return   expenses_perc_prem(t) + expenses_per_pol(t) + as_exp(t) + pup_expenses_per_pol(t)
+ expenses_res(t) + expenses_claims(t) + pup_expenses_claims(t) +
expenses_surrs(t) + expenses_mats(t)
+ gimla_expenses(t) + expenses_gimlaconv(t);
/* JB 28/12/10 - added expenses_res
DC 21/12/14 - Tidied formula
DC 05/01/16 - Added in claims expenses
OS 17/08/16 - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
DC 03/10/17 - CR179 - Changed the format of the formula to split the calculation for gimla and
non-gimla products
GA 28/01/19 - CR260 - Added in new expense types
GA 07/02/19 - CR265 - Added in expenses_gimlaconv
*/

/* Returns total investment income in the period*/
if (t < commence_period_w+1)
return NO_AVG;
if (!gimla_prod_ind) {
if (t > maturity_period_last_w)
return NO_AVG;
return invest_inc(t) + as_inv(t) + pup_invest_inc(t);
}
// For gimla products include gimla cashflows
return   invest_inc(t) + as_inv(t) + pup_invest_inc(t)
+ gimla_invest_inc_feff_pre(t) + gimla_invest_inc(t);
/* ES 11/11/14 - 1. Moved initial conditions check to indicator column nogimla_postmat_ind.
2. Tidied formula
AH 4/11/15  -  Removed anpy_add_res_inv_inc from equation
OS 01/01/17 - Added gimla_invest_inc_feff_pre to the sum of investment income.
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Changed the format of the formula to split the calculation for gimla and
non-gimla products
*/

/* Returns total investment income on the hetz portion */
if (t < commence_period_w+1)
return NO_AVG;
if (t > maturity_period_last_w && !gimla_prod_ind)
return NO_AVG;
return (pow(1.0 + inv_gross_hetz, 1.0 / pv_period_im) - 1.0)
* inv_pct_hetz
* (tot_res(t)+tot_res(t+1)) / 2.0 ;
/*
JB 31/12/2010 assume hetz percentage is rebalance at end of period
ES 11/11/14 - 1. Moved initial conditions check to indicator column nogimla_postmat_ind.
2. Tidied formula
OS 28/09/16 - replaced column  to get the value directly from  the variable inv_pct_hetz
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Rewrote initial conditions
*/

if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return prem_recd(t) + as_prm(t) + ltc_incr_prem_recd(t);
/*
OS 07/12/16 CR80- added ltc_incr_prem_recd to the sum (contains the increased premium to
cover the malus
*/

/* Reports the present value of all future expenses */
if (t < commence_period_w+1 || t > model_end_period)
return NO_AVG;
if (!gimla_prod_ind)
return tot_pv_exps_pre(t);
return tot_pv_exps_pre(t) + tot_pv_exps_gimla(t);
/* AZ 2/3/2010 - removed the restriction on reporting expenses after the maturity period
RR 29/12/2010 - added in expenses_res to the reporting
DC 4/11/2014 - tidied formula
AH 16/2/2016 - Added in two claims columns that have been zero until this point but will
be positive in the future.
OS 17/8/16  - CR70  Type comparison correction - changed comparison to SMALL DOUBLE
OS 28/09/16 - renamed column
OS 26/12/16 - Changed the code to sum up the pre and post maturity expenses.
DC 15/08/17 - CR156 - Changed the condition to use gimla_postmat_ind rather than
nogimla_postmat_ind
DC 03/10/17 - CR179 - Replaced use of gimla_postmat_ind with gimla_prod_ind
SK 05/08/21 - CR356 - Adding time guard for gen2 engine
*/
/* Reporting column */

/* Reports the present value of future claim expenses */
if (t < commence_period_w+1 || t > maturity_period_last_w)
return NO_AVG;
return (expenses_claims(t) + pup_expenses_claims(t) + tot_pv_exps_claims(t+1))
* v_factor_pre(t);
/* AH 16/02/16 - Created column
*/
/* Reporting column */

