int calc_maturity_period(double age)
{
if (prod_code == ANPY)
return commence_period_w;
if (age <= age_exact_issue + elapsed_years) //to deal with data points where current age > maturity
age
return max(commence_period_w + elapsed_years * pv_period_im, 2);
return commence_period_w + (age - age_exact_issue) * pv_period_im;
