savings policies
*/
}

void create_submodel_array(void)
{
// Set the number of maslulim.  For older savings products this should be 5.  For newer savings and
ANPY, 1.  For other products, 0.
int maslul_no = 0;
if (savings_prod_ind || klassi_prod_ind) {
if (prod_fund_group_post <= 10)
maslul_no = 5;
else maslul_no = 1;
}
else if (prod_code == ANPY)
maslul_no = 1;
sm_maslul.resize(maslul_no);
int ret_ages_range;
double mat_age;
// For savings products with an age distribution:
if (gimla_retagedistr_use == 1) {
ret_ages_range = max(gimla_lastretage - gimla_firstretage + 1, 1);
mat_age = gimla_firstretage;
}
else if (savings_prod_ind || klassi_prod_ind || prod_code == ANPY) { // Savings without
distribution, and ANPY
ret_ages_range = 1; // 2nd dimension is set to 1
if (klassi_prod_ind && gimla_firstretage_tbl == gimla_lastretage && age_exact_issue +
elapsed_years > gimla_lastretage)
mat_age = xint(age_exact_issue + elapsed_years) + 1; //Next birthday
else {
if (age_exact_issue + elapsed_years < maturity_age)
mat_age = maturity_age; // using maturity age from the data
else
mat_age = xint(age_exact_issue + elapsed_years) + 1; //Next birthday
}
}
else { // all other products
ret_ages_range = 0; // 2nd dimension is set to 0
mat_age = 0; // maturity age is 0
}
// Set the second dimension of the sub-model array to be the number of retirement ages
for(int i = 0; i < maslul_no; i++)
sm_maslul[i].resize(ret_ages_range);
// For older savings products, set the properties of each of the five maslulim
if ((savings_prod_ind || klassi_prod_ind) && prod_fund_group_post <= 10) {
for(int j = 0; j < ret_ages_range; j++){
xstring mas_name = "JL_100";
sm_maslul[JL_100][j]->setGroup(mas_name+"_"+xstring(mat_age + j));
sm_maslul[JL_100][j]->maslul_name = mas_name;
sm_maslul[JL_100][j]->maturity_age_sub =  mat_age + j;
sm_maslul[JL_100][j]->maturity_period_sub =  calc_maturity_period(mat_age + j); //
calculate from mat_age
mas_name = "JL_60";
sm_maslul[JL_60][j]->setGroup(mas_name+"_"+xstring(mat_age + j));
sm_maslul[JL_60][j]->maslul_name = mas_name;
sm_maslul[JL_60][j]->maturity_age_sub =  mat_age + j;
sm_maslul[JL_60][j]->maturity_period_sub =  calc_maturity_period(mat_age + j);
mas_name = "SL_0";
sm_maslul[SL_0][j]->setGroup(mas_name+"_"+xstring(mat_age + j));
sm_maslul[SL_0][j]->maslul_name = mas_name;
sm_maslul[SL_0][j]->maturity_age_sub =  mat_age + j;
sm_maslul[SL_0][j]->maturity_period_sub =  calc_maturity_period(mat_age + j);
mas_name = "SL_10";
sm_maslul[SL_10][j]->setGroup(mas_name+"_"+xstring(mat_age + j));
sm_maslul[SL_10][j]->maslul_name = mas_name;
sm_maslul[SL_10][j]->maturity_age_sub =  mat_age + j;
sm_maslul[SL_10][j]->maturity_period_sub =  calc_maturity_period(mat_age + j);
mas_name = "SL_5";
sm_maslul[SL_5][j]->setGroup(mas_name+"_"+xstring(mat_age + j));
sm_maslul[SL_5][j]->maslul_name = mas_name;
sm_maslul[SL_5][j]->maturity_age_sub =  mat_age + j;
sm_maslul[SL_5][j]->maturity_period_sub =  calc_maturity_period(mat_age + j);
}
}
// For ANPY, we only need to set up one maslul, and don't loop the retirement age
else if (prod_code == ANPY) {
xstring mas_name = anpy_maslul;
sm_maslul[0][0]->setGroup(mas_name+"_"+xstring(mat_age));
sm_maslul[0][0]->maslul_name = mas_name;
sm_maslul[0][0]->maturity_age_sub =  mat_age;
sm_maslul[0][0]->maturity_period_sub =  calc_maturity_period(mat_age);
}
// For anything else, we only set up SL_20, but do loop the retirement age
else {
for(int j = 0; j < ret_ages_range; j++){
xstring mas_name = "SL_20";
sm_maslul[0][j]->setGroup(mas_name+"_"+xstring(mat_age + j));
sm_maslul[0][j]->maslul_name = mas_name;
sm_maslul[0][j]->maturity_age_sub =  mat_age + j;
sm_maslul[0][j]->maturity_period_sub =  calc_maturity_period(mat_age + j);
}
}
return;
}//end external function
