return 0.0;
// Next check if we are in the reserve rising period at the valuation date
if (duration_b(1) * pv_period_im <= res_briut_rise_periods)
return current_reserve
/ (basic_prem(commence_period_w+1) / pv_period_im
* duration_b(1) * pv_period_im
* (1.0 - (duration_b(1) * pv_period_im - 1.0)
/ (2.0 * (res_briut_rise_periods - 1.0))));
//Otherwise, at the valuation date we are in the reserve falling period
return current_reserve
* (2.0 * pv_period_im)
/ (basic_prem(1) * res_briut_rise_periods)
/ (1.0 - ((1.0 - commence_period_w - res_briut_rise_periods)
* ((duration_b(1) + duration_b(commence_period_w +
res_briut_rise_periods))
* pv_period_im
+ 1.0 - 2.0 * res_briut_rise_periods))
/ (pow(benefit_term * pv_period_im - res_briut_rise_periods, 2.0)
