/* Returns the actual investment return credited to the paid-up portion of the policy, net of
any applicable management fees or spread post maturity */
/* The decision as to whether to take variable fees is based on the bor at the START of the period.
This feeds into only the theoretical gimla payment calculation, that goes into the bor
rollup.
It is here to avoid a circular reference */
if (t < maturity_period_sub)
return NO_AVG;
if (t < 1)
return end->inv_ret_net_post(t);
if (end->prod_fund == 6)
// After maturity, the crediting rate reverts to the basic savings rate
return inv_ret_bonus_act_post_theo(t);
if (prod_fund_adj < 8)
return pow((1.0 + end->inv_non_partic_crediting_rate), 1.0 / pv_period_im) - 1.0;
// Funds 8 and above
double period = (double)t / pv_period_im;
if (period <= end->no_mgt_fees_var_period && period > 0)
return end->inv_ret_net_fxd_post(t);
// Decide whether to deduct variable fees based on the balance at the start of the period
if (mgt_fee_bal_gimpup_b(t) < SMALL_DOUBLE)
return end->inv_ret_net_fxd_post(t);
return end->inv_ret_net_post(t);
