/* Return of investments net of both fixed and partial variable management fees - post retirement
*/
if (t < maturity_period_first_w)
return NO_AVG;
if (prod_fund_adj < 8)
return pow((1.0 + end->inv_non_partic_crediting_rate), 1.0 / pv_period_im) - 1.0;
double period = (t / pv_period_im);
if (period <= end->no_mgt_fees_var_period && period > 0.0) {
if (end->prod_fund == 11) {
double cred_rate = max(pow(1.0 + end->inv_ret_gross_hetz_incl_post(t), pv_period_im)
* (1.0 - end->mgt_fees_fixed_gim) - 1.0, end-
>gimla_tariff);
cred_rate = min(cred_rate, pow(1.0 + end->inv_ret_gross_hetz_incl_post(t),
pv_period_im));
//to calc fixed gimla mgt fees only if return is greater than tariff, with a maximum
of fixed mgt fee
return pow(1.0 + cred_rate, 1.0 / pv_period_im) - 1.0;
}
else
return pow(1.0 + (pow(1.0 + end->inv_ret_gross_hetz_incl_post(t), pv_period_im)
* (1.0 - end->mgt_fees_fixed_gim) - 1.0), 1.0 / pv_period_im) - 1.0;
}
double fee_factor = 0.0;
// Case 1a: We start and end in bor
if (mgt_fee_bal_gimact_b(t) < SMALL_DOUBLE){
if (mgt_fee_bal_gimact_e(t) < SMALL_DOUBLE)
fee_factor = 0.0;
// Case 1b: We start in bor, come out within the period, and so first need to clear the bor and
then start taking management fee
else fee_factor = max(min(mgt_fee_bal_gimact_e(t) / (mgt_fee_bal_gimact_e(t) -
mgt_fee_bal_gimact_b(t)),10.0),-10.0);
}
// Case 2a: We start in odef, go into bor within the period, and so take (negative) management fee
only until the bor is cleared
else if (mgt_fee_bal_gimact_e(t) < SMALL_DOUBLE)
fee_factor = max(min(-mgt_fee_bal_gimact_b(t) / (mgt_fee_bal_gimact_e(t) -
mgt_fee_bal_gimact_b(t)),10.0),-10.0);
// Case 2b: We start and end in odef, and so take the full variable fee
else fee_factor = 1.0;
if (end->prod_fund == 11) {
double eval1 = pow(1.0 + end->inv_ret_gross_hetz_incl_post(t), pv_period_im) - 1.0;
double eval2 = pow(1.0 + end->inv_ret_gross_hetz_incl_post(t), pv_period_im)
* (1.0 - end->mgt_fees_fixed_gim) - 1.0;
double eval3 = end->gimla_tariff;
double eval4 = (eval2 - eval3) * end->mgt_fees_var * fee_factor;
double cred_rate = min(eval1, max(eval2, eval3) - max(eval4, 0));
//to calc fixed gimla mgt fees only if return is greater than tariff , with a maximum of
fixed mgt fee
return pow(1.0 + cred_rate, 1.0 / pv_period_im) - 1.0;
}
// All other mishtatef funds
return pow(1.0 + (pow(1.0 + end->inv_ret_gross_hetz_incl_post(t) , pv_period_im)
* (1.0 - end->mgt_fees_fixed_gim)  - 1.0)
* (1.0 - end->mgt_fees_var * fee_factor), 1.0 / pv_period_im) - 1.0;
