else payment = monthly_payment_internal_m_theo(t) * 12.0 / pv_period_im
* (gimla_inpayment_b(t) - gimla_if_notlife1_life2_b(t)    // 100%
where life1 is still alive
+ gimla_if_notlife1_life2_b(t) * survivor_pc);
