return monthly_payment_internal_m(t)
* (end->activ_perc(maturity_period_sub) * pow(1.0 +
inv_ret_bonus_act_post(t), per_remaining_propn)
* gimla_adjustment_rate_pd
+ (1.0 - end->activ_perc(maturity_period_sub)) * pow(1.0 +
inv_ret_bonus_pup_post(t), per_remaining_propn)
