return monthly_payment_internal_e(t-1)
* (end->activ_perc(maturity_period_sub) * pow(1.0 +
inv_ret_bonus_act_post(t), per_propn)
* gimla_adjustment_rate_pd
+ (1.0 - end->activ_perc(maturity_period_sub)) * pow(1.0 +
inv_ret_bonus_pup_post(t), per_propn)
* gimla_adjustment_rate_pd);
