The reserve is consituted when the capital payment is one.
*/
if (t < maturity_period_sub || t > model_end_period)
return NO_AVG;
if (t > maturity_period_sub && gimla_inpayment_b(t) < SMALL_DOUBLE)
return NO_AVG;
if (gimla_inpayment_b(t+1) < SMALL_DOUBLE)
return 0.0;
/* Single-life maslul calculation */
if (life_type == "single") {
// We need to calculate an annuity certain to be paid after death within the remaining
guarantee period.
// This is based on the standard (1-v^n)/i formula
double annuity_certain = 0.0;
if (t <= maturity_period_sub + gimla_gtee_yrs * pv_period_im) {
double int_res = gimla_interest_reserve;
annuity_certain = (1.0 - pow((1.0 + int_res),
- 1.0/pv_period_im * (maturity_period_sub
+ gimla_gtee_yrs * pv_period_im - t)))
/ (pow(1.0 + int_res, 1.0/12.0) - 1.0)
* pow(1.0 + int_res, 1.0/12.0);
}
// We reserve for the standard mekadem for the maslul for those still alive (this takes into
account
// any potential guarantee), and the annuity certain for those dead and benefitting from the
guarantee.
return monthly_payment_internal_e(t) / gimla_antisel_ratio
* (gimla_if_b(t+1) * ann_conv_fac_gteed(t+1) / 100.0
+ (gimla_if_b(maturity_period_sub+1) - gimla_if_b(t+1)) *
annuity_certain);
