* (gimla_if_b(per+1) * ann_conv_fac_feff(per+1) / 100.0 *
gimla_feff_antisel_postret
+ (gimla_if_b(maturity_period_sub+1) - gimla_if_b(per+1)) *
annuity_certain);
}
