// Writes the rp output file.
void write_rp_output(void)
{
//Write headers to RP output file
rp_file_stream
<< "RP,"
<< "time,"
<< "reins_delta_ALR_res,"
<< "reins_claims_paid,"
<< "reins_NPA,"
<< "reins_comm,"
<< "reins_prem,"
<< "cu_discounted_reins,"
<< "cu_sum_reins,"
<< "cu_reins,"
<< "cu_pv_reins,"
<< "reins_delta_IBNR_prem,"
<< "reins_res_int_prem,"
<< "reins_profcomm_prem,"
<< "reins_profcomm_claims,"
<< "reins_cost,"
<< "Reins_RA_CF"
<< endl;
//Collect number of treaties and number of groups
int number_of_rps = sm_treaty[0]->sm_group_treaty.size();
int number_of_groups = sm_treaty[0]->sm_group_treaty[0].size();
int number_of_reinsurers;
xstring rp;
//Temp totals
double claims_temp;
double default_claims_temp;
double phi_reins_res_inc_temp;
double comm_temp;
double prem_temp;
double profit_commission_prem_temp;
double profit_commission_claims_temp;
double cu_reins_temp;
double cu_sum_reins_temp;
double cu_discounted_reins_temp;
double cu_pv_reins_temp;
double delta_ibnr_temp;
double res_int_prem_temp;
double reins_cost_temp;
double ra_adj_temp;
double Reins_RA_CF_temp;
for (int rp_i = 0; rp_i < number_of_rps; rp_i++)//Loop through RPs
{
//Collect RP flag
rp = sm_treaty[0]->sm_group_treaty[rp_i][0]->reins_portfolio;
// Get RA adjustment for current reins portfolio
rp_cv = rp;
ra_adj_temp = ra_adj;
log_strm << "Reins portfolio: " << rp << ", Adjustment: " << ra_adj_temp << endl;
for (int t = 0; t <= last_model_period; t++) //Loop through projection periods
{
//Reset temp totals
claims_temp = 0.;
default_claims_temp = 0.;
phi_reins_res_inc_temp = 0.;
comm_temp = 0.;
prem_temp = 0.;
profit_commission_prem_temp = 0.;
profit_commission_claims_temp = 0.;
cu_reins_temp = 0.;
cu_sum_reins_temp = 0.;
cu_discounted_reins_temp = 0.;
cu_pv_reins_temp = 0.;
delta_ibnr_temp = 0.;
res_int_prem_temp = 0.;
reins_cost_temp = 0.;
Reins_RA_CF_temp = 0.;
for (int treaty_i = 0; treaty_i < sm_treaty.size(); treaty_i++)//Loop through
treaties
{
for (int group_i = 0; group_i < number_of_groups; group_i++)//Loop
through groups
{
claims_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->reinsurance_claims_ifrs(t);
default_claims_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->reinsurance_claims_ifrs(t) * (1 - sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->treaty_default_reduction_factor); //The default risk is applied
here for now.
phi_reins_res_inc_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->phi_reinsurance_res_inc(t);
comm_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->reinsurance_commissions_ifrs(t);
prem_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->reinsurance_premium_ifrs(t);
cu_reins_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->cu_reinsurance(t) / 100000.0;
cu_sum_reins_temp += sm_treaty[treaty_i]->sm_group_treaty[rp_i][group_i]-
>cu_sum_reinsurance(t) / 100000.0;
cu_discounted_reins_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->cu_discounted_reinsurance(t) / 100000.0;
cu_pv_reins_temp += sm_treaty[treaty_i]->sm_group_treaty[rp_i][group_i]-
>cu_pv_reinsurance(t) / 100000.0;
delta_ibnr_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->reinsurance_delta_ibnr_prem_ifrs(t);
res_int_prem_temp += sm_treaty[treaty_i]-
>sm_group_treaty[rp_i][group_i]->reinsurance_interest_prem_ifrs(t);
}//Loop through groups
//Number of reinsurers associated with each treaty can vary by treaty.
number_of_reinsurers = sm_treaty[treaty_i]-
>sm_reinsurer_treaty.size();
for (int reinsurer_i = 0; reinsurer_i < number_of_reinsurers;
reinsurer_i++)//Loop through reinsurers
{
profit_commission_prem_temp += sm_treaty[treaty_i]-
>sm_reinsurer_treaty[reinsurer_i]->sm_reinsurance_portfolio[rp_i]->reinsurance_prof_comm_prem(t);
profit_commission_claims_temp += sm_treaty[treaty_i]-
>sm_reinsurer_treaty[reinsurer_i]->sm_reinsurance_portfolio[rp_i]->reinsurance_prof_comm_claims(t);
}//Loop through reinsurers
}//Loop through treaties
reins_cost_temp += prem_temp - claims_temp - comm_temp -
(profit_commission_prem_temp + profit_commission_claims_temp) - phi_reins_res_inc_temp
- delta_ibnr_temp + res_int_prem_temp;
Reins_RA_CF_temp += claims_temp * ra_adj_temp;
//Write out to file
rp_file_stream << std :: fixed
<< rp << ","
<< t << ","
<< phi_reins_res_inc_temp << ","
<< claims_temp << ","
<< default_claims_temp << ","
<< comm_temp << ","
<< prem_temp << ","
<< cu_discounted_reins_temp << ","
<< cu_sum_reins_temp << ","
<< cu_reins_temp << ","
<< cu_pv_reins_temp << ","
<< delta_ibnr_temp << ","
<< res_int_prem_temp << ","
<< profit_commission_prem_temp << ","
<< profit_commission_claims_temp << ","
<< reins_cost_temp << ","
<< Reins_RA_CF_temp << ","
//Add other fields
<< endl;
}//Loop through projection periods
}//Loop through RPs
}
