// Auxiliary function - used by the function aggregate_premium
void parse_string(xstring input_string, xstring delimitor, vector<xstring> &vect)
{
xstring main_string = remove_blanks(input_string);
xstring substr = "";
int i = 0;
while (i > -1){
i = main_string.find(delimitor);
if (i > -1){
substr = main_string(0, i);
substr = remove_blanks(substr);
if (substr != delimitor && substr.length() > 0)
vect.push_back(substr);
main_string = main_string(i + 1, main_string.length());
main_string = remove_blanks(main_string);
}
else if(main_string != delimitor && main_string.length() > 0)
vect.push_back(main_string);
}
return;
}
