// Auxiliary function - used by the function parse_string
xstring remove_blanks(xstring input)
{
xstring output = "";
input = input.strip(); //remove trailing blanks
int len = input.length();
if (len > 0){
int i = input.find_first_not_of(" "); //remove leading blanks
output = input(i, input.length());
}
else
output = input;
return output;
}
